use serde::Deserialize;
use std::collections::HashMap;

fn def_message_keys() -> Vec<String> {
    vec!["short_message".to_string(), "msg".to_string(), "message".to_string()]
}
fn def_time_keys() -> Vec<String> {
    vec!["timestamp".to_string(), "time".to_string(), "@timestamp".to_string()]
}
fn def_level_keys() -> Vec<String> {
    vec!["level".to_string(), "severity".to_string(), "log.level".to_string(), "loglevel".to_string()]
}
fn def_dump_all_exclude() -> Vec<String> {
    vec![]
}
fn def_always_print_fields() -> Vec<String> {
    vec![]
}
fn def_main_line_format() -> String {
    "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}".to_string()
}
fn def_additional_value_format() -> String {
    "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}".to_string()
}

#[derive(Debug, Clone, Deserialize)]
#[serde(default)]
pub struct Config {
    pub message_keys: Vec<String>,
    pub time_keys: Vec<String>,
    pub dump_all_exclude: Vec<String>,
    pub always_print_fields: Vec<String>,
    pub level_keys: Vec<String>,
    pub main_line_format: String,
    pub additional_value_format: String,
    pub level_map: HashMap<String, String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            message_keys: def_message_keys(),
            time_keys: def_time_keys(),
            dump_all_exclude: def_dump_all_exclude(),
            always_print_fields: def_always_print_fields(),
            level_keys: def_level_keys(),
            main_line_format: def_main_line_format(),
            additional_value_format: def_additional_value_format(),
            level_map: HashMap::new(),
        }
    }
}

pub const DEFAULT_CONFIG_NAME: &str = "fblog.toml";

/// Loads a config file, printing the parse error and returning an Err when the
/// file could not be used.
pub fn load(path: &str) -> Result<Config, ()> {
    match std::fs::read_to_string(path) {
        Ok(content) => match toml::from_str::<Config>(&content) {
            Ok(config) => Ok(config),
            Err(err) => {
                eprintln!("Could not parse config file: {err}");
                Err(())
            }
        },
        Err(_) => Err(()),
    }
}

/// Loads the configuration found in the standard user configuration location.
pub fn load_default() -> Config {
    if let Some(dir) = crate_dirs::config_dir() {
        let path = dir.join(DEFAULT_CONFIG_NAME);
        if let Ok(content) = std::fs::read_to_string(&path) {
            match toml::from_str::<Config>(&content) {
                Ok(config) => return config,
                Err(err) => {
                    panic!("Could not parse config file: {err}");
                }
            }
        }
    }
    Config::default()
}

/// Minimal replacement for the `dirs` crate: returns the XDG config directory.
mod crate_dirs {
    pub fn config_dir() -> Option<std::path::PathBuf> {
        if let Ok(v) = std::env::var("XDG_CONFIG_HOME") {
            if !v.is_empty() && std::path::Path::new(&v).is_absolute() {
                return Some(std::path::PathBuf::from(v));
            }
        }
        if let Ok(home) = std::env::var("HOME") {
            if !home.is_empty() {
                let mut p = std::path::PathBuf::from(home);
                p.push(".config");
                return Some(p);
            }
        }
        None
    }
}
