{"command": "cd /workspace && cat > src/template.rs <<'RSEOF'
//! Template engine used by fblog.

use serde_json::Value;

#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Path(Vec<String>),
    Call(String, Vec<Expr>),
    Str(String),
    Num(String),
    Bool(bool),
    Null,
}

#[derive(Debug, Clone)]
pub enum Node {
    Text(String),
    Expr(Expr, usize, usize),
    Block {
        helper: String,
        args: Vec<Expr>,
        body: Vec<Node>,
        else_body: Vec<Node>,
        line: usize,
        col: usize,
    },
}

#[derive(Debug, Clone)]
pub struct Template {
    pub nodes: Vec<Node>,
    pub name: String,
}

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
}

/// Description of a syntax error.
struct SynErr {
    reason: String,
    line: usize,
    col: usize,
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Self {
        Parser { src: src.as_bytes(), pos: 0 }
    }

    fn eof(&self) -> bool {
        self.pos >= self.src.len()
    }

    fn peek(&self) -> u8 {
        if self.eof() {
            0
        } else {
            self.src[self.pos]
        }
    }

    fn peek_at(&self, off: usize) -> u8 {
        if self.pos + off >= self.src.len() {
            0
        } else {
            self.src[self.pos + off]
        }
    }

    /// 1-based line number of the current position.
    fn line(&self) -> usize {
        let mut line = 1;
        for i in 0..self.pos.min(self.src.len()) {
            if self.src[i] == b'\n' {
                line += 1;
            }
        }
        line
    }

    /// 1-based column number of the current position.
    fn col(&self) -> usize {
        let start = {
            let mut start = 0usize;
            for i in (0..self.pos.min(self.src.len())).rev() {
                if self.src[i] == b'\n' {
                    start = i + 1;
                    break;
                }
            }
            start
        };
        self.pos - start + 1
    }

    fn line_text(&self) -> String {
        let start = {
            let mut start = 0usize;
            for i in (0..self.pos.min(self.src.len())).rev() {
                if self.src[i] == b'\n' {
                    start = i + 1;
                    break;
                }
            }
            start
        };
        let mut end = start;
        while end < self.src.len() && self.src[end] != b'\n' {
            end += 1;
        }
        String::from_utf_lossy(&self.src[start..end]).to_string()
    }

    fn skip_ws(&mut self) {
        while !self.eof() {
            match self.peek() {
                b' ' | b'\t' | b'\r' | b'\n' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn is_ident_char(c: u8) -> bool {
        c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'@'
    }

    fn parse_ident(&mut self) -> Option<String> {
        let start = self.pos;
        while !self.eof() && Self::is_ident_char(self.peek()) {
            self.pos += 1;
        }
        if self.pos == start {
            None
        } else {
            Some(String::from_utf_lossy(&self.src[start..self.pos]).to_string())
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        if self.peek() != b'"' {
            return None;
        }
        self.pos += 1;
        let mut out = String::new();
        while !self.eof() {
            let c = self.peek();
            self.pos += 1;
            match c {
                b'"' => return Some(out),
                b'\\' => {
                    if self.eof() {
                        return None;
                    }
                    let e = self.peek();
                    self.pos += 1;
                    match e {
                        b'n' => out.push('\n'),
                        b't' => out.push('\t'),
                        b'r' => out.push('\r'),
                        b'0' => out.push('\0'),
                        b'\\' => out.push('\\'),
                        b'"' => out.push('"'),
                        b'\'' => out.push('\''),
                        b'u' => {
                            // \uXXXX
                            if self.pos + 4 > self.src.len() {
                                return None;
                            }
                            let hex = std::str::from_utf8(&self.src[self.pos..self.pos + 4]).ok()?;
                            self.pos += 4;
                            let cp = u32::from_str_radix(hex, 16).ok()?;
                            out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                        }
                        _ => out.push(e as char),
                    }
                }
                _ => {
                    // copy the raw byte(s) of a utf8 char
                    let start = self.pos - 1;
                    let mut end = self.pos;
                    while end < self.src.len() && (self.src[end] & 0xc0) == 0x80 {
                        end += 1;
                    }
                    out.push_str(&String::from_utf_lossy(&self.src[start..end]));
                    self.pos = end;
                }
            }
        }
        None
    }

    fn parse_number(&mut self) -> Option<String> {
        let start = self.pos;
        if self.peek() == b'-' || self.peek() == b'+' {
            self.pos += 1;
        }
        let mut digits = false;
        while !self.eof() && self.peek().is_ascii_digit() {
            self.pos += 1;
            digits = true;
        }
        if !self.eof() && self.peek() == b'.' {
            self.pos += 1;
            while !self.eof() && self.peek().is_ascii_digit() {
                self.pos += 1;
                digits = true;
            }
        }
        if !digits {
            self.pos = start;
            return None;
        }
        Some(String::from_utf_lossy(&self.src[start..self.pos]).to_string())
    }

    /// Parses a single atom (used for expression starts and helper parameters).
    fn parse_atom(&mut self, is_param: bool) -> Result<Expr, SynErr> {
        let start_col = self.col();
        let line = self.line();
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(is_param, false, true, false),
                line,
                col: start_col,
            });
        }
        match self.peek() {
            b'"' => {
                if let Some(s) = self.parse_string() {
                    Ok(Expr::Str(s))
                } else {
                    Err(SynErr {
                        reason: expected_list(is_param, false, true, false),
                        line,
                        col: start_col,
                    })
                }
            }
            b'(' => {
                self.pos += 1;
                let sub = self.parse_call_in_parens(line)?;
                Ok(sub)
            }
            _ => {
                if let Some(num) = self.parse_number() {
                    return Ok(Expr::Num(num));
                }
                match self.parse_ident() {
                    Some(id) => {
                        if is_param {
                            match id.as_str() {
                                "true" => return Ok(Expr::Bool(true)),
                                "false" => return Ok(Expr::Bool(false)),
                                "null" => return Ok(Expr::Null),
                                _ => {}
                            }
                        }
                        Ok(Expr::Path(self.parse_path(id)))
                    }
