    fn parse_call_in_parens(&mut self, line: usize) -> Result<Expr, SynErr> {
        self.skip_ws();
        if self.eof() || !Self::is_ident_char(self.peek()) {
            return Err(SynErr {
                reason: "expected identifier or path_inline".to_string(),
                line,
                col: self.col(),
            });
        }
        let name = self.parse_ident().unwrap();
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() || !Self::is_ident_char(self.peek()) && self.peek() != b'"' {
                break;
            }
            if self.peek() == b'"' {
                break;
            }
            if self.peek() == b'~' || self.peek() == b'}' {
                break;
            }
            match self.parse_atom(true) {
                Ok(a) => args.push(a),
                Err(e) => {
                    return Err(SynErr {
                        reason: "expected identifier or helper_parameter".to_string(),
                        line: e.line,
                        col: e.col,
                    })
                }
            }
        }
        self.skip_ws();
        if self.peek() != b')' {
            return Err(SynErr {
                reason: "expected identifier or path_inline".to_string(),
                line,
                col: self.col(),
            });
        }
        self.pos += 1;
        Ok(Expr::Call(name, args))
    }

    fn parse_params(&mut self, line: usize, in_block_start: bool) -> Result<Vec<Expr>, SynErr> {
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() {
                break;
            }
            let c = self.peek();
            if c == b'~' || c == b'}' {
                break;
            }
            if c == b'"' || Self::is_ident_char(c) || c == b'(' || c == b'-' || c.is_ascii_digit() {
                match self.parse_atom(true) {
                    Ok(a) => args.push(a),
                    Err(e) => {
                        return Err(SynErr {
                            reason: expected_list(false, in_block_start, e.col > self.line_len(), false),
                            line: e.line,
                            col: e.col,
                        })
                    }
                }
            } else {
                let eof = self.eof();
                return Err(SynErr {
                    reason: expected_list(false, in_block_start, eof, false),
                    line,
                    col: self.col(),
                });
            }
        }
        Ok(args)
    }

    fn line_len(&self) -> usize {
        self.line_text().chars().count() + 1
    }
}

fn expected_list(is_param: bool, in_block_start: bool, eof: bool, in_block_body: bool) -> String {
    if is_param {
        let mut parts = vec!["identifier".to_string(), "helper_parameter".to_string()];
        if in_block_start {
            parts.push("block_param".to_string());
        }
        if eof {
            parts.push("trailing_tilde_to_omit_whitespace".to_string());
        }
        return join_or(&parts);
    }
    let mut parts = vec![
        "identifier".to_string(),
        "subexpression".to_string(),
        "leading_tilde_to_omit_whitespace".to_string(),
    ];
    if in_block_body {
        parts.push("invert_tag_item".to_string());
    }
    parts.push("path_inline".to_string());
    if eof {
        parts.push("trailing_tilde_to_omit_whitespace".to_string());
    }
    join_or(&parts)
}

fn join_or(parts: &[String]) -> String {
    if parts.len() == 1 {
        return parts[0].clone();
    }
    let (last, rest) = parts.split_last().unwrap();
    format!("expected {}, or {}", rest.join(", "), last)
}
