{"command": "cd /workspace && cat >> src/template.rs <<'RSEOF'

#[derive(Debug)]
enum Stop {
    Else,
    End(String),
}

impl<'a> Parser<'a> {
    /// Parses nodes until the end of the template or until a block terminator.
    fn parse_nodes(
        &mut self,
        in_block: bool,
        block_helper: Option<&str>,
    ) -> Result<(Vec<Node>, Option<Stop>), SynErr> {
        let mut nodes: Vec<Node> = Vec::new();
        let mut text = String::new();
        let mut strip = false;
        loop {
            if self.eof() {
                if in_block {
                    let (line, col) = (self.line(), self.col());
                    text = String::new();
                    return Err(SynErr {
                        reason: tag_start_list(false),
                        line,
                        col,
                    });
                }
                if !text.is_empty() {
                    nodes.push(Node::Text(text));
                }
                return Ok((nodes, None));
            }
            // escaped tag
            if self.peek() == b'\\'
                && self.peek_at(1) == b'{'
                && self.peek_at(2) == b'{'
            {
                text.push_str("{{");
                self.pos += 3;
                strip = false;
                continue;
            }
            if self.peek() == b'{' && self.peek_at(1) == b'{' {
                if strip && !text.is_empty() {
                    // strip trailing whitespace of the text before the tag
                    while text.ends_with([' ', '\t', '\r', '\n']) {
                        text.pop();
                    }
                }
                let leading_tilde = {
                    let mut lt = false;
                    let mut p = self.pos + 2;
                    while p < self.src.len() && (self.src[p] == b' ' || self.src[p] == b'\t' || self.src[p] == b'\r' || self.src[p] == b'\n') {
                        p += 1;
                    }
                    if p < self.src.len() && self.src[p] == b'~' {
                        lt = true;
                    }
                    lt
                };
                match self.parse_tag(in_block, block_helper)? {
                    TagResult::Text(s, trailing_tilde) => {
                        if !text.is_empty() || !s.is_empty() {
                            text.push_str(&s);
                        }
                        strip = trailing_tilde;
                        continue;
                    }
                    TagResult::Node(n, trailing_tilde) => {
                        if !text.is_empty() {
                            nodes.push(Node::Text(std::mem::take(&mut text)));
                        }
                        nodes.push(n);
                        strip = trailing_tilde;
                        continue;
                    }
                    TagResult::Stop(stop, trailing_tilde) => {
                        if !text.is_empty() {
                            nodes.push(Node::Text(std::mem::take(&mut text)));
                        }
                        return Ok((nodes, Some(stop)));
                    }
                    TagResult::Comment(trailing_tilde) => {
                        strip = trailing_tilde;
                        continue;
                    }
                }
            }
            let start = self.pos;
            while !self.eof() && !(self.peek() == b'{' && self.peek_at(1) == b'{') {
                if self.peek() == b'\\' && self.peek_at(1) == b'{' && self.peek_at(2) == b'{' {
                    break;
                }
                self.pos += 1;
            }
            text.push_str(&String::from_utf_lossy(&self.src[start..self.pos]));
        }
    }

    fn parse_tag(
        &mut self,
        in_block: bool,
        block_helper: Option<&str>,
    ) -> Result<TagResult, SynErr> {
        let line = self.line();
        let tag_col = self.col();
        self.pos += 2;
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line: self.line(),
                col: self.col(),
            });
        }
        // raw block: {{{{name}}}} ... {{{{/name}}}}
        if self.peek() == b'{' && self.peek_at(1) == b'{' {
            self.pos += 2;
            self.skip_ws();
            let name = match self.parse_ident() {
                Some(n) => n,
                None => {
                    return Err(SynErr {
                        reason: "expected identifier or path_inline".to_string(),
                        line,
                        col: self.col(),
                    })
                }
            };
            self.skip_ws();
            if self.peek() == b'~' {
                self.pos += 1;
            }
            if self.peek() != b'}' || self.peek_at(1) != b'}' || self.peek_at(2) != b'}' || self.peek_at(3) != b'}' {
                return Err(SynErr {
                    reason: "expected escape or raw_block_end".to_string(),
                    line,
                    col: self.col(),
                });
            }
            self.pos += 4;
            let start = self.pos;
            let close = format!("{{{{/{{{}}}}}}}", name);
            let mut p = self.pos;
            while p < self.src.len() {
                if self.src[p..].starts_with(close.as_bytes()) {
                    break;
                }
                p += 1;
            }
            if p >= self.src.len() {
                self.pos = self.src.len();
                return Err(SynErr {
                    reason: "expected escape or raw_block_end".to_string(),
                    line,
                    col: self.col(),
                });
            }
            let raw = String::from_utf_lossy(&self.src[start..p]).to_string();
            self.pos = p + close.len();
            self.skip_ws();
            let trailing = self.consume_tilde();
            return Ok(TagResult::Node(
                Node::Block {
                    helper: name,
                    args: Vec::new(),
                    body: vec![Node::Text(raw)],
                    else_body: Vec::new(),
                    line,
                    col: tag_col,
                },
                trailing,
            ));
        }
        // triple brace expression {{{ expr }}}
        if self.peek() == b'{' {
            self.pos += 1;
            return self.parse_expr_tag(line, tag_col, true, in_block);
        }
        if self.peek() == b'~' {
            self.pos += 1;
        }
