                let mut p = self.pos + 1;
                let compact = self.src[p..].starts_with(b"--");
                if compact {
                    p += 2;
                }
                while p < self.src.len() {
                    if compact {
                        if self.src[p..].starts_with(b"--}}") {
                            p += 4;
                            break;
                        }
                    } else if self.src[p..].starts_with(b"}}") {
                        p += 2;
                        break;
                    }
                    p += 1;
                }
                if p >= self.src.len() {
                    self.pos = self.src.len();
                    return Err(SynErr {
                        reason: "expected escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact".to_string(),
                        line,
                        col: self.col(),
                    });
                }
                self.pos = p;
                self.skip_ws();
                let trailing = self.consume_tilde();
                Ok(TagResult::Comment(trailing))
            }
            b'#' => {
                self.pos += 1;
                self.skip_ws();
                let helper = match self.parse_ident() {
                    Some(h) => h,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                let args = self.parse_params(line, true)?;
                if self.peek() == b'~' {
                    self.pos += 1;
                }
