                    Some(Stop::End(_)) => (vec![], vec![]),
                    Some(Stop::Else) => {
                        let (eb, stop2) = self.parse_nodes(true, Some(&helper))?;
                        match stop2 {
                            Some(Stop::End(_)) => (vec![], eb),
                            _ => (eb, vec![]),
                        }
