                    Some(h) => h,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                self.skip_ws();
                if self.peek() == b'~' {
                    self.pos += 1;
                }
                self.expect_close(line, tag_col, "}}")?;
                match block_helper {
                    Some(h) if h == helper => Ok(TagResult::Stop(Stop::End(helper), false)),
                    _ => Err(SynErr {
                        reason: expected_list(false, false, self.eof(), in_block),
                        line,
                        col: tag_col,
                    }),
                }
            }
            b'>' => {
                self.pos += 1;
                self.skip_ws();
                let name = match self.parse_ident() {
                    Some(n) => n,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                self.skip_ws();
                if self.peek() == b'~' {
                    self.pos += 1;
                }
                self.expect_close(line, tag_col, "}}")?;
                Ok(TagResult::Node(
                    Node::Expr(Expr::Call("__partial__".to_string(), vec![Expr::Str(name)]), line, tag_col),
                    false,
                ))
            }
            _ => self.parse_expr_tag(line, tag_col, false, in_block),
        }
    }

    fn consume_tilde(&mut self) -> bool {
        if self.peek() == b'~' {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn expect_close(&mut self, _line: usize, _col: usize, close: &str) -> Result<(), SynErr> {
        if self.src[self.pos.min(self.src.len())..].starts_with(close.as_bytes()) {
            self.pos += close.len();
            Ok(())
        } else if self.eof() {
            Err(SynErr {
                reason: "expected trailing_tilde_to_omit_whitespace".to_string(),
                line: self.line(),
                col: self.col(),
            })
        } else {
            Err(SynErr {
                reason: "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace".to_string(),
                line: self.line(),
                col: self.col(),
            })
        }
    }

    fn parse_expr_tag(
        &mut self,
        line: usize,
        tag_col: usize,
        triple: bool,
        in_block: bool,
    ) -> Result<TagResult, SynErr> {
        self.skip_ws();
        let close = if triple { "}}}" } else { "}}" };
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line: self.line(),
                col: self.col(),
            });
        }
        if self.peek() == b'}' && self.peek_at(1) == b'}' {
            // empty expression
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line,
                col: self.col(),
            });
        }
        if self.peek() == b'&' {
            self.pos += 1;
            self.skip_ws();
        }
        let first = match self.parse_atom(false) {
            Ok(a) => a,
            Err(e) => {
                return Err(SynErr {
                    reason: expected_list(false, false, false, in_block),
                    line: e.line,
                    col: e.col,
                })
            }
        };
        let args = match &first {
            Expr::Path(_) | Expr::Call(_, _) => self.parse_params(line, false)?,
            _ => vec![],
        };
        self.skip_ws();
        if self.peek() == b'~' {
            self.pos += 1;
        }
        self.expect_close(line, tag_col, close)?;
        // Build the expression
        let expr = match (&first, args.is_empty()) {
            (Expr::Path(p), true) => Expr::Path(p.clone()),
            (Expr::Call(n, a), true) => Expr::Call(n.clone(), a.clone()),
            (Expr::Path(p), false) => Expr::Call(p.join("."), args),
            (other, false) => Expr::Call("".to_string(), {
                let mut v = vec![other.clone()];
                v.extend(args);
                v
            }),
            (other, true) => other.clone(),
        };
        Ok(TagResult::Node(
            Node::Expr(expr, line, tag_col),
            false,
        ))
    }

    /// Parses the body of a block helper, stopping at `{{else}}` or `{{/helper}}`.
    fn parse_block_body(&mut self, helper: &str) -> Result<Option<Stop>, SynErr> {
        let (body, stop) = self.parse_nodes(true, Some(helper))?;
        self.pending = body;
        Ok(stop)
    }
}

enum TagResult {
    Text(String, bool),
    Node(Node, bool),
    Stop(Stop, bool),
    Comment(bool),
}

fn tag_start_list(after_else: bool) -> String {
    let mut parts = vec![
        "escape".to_string(),
        "expression".to_string(),
        "html_expression".to_string(),
        "decorator_expression".to_string(),
        "partial_expression".to_string(),
    ];
    if !after_else {
        parts.push("invert_tag".to_string());
        parts.push("invert_chain_tag".to_string());
    }
    parts.push("helper_block_start".to_string());
    parts.push("helper_block_end".to_string());
    parts.push("decorator_block_start".to_string());
    parts.push("partial_block_start".to_string());
    parts.push("raw_block_start".to_string());
    parts.push("hbs_comment".to_string());
    parts.push("hbs_comment_compact".to_string());
    join_or(&parts)
}
