//! Template engine used by fblog.

use serde_json::Value;

#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Path(Vec<String>),
    Call(String, Vec<Expr>),
    Str(String),
    Num(String),
    Bool(bool),
    Null,
}

#[derive(Debug, Clone)]
pub enum Node {
    Text(String),
    Expr(Expr, usize, usize),
    Block {
        helper: String,
        args: Vec<Expr>,
        body: Vec<Node>,
        else_body: Vec<Node>,
        line: usize,
        col: usize,
    },
}

#[derive(Debug, Clone)]
pub struct Template {
    pub nodes: Vec<Node>,
    pub name: String,
}

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
}

/// Description of a syntax error.
struct SynErr {
    reason: String,
    line: usize,
    col: usize,
}

#[derive(Debug)]
enum Stop {
    Else(Vec<Expr>),
    End(String),
}

enum TagResult {
    Node(Node, bool),
    Stop(Stop, bool),
    Comment(bool),
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Self {
        Parser { src: src.as_bytes(), pos: 0 }
    }

    fn eof(&self) -> bool {
        self.pos >= self.src.len()
    }

    fn peek(&self) -> u8 {
        if self.eof() {
            0
        } else {
            self.src[self.pos]
        }
    }

    fn peek_at(&self, off: usize) -> u8 {
        if self.pos + off >= self.src.len() {
            0
        } else {
            self.src[self.pos + off]
        }
    }

    fn line_start(&self, pos: usize) -> usize {
        let mut start = 0usize;
        for i in (0..pos.min(self.src.len())).rev() {
            if self.src[i] == b'\n' {
                start = i + 1;
                break;
            }
        }
        start
    }

    /// 1-based line number of the current position.
    fn line(&self) -> usize {
        1 + self.src[..self.pos.min(self.src.len())]
            .iter()
            .filter(|c| **c == b'\n')
            .count()
    }

    /// 1-based column number of the current position.
    fn col(&self) -> usize {
        self.pos - self.line_start(self.pos) + 1
    }

    fn line_text(&self) -> String {
        let start = self.line_start(self.pos);
        let mut end = start;
        while end < self.src.len() && self.src[end] != b'\n' {
            end += 1;
        }
        String::from_utf_lossy(&self.src[start..end]).to_string()
    }

    fn skip_ws(&mut self) {
        while !self.eof() {
            match self.peek() {
                b' ' | b'\t' | b'\r' | b'\n' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn is_ident_char(c: u8) -> bool {
        c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'@'
    }

    fn parse_ident(&mut self) -> Option<String> {
        let start = self.pos;
        while !self.eof() && Self::is_ident_char(self.peek()) {
            self.pos += 1;
        }
        if self.pos == start {
            None
        } else {
            Some(String::from_utf_lossy(&self.src[start..self.pos]).to_string())
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        if self.peek() != b'"' {
            return None;
        }
        self.pos += 1;
        let mut out = String::new();
        while !self.eof() {
            let c = self.peek();
            self.pos += 1;
            match c {
                b'"' => return Some(out),
                b'\\' => {
                    if self.eof() {
                        return None;
                    }
                    let e = self.peek();
                    self.pos += 1;
                    match e {
                        b'n' => out.push('\n'),
                        b't' => out.push('\t'),
                        b'r' => out.push('\r'),
                        b'0' => out.push('\0'),
                        b'\\' => out.push('\\'),
                        b'"' => out.push('"'),
                        b'\'' => out.push('\''),
                        b'u' => {
                            if self.pos + 4 > self.src.len() {
                                return None;
                            }
                            let hex = std::str::from_utf8(&self.src[self.pos..self.pos + 4]).ok()?;
                            self.pos += 4;
                            let cp = u32::from_str_radix(hex, 16).ok()?;
                            out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                        }
                        _ => out.push(e as char),
                    }
                }
                _ => {
                    let start = self.pos - 1;
                    let mut end = self.pos;
                    while end < self.src.len() && (self.src[end] & 0xc0) == 0x80 {
                        end += 1;
                    }
                    out.push_str(&String::from_utf_lossy(&self.src[start..end]));
                    self.pos = end;
                }
            }
        }
        None
    }

    fn parse_number(&mut self) -> Option<String> {
        let start = self.pos;
        if self.peek() == b'-' {
            self.pos += 1;
        }
        let mut digits = false;
        while !self.eof() && self.peek().is_ascii_digit() {
            self.pos += 1;
            digits = true;
        }
        if !self.eof() && self.peek() == b'.' {
            self.pos += 1;
            while !self.eof() && self.peek().is_ascii_digit() {
                self.pos += 1;
                digits = true;
            }
        }
        if !digits {
            self.pos = start;
            return None;
        }
        Some(String::from_utf_lossy(&self.src[start..self.pos]).to_string())
    }

    /// Parses a single atom (used for expression starts and helper parameters).
    fn parse_atom(&mut self, is_param: bool) -> Result<Expr, SynErr> {
        let start_col = self.col();
        let line = self.line();
        let eof = self.eof();
        if eof {
            return Err(SynErr {
                reason: expected_list(is_param, false, true, false),
                line,
                col: start_col,
            });
        }
        match self.peek() {
            b'"' => {
                if let Some(s) = self.parse_string() {
                    Ok(Expr::Str(s))
                } else {
                    Err(SynErr {
                        reason: expected_list(is_param, false, true, false),
                        line,
                        col: start_col,
                    })
                }
            }
            b'(' => {
                self.pos += 1;
                self.parse_call_in_parens(line)
            }
            _ => {
                if let Some(num) = self.parse_number() {
                    return Ok(Expr::Num(num));
                }
                match self.parse_ident() {
                    Some(id) => {
                        if is_param {
                            match id.as_str() {
                                "true" => return Ok(Expr::Bool(true)),
                                "false" => return Ok(Expr::Bool(false)),
                                "null" => return Ok(Expr::Null),
                                _ => {}
                            }
                        }
                        Ok(Expr::Path(self.parse_path(id)))
                    }
                    None => Err(SynErr {
                        reason: expected_list(is_param, false, eof, false),
                        line,
                        col: start_col,
                    }),
                }
            }
        }
    }

    /// Extends an identifier into a dotted path.
    fn parse_path(&mut self, first: String) -> Vec<String> {
        let mut path = vec![first];
        loop {
            if self.peek() == b'.' {
                let save = self.pos;
                self.pos += 1;
                if self.peek() != b'.' && Self::is_ident_char(self.peek()) {
                    match self.parse_ident() {
                        Some(id) => path.push(id),
                        None => {
                            self.pos = save;
                            break;
                        }
                    }
                } else {
                    self.pos = save;
                    break;
                }
            } else {
                break;
            }
        }
        path
    }

    /// Parses a helper call inside parentheses: `(` ident [params] `)`.
    fn parse_call_in_parens(&mut self, line: usize) -> Result<Expr, SynErr> {
        self.skip_ws();
        if self.eof() || !Self::is_ident_char(self.peek()) {
            return Err(SynErr {
                reason: "expected identifier or path_inline".to_string(),
                line,
                col: self.col(),
            });
        }
        let name = self.parse_ident().unwrap();
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() {
                break;
            }
            let c = self.peek();
            if c == b')' || c == b'~' {
                break;
            }
            if c == b'"' {
                match self.parse_string() {
                    Some(s) => args.push(Expr::Str(s)),
                    None => {
                        return Err(SynErr {
                            reason: "expected identifier or helper_parameter".to_string(),
                            line,
                            col: self.col(),
                        })
                    }
                }
                continue;
            }
            if Self::is_ident_char(c) || c == b'-' || c.is_ascii_digit() {
                match self.parse_atom(true) {
                    Ok(a) => args.push(a),
                    Err(_) => {
                        return Err(SynErr {
                            reason: "expected identifier or helper_parameter".to_string(),
                            line,
                            col: self.col(),
                        })
                    }
                }
                continue;
            }
            return Err(SynErr {
                reason: "expected identifier or helper_parameter".to_string(),
                line,
                col: self.col(),
            });
        }
        self.skip_ws();
        if self.peek() != b')' {
            return Err(SynErr {
                reason: "expected identifier or path_inline".to_string(),
                line,
                col: self.col(),
            });
        }
        self.pos += 1;
        Ok(Expr::Call(name, args))
    }

    fn parse_params(
        &mut self,
        line: usize,
        in_block_start: bool,
        eof_expected: bool,
    ) -> Result<Vec<Expr>, SynErr> {
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() {
                break;
            }
            let c = self.peek();
            if c == b'~' || c == b'}' {
                break;
            }
            if c == b'"' || Self::is_ident_char(c) || c == b'(' || c == b'-' || c.is_ascii_digit() {
                match self.parse_atom(true) {
                    Ok(a) => args.push(a),
                    Err(e) => {
                        return Err(SynErr {
                            reason: expected_list(false, in_block_start, eof_expected, false),
                            line: e.line,
                            col: e.col,
                        })
                    }
                }
            } else {
                return Err(SynErr {
                    reason: expected_list(false, in_block_start, self.eof(), false),
                    line,
                    col: self.col(),
                });
            }
        }
        Ok(args)
    }

    fn consume_tilde(&mut self) -> bool {
        if self.peek() == b'~' {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn expect_close(&mut self, close: &str, line: usize) -> Result<(), SynErr> {
        if self.src[self.pos.min(self.src.len())..].starts_with(close.as_bytes()) {
            self.pos += close.len();
            Ok(())
        } else if self.eof() {
            Err(SynErr {
                reason: "expected trailing_tilde_to_omit_whitespace".to_string(),
                line: self.line(),
                col: self.col(),
            })
        } else {
            Err(SynErr {
                reason: expected_list(true, false, false, false),
                line,
                col: self.col(),
            })
        }
    }

    /// Parses nodes until the end of the template or until a block terminator.
    fn parse_nodes(
        &mut self,
        in_block: bool,
        block_helper: Option<&str>,
        else_allowed: bool,
    ) -> Result<(Vec<Node>, Option<Stop>), SynErr> {
        let mut nodes: Vec<Node> = Vec::new();
        let mut text = String::new();
        let mut strip_next = false;
        loop {
            if self.eof() {
                if in_block {
                    return Err(SynErr {
                        reason: tag_start_list(!else_allowed),
                        line: self.line(),
                        col: self.col(),
                    });
                }
                if !text.is_empty() {
                    nodes.push(Node::Text(text));
                }
                return Ok((nodes, None));
            }
            if self.peek() == b'\\' && self.peek_at(1) == b'{' && self.peek_at(2) == b'{' {
                text.push_str("{{");
                self.pos += 3;
                strip_next = false;
                continue;
            }
            if self.peek() == b'{' && self.peek_at(1) == b'{' {
                if strip_next {
                    while text.ends_with([' ', '\t', '\r', '\n']) {
                        text.pop();
                    }
                    strip_next = false;
                }
                let leading_tilde = {
                    let mut p = self.pos + 2;
                    while p < self.src.len()
                        && matches!(self.src[p], b' ' | b'\t' | b'\r' | b'\n')
                    {
                        p += 1;
                    }
                    p < self.src.len() && self.src[p] == b'~'
                };
                match self.parse_tag(in_block, block_helper, else_allowed, leading_tilde)? {
                    TagResult::Node(n, trailing) => {
                        if !text.is_empty() {
                            nodes.push(Node::Text(std::mem::take(&mut text)));
                        }
                        nodes.push(n);
                        strip_next = trailing;
                        continue;
                    }
                    TagResult::Stop(stop, trailing) => {
                        if !text.is_empty() {
                            nodes.push(Node::Text(std::mem::take(&mut text)));
                        }
                        let _ = trailing;
                        return Ok((nodes, Some(stop)));
                    }
                    TagResult::Comment(trailing) => {
                        strip_next = trailing;
                        continue;
                    }
                }
            }
            let start = self.pos;
            while !self.eof() && !(self.peek() == b'{' && self.peek_at(1) == b'{') {
                if self.peek() == b'\\' && self.peek_at(1) == b'{' && self.peek_at(2) == b'{' {
                    break;
                }
                self.pos += 1;
            }
            let chunk = String::from_utf_lossy(&self.src[start..self.pos]).to_string();
            if strip_next {
                let trimmed = chunk.trim_start_matches([' ', '\t', '\r', '\n']);
                if trimmed.is_empty() {
                    text.push_str(trimmed);
                } else {
                    text.push_str(trimmed);
                }
                strip_next = false;
            } else {
                text.push_str(&chunk);
            }
        }
    }

    fn parse_tag(
        &mut self,
        in_block: bool,
        block_helper: Option<&str>,
        else_allowed: bool,
        leading_tilde: bool,
    ) -> Result<TagResult, SynErr> {
        let _ = leading_tilde;
        let line = self.line();
        let tag_col = self.col();
        self.pos += 2;
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line: self.line(),
                col: self.col(),
            });
        }
        // raw block: {{{{name}}}} ... {{{{/name}}}}
        if self.peek() == b'{' && self.peek_at(1) == b'{' {
            self.pos += 2;
            self.skip_ws();
            let name = match self.parse_ident() {
                Some(n) => n,
                None => {
                    return Err(SynErr {
                        reason: "expected identifier or path_inline".to_string(),
                        line,
                        col: self.col(),
                    })
                }
            };
            let args = self.parse_params(line, true, false)?;
            self.skip_ws();
            self.consume_tilde();
            if !(self.peek() == b'}' && self.peek_at(1) == b'}' && self.peek_at(2) == b'}' && self.peek_at(3) == b'}')
            {
                return Err(SynErr {
                    reason: "expected escape or raw_block_end".to_string(),
                    line,
                    col: self.col(),
                });
            }
            self.pos += 4;
            let start = self.pos;
            let close = format!("{{{{/{{{}}}}}}}", name);
            let mut p = self.pos;
            while p < self.src.len() {
                if self.src[p..].starts_with(close.as_bytes()) {
                    break;
                }
                p += 1;
            }
            if p >= self.src.len() {
                self.pos = self.src.len();
                return Err(SynErr {
                    reason: "expected escape or raw_block_end".to_string(),
                    line,
                    col: self.col(),
                });
            }
            let raw = String::from_utf_lossy(&self.src[start..p]).to_string();
            self.pos = p + close.len();
            let trailing = self.consume_tilde();
            return Ok(TagResult::Node(
                Node::Block {
                    helper: name,
                    args,
                    body: vec![Node::Text(raw)],
                    else_body: Vec::new(),
                    line,
                    col: tag_col,
                },
                trailing,
            ));
        }
        if self.peek() == b'{' {
            self.pos += 1;
            return self.parse_expr_tag(line, tag_col, true, in_block);
        }
        if self.peek() == b'~' {
            self.pos += 1;
        }
        self.skip_ws();
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line: self.line(),
                col: self.col(),
            });
        }
        match self.peek() {
            b'!' => {
                let mut p = self.pos + 1;
                let compact = self.src[p..].starts_with(b"--");
                if compact {
                    p += 2;
                }
                while p < self.src.len() {
                    if compact {
                        if self.src[p..].starts_with(b"--}}") {
                            p += 4;
                            break;
                        }
                    } else if self.src[p..].starts_with(b"}}") {
                        p += 2;
                        break;
                    }
                    p += 1;
                }
                if p >= self.src.len() {
                    self.pos = self.src.len();
                    return Err(SynErr {
                        reason: tag_start_list(false),
                        line,
                        col: self.col(),
                    });
                }
                self.pos = p;
                self.skip_ws();
                let trailing = self.consume_tilde();
                Ok(TagResult::Comment(trailing))
            }
            b'#' => {
                self.pos += 1;
                self.skip_ws();
                let helper = match self.parse_ident() {
                    Some(h) => h,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                let args = self.parse_params(line, true, false)?;
                self.skip_ws();
                self.consume_tilde();
                self.expect_close("}}", line)?;
                self.parse_block(&helper, args, line, tag_col)
            }
            b'/' => {
                self.pos += 1;
                self.skip_ws();
                let helper = match self.parse_ident() {
                    Some(h) => h,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                self.skip_ws();
                self.consume_tilde();
                self.expect_close("}}", line)?;
                match block_helper {
                    Some(h) if h == helper => Ok(TagResult::Stop(Stop::End(helper), false)),
                    _ => Err(SynErr {
                        reason: expected_list(false, false, self.eof(), in_block),
                        line,
                        col: tag_col,
                    }),
                }
            }
            b'>' => {
                self.pos += 1;
                self.skip_ws();
                let name = match self.parse_ident() {
                    Some(n) => n,
                    None => {
                        return Err(SynErr {
                            reason: expected_list(false, false, self.eof(), in_block),
                            line,
                            col: self.col(),
                        })
                    }
                };
                self.skip_ws();
                self.consume_tilde();
                self.expect_close("}}", line)?;
                Ok(TagResult::Node(
                    Node::Expr(
                        Expr::Call("__partial__".to_string(), vec![Expr::Str(name)]),
                        line,
                        tag_col,
                    ),
                    false,
                ))
            }
            _ => self.parse_expr_tag(line, tag_col, false, in_block, block_helper, else_allowed),
        }
    }

    /// Parses a block start: body, optional else chain and the end tag.
    fn parse_block(
        &mut self,
        helper: &str,
        args: Vec<Expr>,
        line: usize,
        col: usize,
    ) -> Result<TagResult, SynErr> {
        let mut body = Vec::new();
        let mut else_body = Vec::new();
        let mut chain: Option<(String, Vec<Expr>)> = None;
        let mut current_else_args: Option<Vec<Expr>> = None;
        loop {
            let (nodes, stop) = self.parse_nodes(true, Some(helper), true)?;
            match stop {
                Some(Stop::End(_)) => {
                    if let Some((ch, ch_args)) = chain.take() {
                        else_body = vec![Node::Block {
                            helper: ch,
                            args: ch_args,
                            body: nodes,
                            else_body: Vec::new(),
                            line,
                            col,
                        }];
                    } else if current_else_args.is_some() {
                        else_body = nodes;
                    } else {
                        body = nodes;
                    }
                    break;
                }
                Some(Stop::Else(eargs)) => {
                    if !eargs.is_empty() {
                        // else if/unless chain
                        let name = match &eargs[0] {
                            Expr::Path(p) => p.join("."),
                            Expr::Call(n, _) => n.clone(),
                            _ => String::new(),
                        };
                        let rest: Vec<Expr> = eargs.iter().skip(1).cloned().collect();
                        chain = Some((name, rest));
                        if let Some((ch, ch_args)) = current_else_args.take() {
                            let _ = ch;
                            let _ = ch_args;
                        }
                        continue;
                    }
                    if let Some((ch, ch_args)) = chain.take() {
                        else_body = vec![Node::Block {
                            helper: ch,
                            args: ch_args,
                            body: nodes,
                            else_body: Vec::new(),
                            line,
                            col,
                        }];
                        continue;
                    }
                    if current_else_args.is_none() {
                        body = nodes;
                        current_else_args = Some(Vec::new());
                        continue;
                    }
                    body = nodes;
                    break;
                }
                None => {
                    return Err(SynErr {
                        reason: tag_start_list(false),
                        line: self.line(),
                        col: self.col(),
                    })
                }
            }
        }
        Ok(TagResult::Node(
            Node::Block {
                helper: helper.to_string(),
                args,
                body,
                else_body,
                line,
                col,
            },
            false,
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn parse_expr_tag(
        &mut self,
        line: usize,
        tag_col: usize,
        triple: bool,
        in_block: bool,
        block_helper: Option<&str>,
        else_allowed: bool,
    ) -> Result<TagResult, SynErr> {
        self.skip_ws();
        let close = if triple { "}}}" } else { "}}" };
        if self.eof() {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line: self.line(),
                col: self.col(),
            });
        }
        if self.peek() == b'}' && self.peek_at(1) == b'}' {
            return Err(SynErr {
                reason: expected_list(false, false, false, in_block),
                line,
                col: self.col(),
            });
        }
        let html_safe = self.peek() == b'&';
        if html_safe {
            self.pos += 1;
            self.skip_ws();
        }
        let first = match self.parse_atom(false) {
            Ok(a) => a,
            Err(e) => {
                return Err(SynErr {
                    reason: expected_list(false, false, false, in_block),
                    line: e.line,
                    col: e.col,
                })
            }
        };
        // `{{else}}` handling
        if let Expr::Path(p) = &first {
            if p.len() == 1 && p[0] == "else" && !html_safe {
                let mut args = self.parse_params(line, false, false)?;
                self.skip_ws();
                self.consume_tilde();
                self.expect_close(close, line)?;
                if args.len() == 1 {
                    if let Expr::Path(pp) = &args[0] {
                        if pp.len() == 1 && pp[0] == "true" {
                            args.clear();
                        }
                    }
                }
                if !args.is_empty() {
                    if !else_allowed {
                        return Err(SynErr {
                            reason: expected_list(false, false, false, in_block),
                            line,
                            col: tag_col,
                        });
                    }
                    // else if / else unless chain
                    let name = match &args[0] {
                        Expr::Path(pp) => pp.join("."),
                        Expr::Call(n, _) => n.clone(),
                        _ => String::new(),
                    };
                    let rest: Vec<Expr> = args.iter().skip(1).cloned().collect();
                    let name = if name == "true" { String::new() } else { name };
                    return Ok(TagResult::Stop(
                        Stop::Else({
                            let mut v = Vec::new();
                            if !name.is_empty() {
                                v.push(Expr::Path(vec![name]));
                            }
                            v.extend(rest);
                            v
                        }),
                        false,
                    ));
                }
                if !else_allowed {
                    return Err(SynErr {
                        reason: expected_list(false, false, false, in_block),
                        line,
                        col: tag_col,
                    });
                }
                return Ok(TagResult::Stop(Stop::Else(Vec::new()), false));
            }
        }
        let args = match &first {
            Expr::Path(_) => self.parse_params(line, false, false)?,
            Expr::Call(_, _) => self.parse_params(line, false, false)?,
            _ => vec![],
        };
        self.skip_ws();
        self.consume_tilde();
        self.expect_close(close, line)?;
        let expr = match (&first, args.is_empty()) {
            (Expr::Path(p), true) => Expr::Path(p.clone()),
            (Expr::Call(n, a), true) => Expr::Call(n.clone(), a.clone()),
            (Expr::Path(p), false) => Expr::Call(p.join("."), args),
            (other, _) => other.clone(),
        };
        if let Expr::Call(n, _) = &expr {
            if n == "else" {
                return Ok(TagResult::Stop(Stop::Else(Vec::new()), false));
            }
        }
        let _ = block_helper;
        Ok(TagResult::Node(Node::Expr(expr, line, tag_col), false))
    }
}

fn expected_list(is_param: bool, in_block_start: bool, eof: bool, in_block_body: bool) -> String {
    if is_param {
        let mut parts = vec!["identifier".to_string(), "helper_parameter".to_string()];
        if in_block_start {
            parts.push("block_param".to_string());
        }
        if eof {
            parts.push("trailing_tilde_to_omit_whitespace".to_string());
        }
        return join_or(&parts);
    }
    let mut parts = vec![
        "identifier".to_string(),
        "subexpression".to_string(),
        "leading_tilde_to_omit_whitespace".to_string(),
    ];
    if in_block_body {
        parts.push("invert_tag_item".to_string());
    }
    parts.push("path_inline".to_string());
    join_or(&parts)
}

fn tag_start_list(after_else: bool) -> String {
    let mut parts = vec![
        "escape".to_string(),
        "expression".to_string(),
        "html_expression".to_string(),
        "decorator_expression".to_string(),
        "partial_expression".to_string(),
    ];
    if !after_else {
        parts.push("invert_tag".to_string());
        parts.push("invert_chain_tag".to_string());
    }
    parts.push("helper_block_start".to_string());
    parts.push("helper_block_end".to_string());
