/// Rendering context: the value that paths resolve against plus block metadata.
pub struct Ctx<'a> {
    pub value: &'a Value,
    pub index: Option<usize>,
    pub key: Option<String>,
    pub first: bool,
    pub last: bool,
    pub in_each: bool,
}

impl<'a> Ctx<'a> {
    pub fn new(value: &'a Value) -> Self {
        Ctx {
            value,
            index: None,
            key: None,
            first: false,
            last: false,
            in_each: false,
        }
    }
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64().map(|f| f != 0.0).unwrap_or(true),
        Value::String(s) => !s.is_empty(),
        Value::Array(_) | Value::Object(_) => true,
    }
}

/// Renders a json value the way fblog templates do.
pub fn render_value(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => s.clone(),
        Value::Array(items) => {
            let parts: Vec<String> = items.iter().map(render_value).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(_) => "[object]".to_string(),
    }
}

fn resolve_path(path: &[String], ctx: &Ctx) -> Value {
    if path.len() == 1 {
        match path[0].as_str() {
            "this" => return ctx.value.clone(),
            "@index" => {
                return match ctx.index {
                    Some(i) => Value::from(i as u64),
                    None => Value::Null,
                }
            }
            "@key" => {
                return match &ctx.key {
                    Some(k) => Value::String(k.clone()),
                    None => Value::Null,
                }
            }
            "@first" => {
                return if ctx.in_each {
                    Value::Bool(ctx.first)
                } else {
                    Value::Null
                }
            }
            "@last" => {
                return if ctx.in_each {
                    Value::Bool(ctx.last)
                } else {
                    Value::Null
                }
            }
            _ => {}
        }
    }
    let mut cur = ctx.value.clone();
    for seg in path {
        if seg.starts_with('@') {
            return match seg.as_str() {
                "@index" => match ctx.index {
                    Some(i) => Value::from(i as u64),
                    None => Value::Null,
                },
                "@key" => match &ctx.key {
                    Some(k) => Value::String(k.clone()),
                    None => Value::Null,
                },
                "@first" => Value::Bool(ctx.first),
                "@last" => Value::Bool(ctx.last),
                _ => Value::Null,
            };
        }
        cur = match &cur {
            Value::Object(map) => map.get(seg).cloned().unwrap_or(Value::Null),
            Value::Array(items) => match seg.parse::<usize>() {
                Ok(i) => items.get(i).cloned().unwrap_or(Value::Null),
                Err(_) => Value::Null,
            },
            _ => Value::Null,
        };
    }
    cur
}

fn eval(expr: &Expr, ctx: &Ctx) -> Result<Value, String> {
    Ok(match expr {
        Expr::Path(p) => resolve_path(p, ctx),
        Expr::Str(s) => Value::String(s.clone()),
        Expr::Num(n) => parse_num(n),
        Expr::Bool(b) => Value::Bool(*b),
        Expr::Null => Value::Null,
        Expr::Call(name, args) => Value::String(call_helper(name, args, ctx)?),
    })
}

fn parse_num(text: &str) -> Value {
    if let Ok(i) = text.parse::<u64>() {
        return Value::from(i);
    }
    if let Ok(i) = text.parse::<i64>() {
        return Value::from(i);
    }
    if let Ok(f) = text.parse::<f64>() {
        return serde_json::Number::from_f64(f).map(Value::Number).unwrap_or(Value::Null);
    }
    Value::Null
}

pub fn render_nodes(nodes: &[Node], ctx: &Ctx, name: &str) -> Result<String, String> {
    let mut out = String::new();
    for node in nodes {
        match node {
            Node::Text(t) => out.push_str(t),
            Node::Expr(expr, line, col) => {
                let v = eval(expr, ctx).map_err(|e| format!("Error rendering \"{name}\" line {line}, col {col}: {e}"))?;
                out.push_str(&render_value(&v));
            }
            Node::Block {
                helper,
                args,
                body,
                else_body,
                line,
                col,
            } => {
                let res = (|| -> Result<String, String> {
                    match helper.as_str() {
                        "if" => {
                            let cond = args
                                .first()
                                .ok_or_else(|| format!("Helper/Decorator {helper} param at index 0 required but not found"))?;
                            let v = eval(cond, ctx)?;
                            if truthy(&v) {
                                render_nodes(body, ctx, name)
                            } else {
                                render_nodes(else_body, ctx, name)
                            }
                        }
                        "unless" => {
                            let cond = args
                                .first()
                                .ok_or_else(|| format!("Helper/Decorator {helper} param at index 0 required but not found"))?;
                            let v = eval(cond, ctx)?;
                            if !truthy(&v) {
                                render_nodes(body, ctx, name)
                            } else {
                                render_nodes(else_body, ctx, name)
                            }
                        }
                        "each" => {
                            let arg = args
                                .first()
                                .ok_or_else(|| format!("Helper/Decorator {helper} param at index 0 required but not found"))?;
                            let v = eval(arg, ctx)?;
                            let mut res = String::new();
                            match &v {
                                Value::Array(items) => {
                                    let len = items.len();
                                    for (i, item) in items.iter().enumerate() {
                                        let sub = Ctx {
                                            value: item,
                                            index: Some(i),
                                            key: None,
                                            first: i == 0,
                                            last: i + 1 == len,
                                            in_each: true,
                                        };
                                        res.push_str(&render_nodes(body, &sub, name)?);
                                    }
                                }
                                Value::Object(map) => {
                                    let len = map.len();
                                    for (i, (k, item)) in map.iter().enumerate() {
                                        let sub = Ctx {
                                            value: item,
                                            index: Some(i),
                                            key: Some(k.clone()),
                                            first: i == 0,
                                            last: i + 1 == len,
                                            in_each: true,
                                        };
                                        res.push_str(&render_nodes(body, &sub, name)?);
                                    }
                                }
                                _ => {}
                            }
                            if res.is_empty() {
                                render_nodes(else_body, ctx, name)
                            } else {
                                Ok(res)
                            }
                        }
                        other => Err(format!("Helper not found {other}")),
                    }
                })()
                .map_err(|e| format!("Error rendering \"{name}\" line {line}, col {col}: {e}"))?;
                out.push_str(&res);
            }
        }
    }
    Ok(out)
}

fn arg_value(args: &[Expr], idx: usize, ctx: &Ctx) -> Result<Option<Value>, String> {
    if idx >= args.len() {
        return Ok(None);
    }
    Ok(Some(eval(&args[idx], ctx)?))
}

fn param_str(name: &str, pname: &str, args: &[Expr], idx: usize, ctx: &Ctx) -> Result<String, String> {
    match arg_value(args, idx, ctx)? {
        Some(Value::String(s)) => Ok(s),
        Some(_) => Err(format!(
            "Helper/Decorator {name} param with name {pname} type mismatch for str"
        )),
        None => Err(format!(
            "Helper/Decorator {name} param with name {pname} required but not found"
        )),
    }
}

fn param_u64(name: &str, pname: &str, args: &[Expr], idx: usize, ctx: &Ctx) -> Result<u64, String> {
    match arg_value(args, idx, ctx)? {
        Some(Value::Number(n)) => match n.as_u64() {
            Some(v) => Ok(v),
            None => Err(format!(
                "Helper/Decorator {name} param with name {pname} type mismatch for u64"
            )),
        },
        Some(_) => Err(format!(
            "Helper/Decorator {name} param with name {pname} type mismatch for u64"
        )),
        None => Err(format!(
            "Helper/Decorator {name} param with name {pname} required but not found"
        )),
    }
}

fn level_color(level: &str) -> u8 {
    let t = level.trim().to_lowercase();
    match t.as_str() {
        "trace" => 36,
        "debug" => 34,
        "info" => 32,
        "warn" | "warning" => 33,
        "err" | "error" => 31,
        _ => 35,
    }
}

pub fn call_helper(name: &str, args: &[Expr], ctx: &Ctx) -> Result<String, String> {
    match name {
        "bold" => {
            let t = param_str(name, "t", args, 0, ctx)?;
            Ok(format!("\x1b[1m{t}\x1b[0m"))
        }
        "red" | "green" | "yellow" | "blue" | "cyan" => {
            let t = param_str(name, "t", args, 0, ctx)?;
            let code = match name {
                "red" => 31,
                "green" => 32,
                "yellow" => 33,
                "blue" => 34,
                _ => 36,
            };
            Ok(format!("\x1b[{code}m{t}\x1b[0m"))
        }
        "uppercase" => {
            let t = param_str(name, "t", args, 0, ctx)?;
            Ok(t.to_uppercase())
        }
        "fixed_size" => {
            let n = param_u64(name, "isize", args, 0, ctx)?;
            let t = param_str(name, "t", args, 1, ctx)?;
            let len = t.chars().count();
            if len > n as usize {
                Ok(t.chars().take(n as usize).collect())
            } else {
                let pad = " ".repeat(n as usize - len);
                Ok(format!("{pad}{t}"))
            }
        }
        "min_size" => {
            let n = param_u64(name, "isize", args, 0, ctx)?;
            let t = param_str(name, "t", args, 1, ctx)?;
            let len = t.chars().count();
            if len < n as usize {
                let pad = " ".repeat(n as usize - len);
                Ok(format!("{pad}{t}"))
            } else {
                Ok(t)
            }
        }
        "color_rgb" => {
            let r = param_u64(name, "r", args, 0, ctx)?;
            let g = param_u64(name, "g", args, 1, ctx)?;
            let b = param_u64(name, "b", args, 2, ctx)?;
            let t = param_str(name, "t", args, 3, ctx)?;
            let _ = u8::try_from(r).map_err(|_| crate::fail::panic_loc(
                "src/template.rs:38:46",
                "called `Result::unwrap()` on an `Err` value: TryFromIntError(())",
            ));
            Ok(format!("\x1b[38;2;{r};{g};{b}m{t}\x1b[0m"))
        }
        "level_style" => {
            let t = param_str(name, "t", args, 0, ctx)?;
            let code = level_color(&t);
            Ok(format!("\x1b[1;{code}m{t}\x1b[0m"))
        }
        "__partial__" => {
            let pname = match args.first() {
                Some(Expr::Str(s)) => s.clone(),
                _ => String::new(),
            };
            Err(format!("Partial not found {pname}"))
        }
        other => Err(format!("Helper not found {other}")),
    }
}

/// Compiles a template, panicking like the original implementation does.
pub fn compile(name: &str, src: &str, panic_location: &str) -> Template {
    let mut p = Parser::new(src);
    match p.parse_nodes(false, None, false) {
        Ok((nodes, None)) => Template {
            nodes,
            name: name.to_string(),
        },
        Ok((_, Some(_))) => Template {
            nodes: Vec::new(),
            name: name.to_string(),
        },
        Err(e) => {
            let msg = format!("Template invalid: {}", debug_error(&e, name, src));
            crate::fail::panic_at(panic_location, &msg)
        }
    }
}

pub fn render(t: &Template, ctx: &Ctx) -> Result<String, String> {
    render_nodes(&t.nodes, ctx, &t.name)
}

fn debug_error(e: &SynErr, name: &str, src: &str) -> String {
    let line_text = line_text_of(src, e.line);
    let line_len = line_text.chars().count();
    let mut segment = format!("{:>4} | {}\n", e.line - 1, line_text);
    segment.push_str("     |");
    if e.col <= line_len && line_len > 0 {
        segment.push_str(&"-".repeat(e.col));
        segment.push('^');
        if line_len > e.col + 1 {
            segment.push_str(&"-".repeat(line_len - e.col - 1));
        }
    } else {
        segment.push_str(&"-".repeat(line_len));
    }
    segment.push('\n');
    format!(
        "TemplateError {{ reason: InvalidSyntax({:?}), template_name: Some(\"{name}\"), line_no: Some({}), column_no: Some({}), segment: Some({:?}) }}",
        e.reason, e.line, e.col, segment
    )
}

fn line_text_of(src: &str, line: usize) -> String {
    src.split('\n')
        .nth(line - 1)
        .map(|s| s.trim_end_matches('\r').to_string())
        .unwrap_or_default()
}
