use clap::Arg;
use clap::Command;
use serde_json::Value;
use std::io::BufRead;

fn build_command() -> Command {
    Command::new("fblog")
        .version("4.17.0")
        .about("json log viewer")
        .arg(
            Arg::new("input")
                .value_name("INPUT")
                .default_value("-")
                .help("Sets the input file to use, otherwise assumes stdin"),
        )
        .arg(
            Arg::new("additional_value")
                .short('a')
                .long("additional-value")
                .value_name("additional-value")
                .action(clap::ArgAction::Append)
                .help("adds additional values"),
        )
        .arg(
            Arg::new("config_file")
                .long("config-file")
                .value_name("config-file")
                .action(clap::ArgAction::Set)
                .help("configuration file to load"),
        )
        .arg(
            Arg::new("message_key")
                .short('m')
                .long("message-key")
                .value_name("message-key")
                .action(clap::ArgAction::Append)
                .help("Adds an additional key to detect the message in the log entry. The first matching key will be assigned to `fblog_message`."),
        )
        .arg(
            Arg::new("print_lua")
                .long("print-lua")
                .action(clap::ArgAction::SetTrue)
                .help("Prints lua init expressions. Used for fblog debugging."),
        )
        .arg(
            Arg::new("time_key")
                .short('t')
                .long("time-key")
                .value_name("time-key")
                .action(clap::ArgAction::Append)
                .help("Adds an additional key to detect the time in the log entry. The first matching key will be assigned to `fblog_timestamp`."),
        )
        .arg(
            Arg::new("level_key")
                .short('l')
                .long("level-key")
                .value_name("level-key")
                .action(clap::ArgAction::Append)
                .help("Adds an additional key to detect the level in the log entry. The first matching key will be assigned to `fblog_level`."),
        )
        .arg(
            Arg::new("map_level")
                .long("map-level")
                .value_name("from=to")
                .action(clap::ArgAction::Append)
                .value_parser(clap::builder::RangedU64ValueParser::<u64>::new())
                .help("Rewrite the log level from one value to another."),
        )
        .arg(
            Arg::new("dump_all")
                .short('d')
                .long("dump-all")
                .action(clap::ArgAction::SetTrue)
                .help("dumps all values"),
        )
        .arg(
            Arg::new("excluded_value")
                .short('x')
                .long("excluded-value")
                .value_name("excluded-value")
                .action(clap::ArgAction::Append)
                .conflicts_with("additional_value")
                .help("Excludes values (--dump-all is enabled implicitly)"),
        )
        .arg(
            Arg::new("with_prefix")
                .short('p')
                .long("with-prefix")
                .action(clap::ArgAction::SetTrue)
                .help("consider all text before opening curly brace as prefix"),
        )
        .arg(
            Arg::new("filter")
                .short('f')
                .long("filter")
                .value_name("filter")
                .action(clap::ArgAction::Append)
                .help("lua expression to filter log entries. `message ~= nil and string.find(message, \"text.*\") ~= nil`"),
        )
        .arg(
            Arg::new("no_implicit_filter_return_statement")
                .long("no-implicit-filter-return-statement")
                .action(clap::ArgAction::SetTrue)
                .help("if you pass a filter expression 'return' is automatically prepended. Pass this switch to disable the implicit return."),
        )
        .arg(
            Arg::new("main_line_format")
                .long("main-line-format")
                .value_name("main-line-format")
                .action(clap::ArgAction::Set)
                .help("Formats the main fblog output. All log values can be used. fblog provides sanitized variables starting with `fblog_`."),
        )
        .arg(
            Arg::new("additional_value_format")
                .long("additional-value-format")
                .value_name("additional-value-format")
                .action(clap::ArgAction::Set)
                .help("Formats the additional value fblog output."),
        )
        .arg(
            Arg::new("substitute")
                .short('s')
                .long("substitute")
                .action(clap::ArgAction::SetTrue)
                .help("Enable substitution of placeholders in the log messages with their corresponding values from the context."),
        )
        .arg(
            Arg::new("context_key")
                .short('c')
                .long("context-key")
                .value_name("context-key")
                .action(clap::ArgAction::Set)
                .help("Use this key as the source of substitutions for the message. Value can either be an array ({1}) or an object ({key})."),
        )
        .arg(
            Arg::new("placeholder_format")
                .short('F')
                .long("placeholder-format")
                .value_name("placeholder-format")
                .action(clap::ArgAction::Set)
                .help("The format that should be used for substituting values in the message, where the key is the literal word `key`. Example: [[key]] or ${key}."),
        )
}

fn parse_map_level(value: &str) -> Result<(String, String), String> {
    match value.split_once('=') {
        Some((from, to)) => Ok((from.to_string(), to.to_string())),
        None => Err(format!("missing '='")),
    }
}

fn main() {
    let cmd = build_command();
    let matches = cmd.clone().get_matches();
    let _ = cmd;

    // 1. configuration
    let config = match matches.get_one::<String>("config_file") {
        Some(path) => match config::load(path) {
            Ok(config) => config,
            Err(_) => fail::panic_at("src/main.rs:35:50", "Could not load config file."),
        },
        None => config::load_default(),
    };

    // 2. additional values and exclusions
    let dump_all = matches.get_flag("dump_all")
        || matches.contains_id("excluded_value");
    let mut exclusions: Vec<String> = config.dump_all_exclude.clone();
    if let Some(vals) = matches.get_many::<String>("excluded_value") {
        for v in vals {
            exclusions.push(v.clone());
        }
    }
    let mut additional: Vec<String> = config.always_print_fields.clone();
    if let Some(vals) = matches.get_many::<String>("additional_value") {
        for v in vals {
            additional.push(v.clone());
        }
    }

    // 3. level map
    let mut level_map = config.level_map.clone();
    if let Some(vals) = matches.get_many::<String>("map_level") {
        for v in vals {
            if let Ok((from, to)) = parse_map_level(v) {
                level_map.insert(from, to);
            }
        }
    }

    // 4. placeholder format
    let placeholder_format = matches
        .get_one::<String>("placeholder_format")
        .cloned()
        .unwrap_or_else(|| "{key}".to_string());
    let (ph_prefix, ph_suffix) = match placeholder_format.split_once("key") {
        Some(v) => v,
        None => fail::panic_at(
            "src/main.rs:68:23",
            "Invalid placeholder format: The identifier `key` is missing",
        ),
    };

    // 5. templates
    let main_template = template::compile(
        "main_line",
        &config.main_line_format,
        "src/template.rs:96:65",
    );
    let additional_template = template::compile(
        "additional_value",
        &config.additional_value_format,
        "src/template.rs:99:10",
    );

    let message_keys = {
        let mut keys = config.message_keys.clone();
        if let Some(vals) = matches.get_many::<String>("message_key") {
            keys = vals.map(|s| s.to_string()).collect();
        }
        keys
    };
    let time_keys = {
        let mut keys = config.time_keys.clone();
        if let Some(vals) = matches.get_many::<String>("time_key") {
            keys = vals.map(|s| s.to_string()).collect();
        }
        keys
    };
    let level_keys = {
        let mut keys = config.level_keys.clone();
        if let Some(vals) = matches.get_many::<String>("level_key") {
            keys = vals.map(|s| s.to_string()).collect();
        }
        keys
    };
    let context_key = matches
        .get_one::<String>("context_key")
        .cloned()
        .unwrap_or_else(|| "context".to_string());
    let substitute = matches.get_flag("substitute");
    let print_lua = matches.get_flag("print_lua");
    let no_implicit_return = matches.get_flag("no_implicit_filter_return_statement");
    let with_prefix = matches.get_flag("with_prefix");
    let filters: Vec<String> = matches
        .get_many::<String>("filter")
        .map(|vals| vals.map(|s| s.to_string()).collect())
        .unwrap_or_default();

    let input = matches.get_one::<String>("input").cloned().unwrap_or_default();
    let reader: Box<dyn BufRead> = if input == "-" {
        Box::new(std::io::BufReader::new(std::io::stdin().lock()))
    } else {
        match std::fs::File::open(&input) {
            Ok(file) => Box::new(std::io::BufReader::new(file)),
            Err(_) => fail::panic_at(
                "src/main.rs:105:68",
                &format!("Can't open file: {input}"),
            ),
        }
    };

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(err) => {
                println!("\x1b[1;31m??? >\x1b[0m Could not read line: {err}");
                continue;
            }
        };
        let (prefix, json_part) = if with_prefix {
            match line.find('{') {
                Some(idx) => (line[..idx].trim().to_string(), &line[idx..]),
                None => (String::new(), line.as_str()),
            }
        } else {
            (String::new(), line.as_str())
        };
        let parsed: Option<Value> = serde_json::from_str(json_part)
            .ok()
            .filter(|v| v.is_object());
        let entry = match parsed {
            Some(v) => v,
            None => {
                println!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {line}");
                continue;
            }
        };

        let message = entry::find_key_string(&entry, &message_keys);
        let level_raw = entry::find_key_string(&entry, &level_keys);
        let level = level_map.get(&level_raw).cloned().unwrap_or(level_raw);
        let time_value = entry::find_key_value(&entry, &time_keys);
        let timestamp = entry::format_time(&time_value);

        // lua filter
        if !filters.is_empty() {
            let mut pass = true;
            for f in &filters {
                let code = if no_implicit_return {
                    f.clone()
                } else {
                    format!("return {f};")
                };
                let chunk = if no_implicit_return {
                    "src/filter.rs:25:1"
                } else {
                    "src/filter.rs:23:1"
                };
                if print_lua {
                    for (k, v) in entry.as_object().unwrap().iter() {
                        println!("{} = {}", lua::sanitize_key(k), lua::lua_literal(v));
                    }
                }
                match lua::run(&code, chunk, &entry) {
                    Ok(v) => {
                        if !matches!(v, lua::Value::Nil | lua::Value::Boolean(false)) {
                            pass = true;
                        } else {
                            pass = false;
                        }
                    }
                    Err(e) => {
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: '{}'", e);
                        pass = false;
                    }
                }
            }
            if !pass {
                continue;
            }
        }

        let message = if substitute {
            entry::substitute(&message, &entry, &context_key, ph_prefix, ph_suffix)
        } else {
            message
        };

        // build the template context
        let mut root = entry.clone();
        if let Some(obj) = root.as_object_mut() {
            obj.insert("fblog_message".to_string(), Value::String(message.clone()));
            obj.insert("fblog_timestamp".to_string(), Value::String(timestamp.clone()));
            obj.insert("fblog_level".to_string(), Value::String(level.clone()));
            obj.insert("fblog_prefix".to_string(), Value::String(prefix.clone()));
        }
        let ctx = template::Ctx::new(&root);
        match template::render(&main_template, &ctx) {
            Ok(text) => println!("{text}"),
