//! Helpers to extract values from a json log entry.

use serde_json::Value;

/// String representation used for `fblog_message`, `fblog_level` and
/// `fblog_timestamp`.
pub fn value_to_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        _ => String::new(),
    }
}

/// Returns the first matching key's value.
pub fn find_key_value(entry: &Value, keys: &[String]) -> Value {
    if let Some(obj) = entry.as_object() {
        for key in keys {
            if let Some(v) = obj.get(key) {
                return v.clone();
            }
        }
    }
    Value::Null
}

/// Returns the first matching key's value rendered as a string.
pub fn find_key_string(entry: &Value, keys: &[String]) -> String {
    value_to_string(&find_key_value(entry, keys))
}

#[derive(Debug, Clone, PartialEq)]
pub enum Step {
    Key(String),
    Index(usize),
}

pub fn render_steps(steps: &[Step]) -> String {
    let mut out = String::new();
    for step in steps {
        match step {
            Step::Key(k) => {
                if out.is_empty() {
                    out.push_str(k);
                } else {
                    out.push_str(" > ");
                    out.push_str(k);
                }
            }
            Step::Index(i) => {
                out.push_str(&format!("[{i}]"));
            }
        }
    }
    out
}

/// Splits an `-a`/`-x` style path into steps.
pub fn parse_pattern(pattern: &str) -> Vec<Step> {
    let mut steps = Vec::new();
    for part in pattern.split(" > ") {
        if part.is_empty() {
            continue;
        }
        // split off [n] indices
        let mut rest = part.as_bytes();
        let mut key_end = 0usize;
        while key_end < rest.len() && rest[key_end] != b'[' {
            key_end += 1;
        }
        let key = String::from_utf_lossy(&rest[..key_end]).to_string();
        if !key.is_empty() {
            steps.push(Step::Key(key));
        }
        rest = &rest[key_end..];
        while rest.starts_with(b"[") {
            let mut i = 1;
            while i < rest.len() && rest[i] != b']' {
                i += 1;
            }
            let num = String::from_utf_lossy(&rest[1..i]).to_string();
            if let Ok(n) = num.parse::<usize>() {
                steps.push(Step::Index(n));
            } else {
                steps.push(Step::Key(format!("[{num}]")));
            }
            if i >= rest.len() {
                break;
            }
            rest = &rest[i + 1..];
        }
    }
    steps
}

pub fn steps_start_with(steps: &[Step], pattern: &[Step]) -> bool {
    if pattern.len() > steps.len() {
        return false;
    }
    for (i, p) in pattern.iter().enumerate() {
        if steps[i] != *p {
            return false;
        }
    }
    true
}

pub fn path_matches(path: &[Step], pattern: &str) -> bool {
    let p = parse_pattern(pattern);
    steps_start_with(path, &p)
}

/// Renders all leaves of a json value, in the order fblog does.
pub fn dump_entry(
    path: &str,
    value: &Value,
    parent_is_array: bool,
    exclusions: &[String],
    out: &mut Vec<(String, String)>,
) {
    let _ = parent_is_array;
    dump_steps(&[], value, false, exclusions, out, path);
}

fn dump_steps(
    steps: &[Step],
    value: &Value,
    parent_is_array: bool,
    exclusions: &[String],
    out: &mut Vec<(String, String)>,
    _path: &str,
) {
    match value {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let v = map.get(k).unwrap();
                if v.is_null() {
                    continue;
                }
                let mut new_steps: Vec<Step> = steps.to_vec();
                new_steps.push(Step::Key(k.clone()));
                dump_steps(&new_steps, v, false, exclusions, out, _path);
            }
        }
        Value::Array(items) => {
            let base = if parent_is_array { 1usize } else { 0usize };
            for (i, item) in items.iter().enumerate() {
                let mut new_steps: Vec<Step> = steps.to_vec();
                new_steps.push(Step::Index(i + base));
                dump_steps(&new_steps, item, true, exclusions, out, _path);
            }
        }
        other => {
            let path_str = render_steps(steps);
            if exclusions.iter().any(|e| e == &path_str) {
                return;
            }
            let rendered = if parent_is_array {
                other.to_string()
            } else {
                match other {
                    Value::String(s) => s.clone(),
                    Value::Number(n) => n.to_string(),
                    Value::Bool(b) => b.to_string(),
                    _ => String::new(),
                }
            };
            out.push((path_str, rendered));
        }
    }
}

/// Formats a timestamp the way fblog does: integers are interpreted as unix
/// epoch seconds or milliseconds, whichever is closest to the current time.
pub fn format_time(v: &Value) -> String {
    match v {
        Value::Number(n) => match n.as_i64() {
            Some(i) => format_epoch(i).unwrap_or_else(|| n.to_string()),
            None => n.to_string(),
        },
        other => value_to_string(other),
    }
}

const MIN_SECONDS: i64 = -8334601228800;
const MAX_SECONDS: i64 = 821026687679;
const MIN_MILLIS: i64 = -8334601228800000;
const MAX_MILLIS: i64 = 8210266876799999;

pub fn format_epoch(v: i64) -> Option<String> {
    let s_valid = (MIN_SECONDS..=MAX_SECONDS).contains(&v);
    let m_valid = (MIN_MILLIS..=MAX_MILLIS).contains(&v);
    let now = crate::now_seconds();
    let use_millis = if s_valid && m_valid {
        let ds = (v as f64 - now).abs();
        let dm = (v as f64 / 1000.0 - now).abs();
        !(ds < dm)
    } else {
        m_valid
    };
    let secs = if use_millis { v / 1000 } else { v };
    Some(crate::iso_utc(secs))
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (y + if m <= 2 { 1 } else { 0 }, m, d)
}

/// Formats a unix timestamp as UTC `%Y-%m-%dT%H:%M:%S`.
pub fn iso_utc(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = rem / 3600;
    let mi = (rem % 3600) / 60;
    let s = rem % 60;
    let year = if (-9999..=9999).contains(&y) {
        format!("{y:04}")
    } else if y > 0 {
        format!("+{y}")
    } else {
        format!("-{}", -y)
    };
    format!("{year}-{m:02}-{d:02}T{h:02}:{mi:02}:{s:02}")
}

const PLACEHOLDER_CHARS: fn(char) -> bool = |c: char| c.is_ascii_alphanumeric() || c == '_' || c == '-';

/// Substitutes `{{key}}`-like placeholders in the message.
pub fn substitute(
    message: &str,
    entry: &Value,
    context_key: &str,
    ph_prefix: &str,
    ph_suffix: &str,
) -> String {
    let context = match entry.as_object().and_then(|o| o.get(context_key)) {
        Some(v) => v.clone(),
        None => return message.to_string(),
    };
    let has_context = matches!(context, Value::Object(_) | Value::Array(_));
    let chars: Vec<char> = message.chars().collect();
    let prefix_chars: Vec<char> = ph_prefix.chars().collect();
    let suffix_chars: Vec<char> = ph_suffix.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        // look for the placeholder prefix
        if chars[i..].starts_with(&prefix_chars) && !prefix_chars.is_empty() {
            let mut j = i + prefix_chars.len();
            let start = j;
            while j < chars.len() && PLACEHOLDER_CHARS(chars[j]) {
                j += 1;
            }
            if j > start && chars[j..].starts_with(&suffix_chars) {
                let name: String = chars[start..j].iter().collect();
                out.push_str(&render_placeholder(&name, &context, has_context, ph_prefix, ph_suffix));
                i = j + suffix_chars.len();
                continue;
            }
            out.push(chars[i]);
            i += 1;
            continue;
        }
        if prefix_chars.is_empty() {
            // no prefix: the placeholder starts at an identifier character
            if PLACEHOLDER_CHARS(chars[i]) {
                let start = i;
                let mut j = i;
                while j < chars.len() && PLACEHOLDER_CHARS(chars[j]) {
                    j += 1;
                }
                let name: String = chars[start..j].iter().collect();
                out.push_str(&render_placeholder(&name, &context, has_context, ph_prefix, ph_suffix));
                i = j;
                continue;
            }
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn render_placeholder(
    name: &str,
    context: &Value,
    has_context: bool,
    ph_prefix: &str,
    ph_suffix: &str,
) -> String {
    let value = lookup(name, context);
    match value {
        Some(v) => render_styled(&v),
        None => {
            if has_context {
                format!(
                    "\x1b[2m{ph_prefix}\x1b[0m\x1b[1;31m{name}\x1b[0m\x1b[2m{ph_suffix}\x1b[0m"
                )
            } else {
                format!(
                    "\x1b[2m{ph_prefix}\x1b[0m\x1b[1;31m{name}\x1b[0m\x1b[2m{ph_suffix}\x1b[0m"
                )
            }
        }
    }
}

fn lookup(name: &str, context: &Value) -> Option<Value> {
    match context {
        Value::Object(map) => map.get(name).cloned(),
        Value::Array(items) => name.parse::<usize>().ok().and_then(|i| items.get(i).cloned()),
        _ => None,
    }
}

pub fn render_styled(v: &Value) -> String {
    match v {
        Value::String(s) => format!("\x1b[1;33m{s}\x1b[0m"),
        Value::Number(n) => format!("\x1b[1;36m{}\x1b[0m", n),
        Value::Bool(b) => {
            if *b {
                "\x1b[1;32mtrue\x1b[0m".to_string()
            } else {
                "\x1b[1;31mfalse\x1b[0m".to_string()
            }
        }
        Value::Null => "\x1b[1mnull\x1b[0m".to_string(),
        Value::Array(items) => {
            let mut out = String::from("\x1b[2m[\x1b[0m");
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push_str("\x1b[2m, \x1b[0m");
                }
                out.push_str(&render_styled(item));
            }
            out.push_str("\x1b[2m]\x1b[0m");
            out
        }
        Value::Object(map) => {
            let mut out = String::from("\x1b[2m{\x1b[0m");
            for (i, (k, item)) in map.iter().enumerate() {
                if i > 0 {
                    out.push_str("\x1b[2m, \x1b[0m");
                }
                out.push_str(&format!("\x1b[35m{k}\x1b[0m\x1b[2m: \x1b[0m"));
                out.push_str(&render_styled(item));
            }
            out.push_str("\x1b[2m}\x1b[0m");
            out
        }
    }
}
