pub fn format_epoch(v: i64) -> Option<String> {
    let s_valid = (MIN_SECONDS..=MAX_SECONDS).contains(&v);
    let m_valid = (MIN_MILLIS..=MAX_MILLIS).contains(&v);
    let now = crate::now_seconds();
    let use_millis = if s_valid && m_valid {
        let ds = (v as f64 - now).abs();
        let dm = (v as f64 / 1000.0 - now).abs();
        !(ds < dm)
    } else {
        m_valid
    };
    let secs = if use_millis { v / 1000 } else { v };
    Some(crate::iso_utc(secs))
