#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Name(String),
    Number(String),
    Str(String),
    Keyword(&'static str),
    Punct(&'static str),
    Eof,
}

struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Lexer {
            src: src.as_bytes(),
            pos: 0,
            line: 1,
        }
    }

    fn skip_ws(&mut self) -> Result<(), String> {
        while self.pos < self.src.len() {
            let c = self.src[self.pos];
            match c {
                b' ' | b'\t' | b'\r' | b'\n' => {
                    if c == b'\n' {
                        self.line += 1;
                    }
                    self.pos += 1;
                }
                b'-' if self.pos + 1 < self.src.len() && self.src[self.pos + 1] == b'-' => {
                    if self.pos + 3 < self.src.len()
                        && self.src[self.pos + 2] == b'['
                        && self.src[self.pos + 3] == b'['
                    {
                        // long comment
                        self.pos += 4;
                        while self.pos + 1 < self.src.len() {
                            if self.src[self.pos] == b']' && self.src[self.pos + 1] == b']' {
                                self.pos += 2;
                                break;
                            }
                            if self.src[self.pos] == b'\n' {
                                self.line += 1;
                            }
                            self.pos += 1;
                        }
                        if self.pos + 1 < self.src.len() {
                            self.pos += 2;
                        } else {
                            self.pos = self.src.len();
                        }
                    } else {
                        while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
                            self.pos += 1;
                        }
                    }
                }
                _ => return Ok(()),
            }
        }
        Ok(())
    }

    fn next(&mut self) -> Result<Tok, String> {
        self.skip_ws()?;
        if self.pos >= self.src.len() {
            return Ok(Tok::Eof);
        }
        let c = self.src[self.pos];
        if c.is_ascii_alphabetic() || c == b'_' {
            let start = self.pos;
            while self.pos < self.src.len()
                && (self.src[self.pos].is_ascii_alphanumeric() || self.src[self.pos] == b'_')
            {
                self.pos += 1;
            }
            let name = std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string();
            return Ok(match name.as_str() {
                "and" | "break" | "do" | "else" | "elseif" | "end" | "false" | "for"
                | "function" | "goto" | "if" | "in" | "local" | "nil" | "not" | "or"
                | "repeat" | "return" | "then" | "true" | "until" | "while" => {
                    Tok::Keyword(Box::leak(name.clone().into_boxed_str()))
                }
                _ => Tok::Name(name),
            });
        }
        if c.is_ascii_digit() || (c == b'.' && self.pos + 1 < self.src.len() && self.src[self.pos + 1].is_ascii_digit())
        {
            let start = self.pos;
            if c == b'0' && self.pos + 1 < self.src.len() && (self.src[self.pos + 1] | 32) == b'x' {
                self.pos += 2;
                while self.pos < self.src.len()
                    && (self.src[self.pos].is_ascii_hexdigit() || self.src[self.pos] == b'.' || (self.src[self.pos] | 32) == b'p')
                {
                    self.pos += 1;
                }
                if self.pos < self.src.len() && (self.src[self.pos] | 32) == b'p' {
                    self.pos += 1;
                    if self.pos < self.src.len() && (self.src[self.pos] == b'-' || self.src[self.pos] == b'+') {
                        self.pos += 1;
                    }
                    while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
                        self.pos += 1;
                    }
                }
                return Ok(Tok::Number(
                    std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string(),
                ));
            }
            while self.pos < self.src.len() && (self.src[self.pos].is_ascii_digit() || self.src[self.pos] == b'.') {
                self.pos += 1;
            }
            if self.pos < self.src.len() && (self.src[self.pos] | 32) == b'e' {
                self.pos += 1;
                if self.pos < self.src.len() && (self.src[self.pos] == b'-' || self.src[self.pos] == b'+') {
                    self.pos += 1;
                }
                while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
                    self.pos += 1;
                }
            }
            if self.pos < self.src.len() && (self.src[self.pos] | 32) == b'u'
                && self.pos + 1 < self.src.len()
                && (self.src[self.pos + 1] | 32) == b'l'
                && self.pos + 2 < self.src.len()
                && (self.src[self.pos + 2] | 32) == b'l'
            {
                self.pos += 3;
            }
            return Ok(Tok::Number(
                std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string(),
            ));
        }
        if c == b'"' || c == b'\'' {
            let quote = c;
            self.pos += 1;
            let mut out = String::new();
            while self.pos < self.src.len() {
                let ch = self.src[self.pos];
                self.pos += 1;
                if ch == quote {
                    return Ok(Tok::Str(out));
                }
                if ch == b'\\' {
                    if self.pos >= self.src.len() {
                        break;
                    }
                    let e = self.src[self.pos];
                    self.pos += 1;
                    match e {
                        b'n' => out.push('\n'),
                        b't' => out.push('\t'),
                        b'r' => out.push('\r'),
                        b'a' => out.push('\u{7}'),
                        b'b' => out.push('\u{8}'),
                        b'f' => out.push('\u{c}'),
                        b'v' => out.push('\u{b}'),
                        b'\\' => out.push('\\'),
                        b'"' => out.push('"'),
                        b'\'' => out.push('\''),
                        b'\n' => out.push('\n'),
                        b'x' => {
                            let mut v = 0u32;
                            let mut n = 0;
                            while n < 2 && self.pos < self.src.len() && self.src[self.pos].is_ascii_hexdigit() {
                                v = v * 16 + (self.src[self.pos] as char).to_digit(16).unwrap();
                                self.pos += 1;
                                n += 1;
                            }
                            out.push(char::from_u32(v).unwrap_or('\0'));
                        }
                        b'0'..=b'9' => {
                            let mut v = (e - b'0') as u32;
                            let mut n = 1;
                            while n < 3 && self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
                                v = v * 10 + (self.src[self.pos] - b'0') as u32;
                                self.pos += 1;
                                n += 1;
                            }
                            out.push(char::from_u32(v).unwrap_or('\0'));
                        }
                        b'u' => {
                            if self.pos < self.src.len() && self.src[self.pos] == b'{' {
                                self.pos += 1;
                                let mut v = 0u32;
                                while self.pos < self.src.len() && self.src[self.pos] != b'}' {
                                    v = v * 16 + (self.src[self.pos] as char).to_digit(16).unwrap_or(0);
                                    self.pos += 1;
                                }
                                if self.pos < self.src.len() {
                                    self.pos += 1;
                                }
                                out.push(char::from_u32(v).unwrap_or('\0'));
                            }
                        }
                        _ => out.push(e as char),
                    }
                    continue;
                }
                if ch == b'\n' {
                    self.line += 1;
                    return Err("unfinished string".to_string());
                }
                out.push(ch as char);
            }
            return Err("unfinished string".to_string());
        }
        if c == b'['
            && self.pos + 1 < self.src.len()
            && (self.src[self.pos + 1] == b'[' || self.src[self.pos + 1] == b'=')
        {
            // long string
            let mut eq = 0;
            let mut p = self.pos + 1;
            while p < self.src.len() && self.src[p] == b'=' {
                eq += 1;
                p += 1;
            }
            if p < self.src.len() && self.src[p] == b'[' {
                p += 1;
                if p < self.src.len() && self.src[p] == b'\n' {
                    p += 1;
                    self.line += 1;
                }
                let start = p;
                let close = format!("]{}]", "=".repeat(eq));
                while p < self.src.len() {
                    if self.src[p..].starts_with(close.as_bytes()) {
                        break;
                    }
                    if self.src[p] == b'\n' {
                        self.line += 1;
                    }
                    p += 1;
                }
                let text = String::from_utf_lossy(&self.src[start..p]).to_string();
                self.pos = (p + close.len()).min(self.src.len());
                return Ok(Tok::Str(text));
            }
            self.pos += 1;
            return Ok(Tok::Punct("["));
        }
        let two = |a: u8, b: u8| self.pos + 1 < self.src.len() && self.src[self.pos] == a && self.src[self.pos + 1] == b;
        for (tok, len) in [
            ("...", 3usize),
            ("//", 2),
            ("==", 2),
            ("~=", 2),
            ("<=", 2),
            (">=", 2),
            ("::", 2),
            ("<<", 2),
            (">>", 2),
        ] {
            if len == 3 {
                if self.pos + 2 < self.src.len()
                    && self.src[self.pos] == b'.'
                    && self.src[self.pos + 1] == b'.'
                    && self.src[self.pos + 2] == b'.'
                {
                    self.pos += 3;
                    return Ok(Tok::Punct("..."));
                }
            } else if two(tok.as_bytes()[0], tok.as_bytes()[1]) {
                self.pos += 2;
                return Ok(Tok::Punct(tok));
            }
        }
        if two(b'.', b'.') {
            self.pos += 2;
            return Ok(Tok::Punct(".."));
        }
        let single = [
            b'+', b'-', b'*', b'/', b'%', b'^', b'#', b'=', b'~', b'<', b'>', b'(', b')',
            b'{', b'}', b'[', b']', b';', b':', b',', b'.', b'&', b'|',
        ];
        if single.contains(&c) {
            self.pos += 1;
            return Ok(Tok::Punct(std::str::from_utf8(&[c]).unwrap()));
        }
        Err(format!("unexpected symbol near '{}'", c as char))
    }
}
