//! A small Lua interpreter (used for the `--filter` expressions).

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone)]
pub enum Value {
    Nil,
    Boolean(bool),
    Integer(i64),
    Float(f64),
    Str(Rc<String>),
    Table(Rc<RefCell<Table>>),
    Function(Rc<LuaFunction>),
    Native(Rc<NativeFn>),
}

pub type NativeFn = fn(&mut Interp, Vec<Value>) -> Result<Vec<Value>, String>;

pub struct LuaFunction {
    pub params: Vec<String>,
    pub is_vararg: bool,
    pub body: Vec<Stmt>,
    pub env: Rc<Scope>,
    pub name: Option<String>,
    pub chunk: String,
}

pub struct Table {
    pub entries: Vec<(Value, Value)>,
    pub index: HashMap<String, usize>,
}

impl Table {
    pub fn new() -> Self {
        Table {
            entries: Vec::new(),
            index: HashMap::new(),
        }
    }

    pub fn get(&self, key: &Value) -> Value {
        match self.index.get(&key_key(key)) {
            Some(i) => self.entries[*i].1.clone(),
            None => Value::Nil,
        }
    }

    pub fn set(&mut self, key: Value, value: Value) {
        let k = key_key(&key);
        if let Some(i) = self.index.get(&k) {
            self.entries[*i].1 = value;
        } else {
            self.index.insert(k, self.entries.len());
            self.entries.push((key, value));
        }
    }

    pub fn iter_pairs(&self) -> impl Iterator<Item = (Value, Value)> + '_ {
        self.entries
            .iter()
            .filter(|(_, v)| !matches!(v, Value::Nil))
            .map(|(k, v)| (k.clone(), v.clone()))
    }

    pub fn length(&self) -> i64 {
        let mut n = 0i64;
        loop {
            if matches!(self.get(&Value::Integer(n + 1)), Value::Nil) {
                break;
            }
            n += 1;
        }
        n
    }
}

fn key_key(key: &Value) -> String {
    match key {
        Value::Nil => "n".to_string(),
        Value::Boolean(b) => format!("b{b}"),
        Value::Integer(i) => format!("i{i}"),
        Value::Float(f) => format!("f{f:?}"),
        Value::Str(s) => format!("s{s}"),
        Value::Table(t) => format!("t{:p}", Rc::as_ptr(t)),
        Value::Function(f) => format!("F{:p}", Rc::as_ptr(f)),
        Value::Native(f) => format!("N{:p}", Rc::as_ptr(f)),
    }
}

pub struct Scope {
    pub vars: RefCell<HashMap<String, Rc<RefCell<Value>>>>,
    pub parent: Option<Rc<Scope>>,
    pub globals: Rc<RefCell<Table>>,
}

impl Scope {
    fn new(parent: Option<Rc<Scope>>, globals: Rc<RefCell<Table>>) -> Self {
        Scope {
            vars: RefCell::new(HashMap::new()),
            parent,
            globals,
        }
    }

    fn lookup(&self, name: &str) -> Option<Rc<RefCell<Value>>> {
        if let Some(v) = self.vars.borrow().get(name) {
            return Some(v.clone());
        }
        match &self.parent {
            Some(p) => p.lookup(name),
            None => None,
        }
    }

    fn define(&self, name: &str, value: Value) {
        self.vars
            .borrow_mut()
            .insert(name.to_string(), Rc::new(RefCell::new(value)));
    }

    fn set(&self, name: &str, value: Value) -> bool {
        if let Some(slot) = self.lookup(name) {
            *slot.borrow_mut() = value;
            true
        } else {
            false
        }
    }
}

// ---------------------------------------------------------------- lexer

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Name(String),
    Number(String),
    Str(String),
    Keyword(&'static str),
    Punct(&'static str),
    Eof,
}

struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Lexer {
            src: src.as_bytes(),
            pos: 0,
            line: 1,
        }
    }

    fn skip_ws(&mut self) -> Result<(), String> {
        while self.pos < self.src.len() {
            let c = self.src[self.pos];
            match c {
                b' ' | b'\t' | b'\r' | b'\n' => {
                    if c == b'\n' {
                        self.line += 1;
                    }
                    self.pos += 1;
                }
                b'-' if self.pos + 1 < self.src.len() && self.src[self.pos + 1] == b'-' => {
                    if self.pos + 3 < self.src.len()
                        && self.src[self.pos + 2] == b'['
                        && self.src[self.pos + 3] == b'['
                    {
                        // long comment
                        self.pos += 4;
                        while self.pos + 1 < self.src.len() {
                            if self.src[self.pos] == b']' && self.src[self.pos + 1] == b']' {
                                self.pos += 2;
                                break;
                            }
                            if self.src[self.pos] == b'\n' {
                                self.line += 1;
                            }
                            self.pos += 1;
                        }
                        if self.pos + 1 < self.src.len() {
                            self.pos += 2;
                        } else {
                            self.pos = self.src.len();
                        }
                    } else {
                        while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
                            self.pos += 1;
                        }
                    }
                }
                _ => return Ok(()),
            }
        }
        Ok(())
    }

    fn next(&mut self) -> Result<Tok, String> {
        self.skip_ws()?;
        if self.pos >= self.src.len() {
            return Ok(Tok::Eof);
        }
        let c = self.src[self.pos];
        if c.is_ascii_alphabetic() || c == b'_' {
            let start = self.pos;
            while self.pos < self.src.len()
                && (self.src[self.pos].is_ascii_alphanumeric() || self.src[self.pos] == b'_')
            {
                self.pos += 1;
            }
            let name = std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string();
            return Ok(match name.as_str() {
                "and" | "break" | "do" | "else" | "elseif" | "end" | "false" | "for"
                | "function" | "goto" | "if" | "in" | "local" | "nil" | "not" | "or"
                | "repeat" | "return" | "then" | "true" | "until" | "while" => {
                    Tok::Keyword(Box::leak(name.clone().into_boxed_str()))
                }
                _ => Tok::Name(name),
            });
        }
