// ---------------------------------------------------------------- AST

#[derive(Clone)]
pub enum Expr {
    Nil,
    True,
    False,
    Num(Value),
    Str(String),
    Vararg,
    Name(String),
    Index(Box<Expr>, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>),
    Method(Box<Expr>, String, Vec<Expr>),
    Func(Rc<FuncAst>),
    Table(Vec<TField>),
    Bin(u8, Box<Expr>, Box<Expr>),
    Un(u8, Box<Expr>),
}

#[derive(Clone)]
pub struct FuncAst {
    pub params: Vec<String>,
    pub is_vararg: bool,
    pub body: Vec<Stmt>,
}

#[derive(Clone)]
pub enum TField {
    Item(Expr),
    Named(String, Expr),
    Keyed(Expr, Expr),
}

#[derive(Clone)]
pub enum Stmt {
    Local(Vec<String>, Vec<Expr>),
    LocalFunc(String, Rc<FuncAst>),
    Assign(Vec<Expr>, Vec<Expr>),
    ExprStmt(Expr),
    If(Vec<(Expr, Vec<Stmt>)>, Vec<Stmt>),
    While(Expr, Vec<Stmt>),
    Repeat(Vec<Stmt>, Expr),
    NumFor(String, Expr, Expr, Option<Expr>, Vec<Stmt>),
    GenFor(Vec<String>, Vec<Expr>, Vec<Stmt>),
    GlobalFunc(Vec<String>, Rc<FuncAst>),
    Return(Vec<Expr>),
    Break,
    Do(Vec<Stmt>),
}

// ---------------------------------------------------------------- parser

struct P<'a> {
    lex: Lexer<'a>,
    cur: Tok,
    src: &'a str,
    line: usize,
}

type PResult<T> = Result<T, String>;

const BIN_PREC: &[(u8, u8)] = &[
    (1, 1),  // or
    (2, 2),  // and
    (3, 3),  // < > <= >= ~= ==
    (4, 3),  // .. (right assoc)
    (5, 5),  // + -
    (6, 6),  // * / // %
    (7, 7),  // ~ & | << >> (not real lua)
    (9, 8),  // ^ (right assoc)
];

fn prec_of(tok: &str) -> Option<(u8, u8)> {
    Some(match tok {
        "or" => (1, 1),
        "and" => (2, 2),
        "<" | ">" | "<=" | ">=" | "~=" | "==" => (3, 3),
        ".." => (4, 3),
        "+" | "-" => (5, 5),
        "*" | "/" | "//" | "%" => (6, 6),
        "^" => (9, 8),
        _ => return None,
    })
}

fn unop_prec() -> u8 {
    8
}

impl<'a> P<'a> {
    fn new(src: &'a str) -> Self {
        let mut lex = Lexer::new(src);
        let cur = lex.next().unwrap_or(Tok::Eof);
        P {
            lex,
            cur,
            src,
            line: 1,
        }
    }

    fn advance(&mut self) -> PResult<()> {
        match self.lex.next() {
            Ok(t) => {
                self.line = self.lex.line;
                self.cur = t;
                Ok(())
            }
            Err(e) => Err(format!("{} near '{}'", "unexpected symbol", e)),
        }
    }

    fn err(&self, msg: &str) -> String {
        format!("{msg}")
    }

    fn check_punct(&self, p: &str) -> bool {
        matches!(&self.cur, Tok::Punct(x) if *x == p)
    }

    fn check_kw(&self, k: &str) -> bool {
        matches!(&self.cur, Tok::Keyword(x) if *x == k)
    }

    fn accept_punct(&mut self, p: &str) -> PResult<bool> {
        if self.check_punct(p) {
            self.advance()?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn accept_kw(&mut self, k: &str) -> PResult<bool> {
        if self.check_kw(k) {
            self.advance()?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn expect_punct(&mut self, p: &str) -> PResult<()> {
        if self.check_punct(p) {
            self.advance()
        } else {
            Err(self.err(&format!(
                "'{}' expected near {}",
                p,
                tok_repr(&self.cur)
            )))
        }
    }

    fn expect_name(&mut self) -> PResult<String> {
        match self.cur.clone() {
            Tok::Name(n) => {
                self.advance()?;
                Ok(n)
            }
            _ => Err(self.err(&format!(
                "<name> expected near {}",
                tok_repr(&self.cur)
            ))),
        }
    }

    fn block_ends(&self) -> bool {
        matches!(
            &self.cur,
            Tok::Eof
                | Tok::Keyword("end")
                | Tok::Keyword("else")
                | Tok::Keyword("elseif")
                | Tok::Keyword("until")
        ) || self.check_punct(";")
    }

    fn parse_chunk(&mut self) -> PResult<Vec<Stmt>> {
        let body = self.parse_block()?;
        if !matches!(self.cur, Tok::Eof) {
            return Err(self.err(&format!(
                "<eof> expected near {}",
                tok_repr(&self.cur)
            )));
        }
        Ok(body)
    }

    fn parse_block(&mut self) -> PResult<Vec<Stmt>> {
        let mut stmts = Vec::new();
        while !self.block_ends() {
            if self.check_kw("return") {
                self.advance()?;
                let mut exprs = Vec::new();
                if !self.block_ends() && !self.check_kw("end") && !self.check_kw("until") {
                    loop {
                        exprs.push(self.parse_expr()?);
                        if !self.accept_punct(",")? {
                            break;
                        }
                    }
                }
                let _ = self.accept_punct(";")?;
                stmts.push(Stmt::Return(exprs));
                break;
            }
            if self.check_kw("break") {
                self.advance()?;
                let _ = self.accept_punct(";")?;
                stmts.push(Stmt::Break);
                continue;
            }
            if self.accept_punct(";")? {
                continue;
            }
            stmts.push(self.parse_statement()?);
        }
        Ok(stmts)
    }

    fn parse_statement(&mut self) -> PResult<Stmt> {
        match self.cur.clone() {
            Tok::Keyword("if") => self.parse_if(),
            Tok::Keyword("while") => {
                self.advance()?;
                let cond = self.parse_expr()?;
                self.expect_kw("do")?;
                let body = self.parse_block()?;
                self.expect_kw("end")?;
                Ok(Stmt::While(cond, body))
            }
            Tok::Keyword("repeat") => {
                self.advance()?;
                let body = self.parse_block()?;
                self.expect_kw("until")?;
                let cond = self.parse_expr()?;
                Ok(Stmt::Repeat(body, cond))
            }
            Tok::Keyword("for") => self.parse_for(),
            Tok::Keyword("do") => {
                self.advance()?;
                let body = self.parse_block()?;
                self.expect_kw("end")?;
                Ok(Stmt::Do(body))
            }
            Tok::Keyword("local") => {
                self.advance()?;
                if self.accept_kw("function")? {
                    let name = self.expect_name()?;
                    let f = self.parse_func_body()?;
                    return Ok(Stmt::LocalFunc(name, Rc::new(f)));
                }
                let mut names = vec![self.expect_name()?];
                while self.accept_punct(",")? {
                    names.push(self.expect_name()?);
                }
                let mut exprs = Vec::new();
                if self.accept_punct("=")? {
                    loop {
                        exprs.push(self.parse_expr()?);
                        if !self.accept_punct(",")? {
                            break;
                        }
                    }
                }
                Ok(Stmt::Local(names, exprs))
            }
            Tok::Keyword("function") => {
                self.advance()?;
                let mut names = vec![self.expect_name()?];
                while self.accept_punct(".")? {
                    names.push(self.expect_name()?);
                }
                let mut method = None;
                if self.accept_punct(":")? {
                    method = Some(self.expect_name()?);
                }
                let mut f = self.parse_func_body()?;
                if method.is_some() {
                    f.params.insert(0, "self".to_string());
                }
                if method.is_some() {
                    let mut full = names.clone();
                    full.push(method.unwrap());
                    return Ok(Stmt::GlobalFunc(full, Rc::new(f)));
                }
                Ok(Stmt::GlobalFunc(names, Rc::new(f)))
            }
            _ => {
                // expression statement or assignment
                let first = self.parse_suffixed()?;
                if self.check_punct("=") || self.check_punct(",") {
                    let mut targets = vec![first];
                    while self.accept_punct(",")? {
                        targets.push(self.parse_suffixed()?);
                    }
                    self.expect_punct("=")?;
                    let mut exprs = Vec::new();
                    loop {
                        exprs.push(self.parse_expr()?);
                        if !self.accept_punct(",")? {
                            break;
                        }
                    }
                    return Ok(Stmt::Assign(targets, exprs));
                }
                match &first {
                    Expr::Call(_, _) | Expr::Method(_, _, _) => Ok(Stmt::ExprStmt(first)),
                    _ => Err(self.err(&format!(
                        "syntax error near {}",
                        tok_repr(&self.cur)
                    ))),
                }
            }
        }
    }

    fn expect_kw(&mut self, k: &str) -> PResult<()> {
        if self.check_kw(k) {
            self.advance()
        } else {
            Err(self.err(&format!(
                "'{k}' expected near {}",
                tok_repr(&self.cur)
            )))
        }
    }

    fn parse_if(&mut self) -> PResult<Stmt> {
        self.advance()?;
        let mut arms = Vec::new();
        let cond = self.parse_expr()?;
        self.expect_kw("then")?;
        let body = self.parse_block()?;
        arms.push((cond, body));
        let mut els = Vec::new();
        loop {
            if self.accept_kw("elseif")? {
                let cond = self.parse_expr()?;
                self.expect_kw("then")?;
                let body = self.parse_block()?;
                arms.push((cond, body));
                continue;
            }
            if self.accept_kw("else")? {
                els = self.parse_block()?;
            }
            break;
        }
        self.expect_kw("end")?;
        Ok(Stmt::If(arms, els))
    }

    fn parse_for(&mut self) -> PResult<Stmt> {
        self.advance()?;
        let name = self.expect_name()?;
        if self.accept_punct("=")? {
            let start = self.parse_expr()?;
            self.expect_punct(",")?;
            let limit = self.parse_expr()?;
            let step = if self.accept_punct(",")? {
                Some(self.parse_expr()?)
            } else {
                None
            };
            self.expect_kw("do")?;
            let body = self.parse_block()?;
            self.expect_kw("end")?;
            return Ok(Stmt::NumFor(name, start, limit, step, body));
        }
        let mut names = vec![name];
        while self.accept_punct(",")? {
            names.push(self.expect_name()?);
        }
        self.expect_kw("in")?;
        let mut exprs = Vec::new();
        loop {
            exprs.push(self.parse_expr()?);
            if !self.accept_punct(",")? {
                break;
            }
        }
        self.expect_kw("do")?;
        let body = self.parse_block()?;
        self.expect_kw("end")?;
        Ok(Stmt::GenFor(names, exprs, body))
    }

    fn parse_func_body(&mut self) -> PResult<FuncAst> {
        self.expect_punct("(")?;
        let mut params = Vec::new();
        let mut is_vararg = false;
        if self.check_punct(")") {
            self.advance()?;
        } else {
            loop {
                if self.check_punct("...") {
                    self.advance()?;
                    is_vararg = true;
                    break;
                }
                params.push(self.expect_name()?);
                if !self.accept_punct(",")? {
                    break;
                }
            }
            self.expect_punct(")")?;
        }
        let body = self.parse_block()?;
        self.expect_kw("end")?;
        Ok(FuncAst {
            params,
            is_vararg,
            body,
        })
    }

    fn parse_expr(&mut self) -> PResult<Expr> {
        self.parse_sub_expr(0)
    }

    fn parse_sub_expr(&mut self, limit: u8) -> PResult<Expr> {
        let mut left = self.parse_simple_expr()?;
        loop {
            let (lp, rp) = match &self.cur {
                Tok::Keyword(k) => match prec_of(k) {
                    Some(p) => p,
                    None => break,
                },
                Tok::Punct(p) => match prec_of(p) {
                    Some(q) => q,
                    None => break,
                },
                _ => break,
            };
            if lp > limit {
                break;
            }
            let op = match self.cur.clone() {
                Tok::Keyword(k) => k.as_bytes()[0],
                Tok::Punct(p) => p.as_bytes()[0],
                _ => unreachable!(),
            };
            self.advance()?;
            let right = self.parse_sub_expr(rp)?;
            left = Expr::Bin(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_simple_expr(&mut self) -> PResult<Expr> {
        match self.cur.clone() {
            Tok::Number(n) => {
                self.advance()?;
                Ok(Expr::Num(parse_lua_number(&n)))
            }
            Tok::Str(s) => {
                self.advance()?;
                Ok(Expr::Str(s))
            }
            Tok::Keyword("nil") => {
                self.advance()?;
                Ok(Expr::Nil)
            }
            Tok::Keyword("true") => {
                self.advance()?;
                Ok(Expr::True)
            }
            Tok::Keyword("false") => {
                self.advance()?;
                Ok(Expr::False)
            }
            Tok::Punct("...") => {
                self.advance()?;
                Ok(Expr::Vararg)
            }
            Tok::Punct("{") => self.parse_table(),
            Tok::Keyword("function") => {
                self.advance()?;
                Ok(Expr::Func(Rc::new(self.parse_func_body()?)))
            }
            Tok::Keyword("not") => {
                self.advance()?;
                let e = self.parse_sub_expr(unop_prec())?;
                Ok(Expr::Un(b'n', Box::new(e)))
            }
            Tok::Punct("-") => {
                self.advance()?;
                let e = self.parse_sub_expr(unop_prec())?;
                Ok(Expr::Un(b'-', Box::new(e)))
            }
            Tok::Punct("#") => {
                self.advance()?;
                let e = self.parse_sub_expr(unop_prec())?;
                Ok(Expr::Un(b'#', Box::new(e)))
            }
            Tok::Punct("~") => {
                self.advance()?;
                let e = self.parse_sub_expr(unop_prec())?;
                Ok(Expr::Un(b'~', Box::new(e)))
            }
            _ => self.parse_suffixed(),
        }
    }

    fn parse_table(&mut self) -> PResult<Expr> {
        self.expect_punct("{")?;
        let mut fields = Vec::new();
        loop {
            if self.check_punct("}") {
                self.advance()?;
                break;
            }
            if self.check_punct("[") {
                self.advance()?;
                let k = self.parse_expr()?;
                self.expect_punct("]")?;
                self.expect_punct("=")?;
                let v = self.parse_expr()?;
                fields.push(TField::Keyed(k, v));
            } else if let Tok::Name(n) = self.cur.clone() {
                // could be `name = expr`
                let save_pos = self.lex.pos;
                let save_cur = self.cur.clone();
                self.advance()?;
                if self.check_punct("=") {
                    self.advance()?;
                    let v = self.parse_expr()?;
                    fields.push(TField::Named(n, v));
                } else {
                    self.lex.pos = save_pos;
                    self.lex.line = self.line;
                    self.cur = save_cur;
                    let e = self.parse_expr()?;
                    fields.push(TField::Item(e));
                }
            } else {
                let e = self.parse_expr()?;
                fields.push(TField::Item(e));
            }
            if !self.accept_punct(",")? && !self.accept_punct(";")? {
                break;
            }
        }
        Ok(Expr::Table(fields))
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        match self.cur.clone() {
            Tok::Name(n) => {
                self.advance()?;
                Ok(Expr::Name(n))
            }
            Tok::Punct("(") => {
                self.advance()?;
                let e = self.parse_expr()?;
                self.expect_punct(")")?;
                Ok(e)
            }
            _ => Err(self.err(&format!(
                "unexpected symbol near {}",
                tok_repr(&self.cur)
            ))),
        }
    }

    fn parse_suffixed(&mut self) -> PResult<Expr> {
        let mut expr = self.parse_primary()?;
        loop {
            if self.check_punct(".") {
                self.advance()?;
                let name = self.expect_name()?;
                expr = Expr::Index(Box::new(expr), Box::new(Expr::Str(name)));
            } else if self.check_punct("[") {
                self.advance()?;
                let k = self.parse_expr()?;
                self.expect_punct("]")?;
                expr = Expr::Index(Box::new(expr), Box::new(k));
            } else if self.check_punct(":") {
                self.advance()?;
                let name = self.expect_name()?;
                let args = self.parse_args()?;
                expr = Expr::Method(Box::new(expr), name, args);
            } else if self.check_punct("(")
                || self.check_punct("{")
                || matches!(&self.cur, Tok::Str(_))
            {
                let args = self.parse_args()?;
                expr = Expr::Call(Box::new(expr), args);
            } else {
                break;
            }
        }
        Ok(expr)
    }

    fn parse_args(&mut self) -> PResult<Vec<Expr>> {
        if self.accept_punct("(")? {
            let mut args = Vec::new();
            if !self.check_punct(")") {
                loop {
                    args.push(self.parse_expr()?);
                    if !self.accept_punct(",")? {
                        break;
                    }
                }
            }
            self.expect_punct(")")?;
            Ok(args)
        } else if self.check_punct("{") {
            Ok(vec![self.parse_table()?])
        } else if let Tok::Str(s) = self.cur.clone() {
            self.advance()?;
            Ok(vec![Expr::Str(s)])
        } else {
            Err(self.err(&format!(
                "function arguments expected near {}",
                tok_repr(&self.cur)
            )))
        }
    }
}

fn tok_repr(t: &Tok) -> String {
    match t {
        Tok::Name(n) => format!("'{n}'"),
        Tok::Number(n) => format!("'{n}'"),
        Tok::Str(s) => format!("\"{s}\""),
        Tok::Keyword(k) => format!("'{k}'"),
        Tok::Punct(p) => format!("'{p}'"),
        Tok::Eof => "<eof>".to_string(),
    }
}

pub fn parse_lua_number(text: &str) -> Value {
    let t = text.trim();
    if t.starts_with("0x") || t.starts_with("0X") {
        let hex = &t[2..];
        if let Ok(i) = i64::from_str_radix(hex, 16) {
            return Value::Integer(i);
        }
        if let Ok(f) = f64::from_str_radix(hex, 16) {
            return Value::Float(f);
        }
        return Value::Integer(0);
    }
    if !t.contains('.') && !t.to_lowercase().contains('e') && !t.ends_with("ull") {
        if let Ok(i) = t.parse::<i64>() {
            return Value::Integer(i);
        }
    }
    if t.ends_with("ull") {
        if let Ok(i) = t.trim_end_matches("ull").parse::<u64>() {
            return Value::Integer(i as i64);
        }
    }
    match t.parse::<f64>() {
        Ok(f) => Value::Float(f),
        Err(_) => Value::Integer(0),
    }
}
