{"command": "cd /workspace && cat >> src/lua.rs <<'RSEOF'

// ---------------------------------------------------------------- runtime

#[derive(Debug)]
enum Frame {
    Main,
    Desc(String),
    C(String),
}

pub struct Interp {
    pub globals: Rc<RefCell<Table>>,
    pub chunk: String,
    frames: Vec<Frame>,
    varargs: Vec<Value>,
    depth: usize,
}

pub struct LuaErr {
    pub message: String,
}

enum Flow {
    Normal,
    Break,
    Return(Vec<Value>),
}

impl Interp {
    pub fn new(chunk: &str) -> Self {
        let globals = Rc::new(RefCell::new(Table::new()));
        let mut interp = Interp {
            globals,
            chunk: chunk.to_string(),
            frames: vec![Frame::Main],
            varargs: Vec::new(),
            depth: 0,
        };
        interp.install_stdlib();
        interp
    }

    fn env_globals(&self) -> Rc<RefCell<Table>> {
        self.globals.clone()
    }

    fn new_scope(&self, parent: Option<Rc<Scope>>) -> Rc<Scope> {
        Rc::new(Scope::new(parent, self.globals.clone()))
    }

    fn push_frame(&mut self, f: Frame) {
        self.frames.push(f);
    }

    fn pop_frame(&mut self) {
        self.frames.pop();
    }

    fn error(&self, message: &str) -> String {
        let mut frames: Vec<String> = Vec::new();
        for f in self.frames.iter().rev() {
            let s = match f {
                Frame::Main => format!("{}: in main chunk", self.chunk),
                Frame::Desc(d) => format!("{}: in {d}", self.chunk),
                Frame::C(c) => format!("[C]: {c}"),
            };
            frames.push(s);
        }
        let mut out = format!("{}: {message}", self.chunk);
        out.push_str("\nstack traceback:");
        for f in frames {
            out.push_str("\n\t");
            out.push_str(&f);
        }
        out
    }

    pub fn run(&mut self, body: &[Stmt]) -> Result<Vec<Value>, String> {
        let env = self.new_scope(None);
        match self.exec_block(body, &env) {
            Ok(Flow::Return(v)) => Ok(v),
            Ok(_) => Ok(vec![]),
            Err(e) => Err(e),
        }
    }

    // ---- statements

    fn exec_block(&mut self, stmts: &[Stmt], env: &Rc<Scope>) -> Result<Flow, String> {
        for s in stmts {
            match self.exec_stmt(s, env)? {
                Flow::Normal => {}
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_stmt(&mut self, stmt: &Stmt, env: &Rc<Scope>) -> Result<Flow, String> {
        match stmt {
            Stmt::Local(names, exprs) => {
                let values = self.eval_list(exprs, env, names.len())?;
                for (i, name) in names.iter().enumerate() {
                    let v = values.get(i).cloned().unwrap_or(Value::Nil);
                    env.define(name, v);
                }
                Ok(Flow::Normal)
            }
            Stmt::LocalFunc(name, f) => {
                let func = self.make_closure(f, env, None);
                env.define(name, Value::Function(func));
                Ok(Flow::Normal)
            }
            Stmt::Assign(targets, exprs) => {
                let values = self.eval_list(exprs, env, targets.len())?;
                for (i, t) in targets.iter().enumerate() {
                    let v = values.get(i).cloned().unwrap_or(Value::Nil);
                    self.assign(t, v, env)?;
                }
                Ok(Flow::Normal)
            }
            Stmt::ExprStmt(e) => {
                self.eval_multi(e, env)?;
                Ok(Flow::Normal)
            }
            Stmt::If(arms, els) => {
                for (cond, body) in arms {
                    if truthy(&self.eval(cond, env)?) {
                        return self.exec_block(body, env);
                    }
                }
                self.exec_block(els, env)
            }
            Stmt::While(cond, body) => {
                while truthy(&self.eval(cond, env)?) {
                    match self.exec_block(body, env)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Repeat(body, cond) => loop {
                match self.exec_block(body, env)? {
                    Flow::Normal => {}
                    Flow::Break => break,
                    Flow::Return(v) => return Ok(Flow::Return(v)),
                }
                if truthy(&self.eval(cond, env)?) {
                    break;
                }
            },
            Stmt::NumFor(name, start, limit, step, body) => {
                let s = self.eval(start, env)?;
                let l = self.eval(limit, env)?;
                let st = match step {
                    Some(e) => self.eval(e, env)?,
                    None => Value::Integer(1),
                };
                let sf = to_float(&s).ok_or_else(|| {
                    self.error("'for' initial value must be a number")
                })?;
                let lf = to_float(&l)
                    .ok_or_else(|| self.error("'for' limit must be a number"))?;
                let stf = to_float(&st).ok_or_else(|| {
                    self.error("'for' step must be a number")
                })?;
                if stf == 0.0 {
                    return Err(self.error("'for' step is zero"));
                }
                let is_int = matches!(s, Value::Integer(_))
                    && matches!(l, Value::Integer(_))
                    && matches!(st, Value::Integer(_));
                if is_int {
                    let (mut i, l, st) = (s, l, st);
                    let i0 = as_int(&i).unwrap();
                    let i1 = as_int(&l).unwrap();
                    let ist = as_int(&st).unwrap();
                    let mut v = i0;
                    while (ist > 0 && v <= i1) || (ist < 0 && v >= i1) {
                        let child = self.new_scope(Some(env.clone()));
                        child.define(name, Value::Integer(v));
                        match self.exec_block(body, &child)? {
                            Flow::Normal => {}
                            Flow::Break => break,
                            Flow::Return(r) => return Ok(Flow::Return(r)),
                        }
                        v = v.wrapping_add(ist);
                        let _ = (&mut i, &mut l, &mut st);
                    }
                } else {
                    let mut v = sf;
                    loop {
                        if stf > 0.0 && v > lf {
                            break;
                        }
                        if stf < 0.0 && v < lf {
                            break;
                        }
                        let child = self.new_scope(Some(env.clone()));
                        child.define(name, Value::Float(v));
                        match self.exec_block(body, &child)? {
                            Flow::Normal => {}
                            Flow::Break => break,
                            Flow::Return(r) => return Ok(Flow::Return(r)),
                        }
                        v += stf;
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::GenFor(names, exprs, body) => {
                let values = self.eval_list(exprs, env, 3)?;
                let f = values.first().cloned().unwrap_or(Value::Nil);
                let state = values.get(1).cloned().unwrap_or(Value::Nil);
                let control = values.get(2).cloned().unwrap_or(Value::Nil);
                let mut ctrl = control;
                loop {
                    let results = match &f {
                        Value::Function(_) | Value::Native(_) => {
                            self.call_value(f.clone(), vec![state.clone(), ctrl.clone()], "main chunk")?
                        }
                        _ => {
                            return Err(self
                                .error("attempt to call a non function object"))
                        }
                    };
                    let first = results.first().cloned().unwrap_or(Value::Nil);
                    if matches!(first, Value::Nil) {
                        break;
                    }
                    let child = self.new_scope(Some(env.clone()));
                    for (i, n) in names.iter().enumerate() {
                        child.define(n, results.get(i).cloned().unwrap_or(Value::Nil));
                    }
                    match self.exec_block(body, &child)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        Flow::Return(r) => return Ok(Flow::Return(r)),
                    }
                    ctrl = first.clone();
                }
                Ok(Flow::Normal)
            }
            Stmt::GlobalFunc(names, f) => {
                let func = self.make_closure(f, env, names.last().cloned());
                if names.len() == 1 {
                    self.globals
                        .borrow_mut()
                        .set(Value::Str(Rc::new(names[0].clone())), Value::Function(func));
                } else {
                    let mut cur = Value::Table(Rc::new(RefCell::new(Table::new())));
                    if let Some(v) = self
                        .globals
                        .borrow()
                        .get(&Value::Str(Rc::new(names[0].clone())))
                    {
                        cur = v;
                    }
                    for name in &names[1..names.len() - 1] {
                        let key = Value::Str(Rc::new(name.clone()));
                        let next = match &cur {
                            Value::Table(t) => t.borrow().get(&key),
                            _ => Value::Nil,
                        };
                        cur = match next {
                            Value::Table(_) => next,
                            _ => Value::Table(Rc::new(RefCell::new(Table::new()))),
                        };
                        if let Value::Table(t) = &cur {
                            let outer = cur.clone();
                            t.borrow_mut().set(key, outer.clone());
                        }
                        break;
                    }
                    if let Value::Table(t) = &cur {
                        t.borrow_mut().set(
                            Value::Str(Rc::new(names[names.len() - 1].clone())),
                            Value::Function(func),
                        );
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Return(exprs) => {
                let values = self.eval_list(exprs, env, usize::MAX)?;
                Ok(Flow::Return(values))
            }
            Stmt::Break => Ok(Flow::Break),
            Stmt::Do(body) => self.exec_block(body, env),
        }
    }

    fn make_closure(
        &mut self,
        f: &Rc<FuncAst>,
        env: &Rc<Scope>,
        name: Option<String>,
    ) -> Rc<LuaFunction> {
        Rc::new(LuaFunction {
            params: f.params.clone(),
            is_vararg: f.is_vararg,
            body: f.body.clone(),
            env: env.clone(),
            name,
            chunk: self.chunk.clone(),
        })
    }

    fn assign(&mut self, target: &Expr, value: Value, env: &Rc<Scope>) -> Result<(), String> {
        match target {
            Expr::Name(n) => {
                if !env.set(n, value.clone()) {
                    self.globals
                        .borrow_mut()
                        .set(Value::Str(Rc::new(n.clone())), value);
                }
                Ok(())
            }
            Expr::Index(obj, key) => {
                let o = self.eval(obj, env)?;
                let k = self.eval(key, env)?;
                match &o {
                    Value::Table(t) => {
                        t.borrow_mut().set(k, value);
                        Ok(())
                    }
                    Value::Nil => Err(self.index_error(&o, &describe_expr(obj))),
                    _ => Err(self.index_error(&o, &describe_expr(obj))),
                }
            }
            _ => Err(self.error("cannot assign to this expression")),
        }
    }

    fn index_error(&self, value: &Value, desc: &str) -> String {
        let tn = type_name(value);
        let mut msg = format!("attempt to index a {tn} value");
        if !desc.is_empty() {
            msg.push_str(&format!(" ({desc})"));
        }
        let mut frames: Vec<String> = vec!["[C]: in metamethod 'index'".to_string()];
        for f in self.frames.iter().rev() {
            let s = match f {
                Frame::Main => format!("{}: in main chunk", self.chunk),
                Frame::Desc(d) => format!("{}: in {d}", self.chunk),
                Frame::C(c) => format!("[C]: {c}"),
            };
            frames.push(s);
        }
        let mut out = format!("{}: {msg}", self.chunk);
        out.push_str("\nstack traceback:");
        for f in frames {
            out.push_str("\n\t");
            out.push_str(&f);
        }
        out
    }
}

fn describe_expr(e: &Expr) -> String {
    match e {
        Expr::Name(n) => format!("global '{n}'"),
        Expr::Index(o, k) => match &**k {
            Expr::Str(s) => format!("field '{s}'"),
            _ => format!("field '?'"),
        },
        _ => String::new(),
    }
}

pub fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Nil => "nil",
        Value::Boolean(_) => "boolean",
        Value::Integer(_) | Value::Float(_) => "number",
        Value::Str(_) => "string",
        Value::Table(_) => "table",
        Value::Function(_) | Value::Native(_) => "function",
    }
}

pub fn truthy(v: &Value) -> bool {
    !matches!(v, Value::Nil | Value::Boolean(false))
}

pub fn as_int(v: &Value) -> Option<i64> {
    match v {
        Value::Integer(i) => Some(*i),
        Value::Float(f) if f.fract() == 0.0 => Some(*f as i64),
        _ => None,
    }
}

pub fn to_float(v: &Value) -> Option<f64> {
    match v {
        Value::Integer(i) => Some(*i as f64),
        Value::Float(f) => Some(*f),
        Value::Str(s) => s.parse::<f64>().ok(),
        _ => None,
    }
}
