                        if stf > 0.0 && v > lf {
                            break;
                        }
                        if stf < 0.0 && v < lf {
                            break;
                        }
                        let child = self.new_scope(Some(env.clone()));
                        child.define(name, Value::Float(v));
                        match self.exec_block(body, &child)? {
                            Flow::Normal => {}
                            Flow::Break => break,
                            Flow::Return(r) => return Ok(Flow::Return(r)),
                        }
