    fn make_closure(
        &mut self,
        f: &Rc<FuncAst>,
        env: &Rc<Scope>,
        name: Option<String>,
    ) -> Rc<LuaFunction> {
        Rc::new(LuaFunction {
            params: f.params.clone(),
            is_vararg: f.is_vararg,
            body: f.body.clone(),
            env: env.clone(),
            name,
            chunk: self.chunk.clone(),
