fn describe_expr(e: &Expr) -> String {
    match e {
        Expr::Name(n) => format!("global '{n}'"),
        Expr::Index(o, k) => match &**k {
            Expr::Str(s) => format!("field '{s}'"),
            _ => format!("field '?'"),
        },
