// ---- evaluation

impl Interp {
    fn eval_list(
        &mut self,
        exprs: &[Expr],
        env: &Rc<Scope>,
        want: usize,
    ) -> Result<Vec<Value>, String> {
        let mut out: Vec<Value> = Vec::new();
        for (i, e) in exprs.iter().enumerate() {
            if i + 1 == exprs.len() {
                let vals = self.eval_multi(e, env)?;
                out.extend(vals);
            } else {
                out.push(self.eval(e, env)?);
            }
        }
        if want != usize::MAX && out.len() < want {
            while out.len() < want {
                out.push(Value::Nil);
            }
        }
        Ok(out)
    }

    fn eval_multi(&mut self, e: &Expr, env: &Rc<Scope>) -> Result<Vec<Value>, String> {
        match e {
            Expr::Vararg => Ok(self.varargs.clone()),
            Expr::Call(f, args) => {
                let fv = self.eval(f, env)?;
                let argv = self.eval_list(args, env, usize::MAX)?;
                self.call_value(fv, argv, &describe_expr(f))
            }
            Expr::Method(o, name, args) => {
                let ov = self.eval(o, env)?;
                let fv = match &ov {
                    Value::Table(t) => {
                        let v = t.borrow().get(&Value::Str(Rc::new(name.clone())));
                        v
                    }
                    Value::Nil => Value::Nil,
                    _ => return Err(self.index_error(&ov, &format!("method '{name}'"))),
                };
                if matches!(fv, Value::Nil) {
                    return Err(self.call_error(&Value::Nil, &format!("method '{name}'")));
                }
                let mut argv = vec![ov.clone()];
                argv.extend(self.eval_list(args, env, usize::MAX)?);
                self.call_value(fv, argv, &format!("method '{name}'"))
            }
            Expr::Table(fields) => {
                let table = Value::Table(Rc::new(RefCell::new(Table::new())));
                let mut idx = 1i64;
                let n = fields.len();
                for (i, f) in fields.iter().enumerate() {
                    match f {
                        TField::Item(e) => {
                            if i + 1 == n {
                                let vals = self.eval_multi(e, env)?;
                                for v in vals {
                                    if let Value::Table(t) = &table {
                                        t.borrow_mut()
                                            .set(Value::Integer(idx), v.clone());
                                    }
                                    idx += 1;
                                }
                            } else {
                                let v = self.eval(e, env)?;
                                if let Value::Table(t) = &table {
                                    t.borrow_mut().set(Value::Integer(idx), v);
                                }
                                idx += 1;
                            }
                        }
                        TField::Named(k, e) => {
                            let v = self.eval(e, env)?;
                            if let Value::Table(t) = &table {
                                t.borrow_mut().set(Value::Str(Rc::new(k.clone())), v);
                            }
                        }
                        TField::Keyed(k, e) => {
                            let kv = self.eval(k, env)?;
                            let v = self.eval(e, env)?;
                            if let Value::Table(t) = &table {
                                t.borrow_mut().set(kv, v);
                            }
                        }
                    }
                }
                Ok(vec![table])
            }
            _ => Ok(vec![self.eval(e, env)?]),
        }
    }

    fn eval(&mut self, e: &Expr, env: &Rc<Scope>) -> Result<Value, String> {
        match e {
            Expr::Nil => Ok(Value::Nil),
            Expr::True => Ok(Value::Boolean(true)),
            Expr::False => Ok(Value::Boolean(false)),
            Expr::Num(n) => Ok(n.clone()),
            Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
            Expr::Vararg => Ok(self.varargs.first().cloned().unwrap_or(Value::Nil)),
            Expr::Name(n) => Ok(match env.lookup(n) {
                Some(v) => v.borrow().clone(),
                None => self
                    .globals
                    .borrow()
                    .get(&Value::Str(Rc::new(n.clone()))),
            }),
            Expr::Index(obj, key) => {
                let o = self.eval(obj, env)?;
                let k = self.eval(key, env)?;
                self.index_value(&o, &k, &describe_expr(obj))
            }
            Expr::Call(_, _) | Expr::Method(_, _, _) | Expr::Table(_) => {
                Ok(self.eval_multi(e, env)?.first().cloned().unwrap_or(Value::Nil))
            }
            Expr::Func(f) => Ok(Value::Function(self.make_closure(f, env, None))),
            Expr::Bin(op, a, b) => self.eval_bin(*op, a, b, env),
            Expr::Un(op, a) => {
                let v = self.eval(a, env)?;
                match op {
                    b'n' => Ok(Value::Boolean(!truthy(&v))),
                    b'#' => match &v {
                        Value::Str(s) => Ok(Value::Integer(s.chars().count() as i64)),
                        Value::Table(t) => Ok(Value::Integer(t.borrow().length())),
                        _ => Err(self.unop_error(&v, "#")),
                    },
                    b'-' => match &v {
                        Value::Integer(i) => Ok(Value::Integer(i.wrapping_neg())),
                        Value::Float(f) => Ok(Value::Float(-f)),
                        Value::Str(s) => match s.parse::<i64>() {
                            Ok(i) => Ok(Value::Integer(i.wrapping_neg())),
                            Err(_) => match s.trim().parse::<f64>() {
                                Ok(f) => Ok(Value::Float(-f)),
                                Err(_) => Err(self.unop_error(&v, "-")),
                            },
                        },
                        _ => Err(self.unop_error(&v, "-")),
                    },
                    b'~' => match as_int(&v) {
                        Some(i) => Ok(Value::Integer(!i)),
                        _ => Err(self.unop_error(&v, "~")),
                    },
                    _ => Ok(Value::Nil),
                }
            }
        }
    }

    fn index_value(&mut self, o: &Value, k: &Value, desc: &str) -> Result<Value, String> {
        match o {
            Value::Table(t) => Ok(t.borrow().get(k)),
            Value::Nil => Err(self.index_error(o, desc)),
            _ => Err(self.index_error(o, desc)),
        }
    }

    fn eval_bin(
        &mut self,
        op: u8,
        a: &Expr,
        b: &Expr,
        env: &Rc<Scope>,
    ) -> Result<Value, String> {
        let av = self.eval(a, env)?;
        let bv = self.eval(b, env)?;
        match op {
            b'o' => {
                if truthy(&av) {
                    Ok(av)
                } else {
                    Ok(bv)
                }
            }
            b'a' => {
                if truthy(&av) {
                    Ok(bv)
                } else {
                    Ok(av)
                }
            }
            b'+' | b'-' | b'*' | b'/' | b'%' | b'^' => {
                self.arith(op, &av, &bv, &describe_expr(a), &describe_expr(b))
            }
            b'.' => {
                // concat
                let sa = self.tostring(&av).map_err(|e| e)?;
                let _ = &sa;
                if !can_concat(&av) {
                    return Err(self.concat_error(&av, &describe_expr(a)));
                }
                if !can_concat(&bv) {
                    return Err(self.concat_error(&bv, &describe_expr(b)));
                }
                let s1 = num_or_str(&av);
                let s2 = num_or_str(&bv);
                Ok(Value::Str(Rc::new(format!("{s1}{s2}"))))
            }
            b'<' | b'>' | b'l' | b'e' => self.compare(op, &av, &bv),
            b'=' => Ok(Value::Boolean(values_equal(&av, &bv))),
            b'~' => Ok(Value::Boolean(!values_equal(&av, &bv))),
            _ => Ok(Value::Nil),
        }
    }

    fn arith(
        &mut self,
        op: u8,
        a: &Value,
        b: &Value,
        adesc: &str,
        bdesc: &str,
    ) -> Result<Value, String> {
        let op_name = match op {
            b'+' => "add",
            b'-' => "sub",
            b'*' => "mul",
            b'/' => "div",
            b'%' => "mod",
            _ => "pow",
        };
        let na = number_of(a);
        let nb = number_of(b);
        let (na, nb) = match (na, nb) {
            (Some(x), Some(y)) => (x, y),
            _ => {
                // error path
                let (bad, desc, tn) = if !is_arith_candidate(a) {
                    (a, adesc, type_name(a))
                } else if !is_arith_candidate(b) {
                    (b, bdesc, type_name(b))
                } else {
                    // both candidates but at least one string is not numeric
                    let (x, y) = (type_name(a), type_name(b));
                    let mut frames: Vec<String> = vec!["[C]: in ?".to_string()];
                    frames.push(format!("[C]: in metamethod '{op_name}'"));
                    return Err(self.error_with(&frames, &format!("attempt to {op_name} a '{x}' with a '{y}'")));
                };
                if let Some(d) = desc_suffix(bad, desc) {
                    let _ = d;
                }
                let mut frames: Vec<String> =
                    vec![format!("[C]: in metamethod '{op_name}'")];
                self.frames_error(&frames, &format!("attempt to perform arithmetic on a {tn} value{desc_suffix(bad, desc)}"))
            }
        };
        match op {
            b'+' => Ok(match (na, nb) {
                (NumKind::Int(x), NumKind::Int(y)) => Value::Integer(x.wrapping_add(y)),
                _ => Value::Float(xf(&na) + xf(&nb)),
            }),
            b'-' => Ok(match (na, nb) {
                (NumKind::Int(x), NumKind::Int(y)) => Value::Integer(x.wrapping_sub(y)),
                _ => Value::Float(xf(&na) - xf(&nb)),
            }),
            b'*' => Ok(match (na, nb) {
                (NumKind::Int(x), NumKind::Int(y)) => Value::Integer(x.wrapping_mul(y)),
                _ => Value::Float(xf(&na) * xf(&nb)),
            }),
            b'/' => Ok(Value::Float(xf(&na) / xf(&nb))),
            b'%' => match (na, nb) {
                (NumKind::Int(x), NumKind::Int(y)) => {
                    if y == 0 {
                        Err(self.error_with(
                            &["[C]: in ?".to_string()],
                            "attempt to perform 'n%%0'",
                        ))
                    } else {
                        Ok(Value::Integer(x - y * ((x as f64 / y as f64).floor() as i64)))
                    }
                }
                _ => {
                    let x = xf(&na);
                    let y = xf(&nb);
                    if y == 0.0 {
                        Ok(Value::Float(f64::NAN))
                    } else {
                        Ok(Value::Float(x - y * (x / y).floor()))
                    }
                }
            },
            _ => Ok(Value::Float(xf(&na).powf(xf(&nb)))),
        }
    }

    fn compare(&mut self, op: u8, a: &Value, b: &Value) -> Result<Value, String> {
        // For > and >= we swap the operands first (like lua does).
        let (op, a, b) = match op {
            b'>' => (b'<', b, a),
            b'l' => (b'e', b, a),
            other => (other, a, b),
        };
        let meta = match op {
            b'<' => "lt",
            _ => "le",
        };
        let ok_pair = |x: &Value, y: &Value| match (x, y) {
            (Value::Integer(_) | Value::Float(_), Value::Integer(_) | Value::Float(_)) => true,
            (Value::Str(_), Value::Str(_)) => true,
            _ => false,
        };
        if !ok_pair(a, b) {
            let msg = match (type_name(a), type_name(b)) {
                ("nil", "nil") => "attempt to compare two nil values".to_string(),
                (x, y) if x == y => format!("attempt to compare two {x} values"),
                (x, y) => format!("attempt to compare {x} with {y}"),
            };
            return Err(self.error_with(
                &[format!("[C]: in metamethod '{meta}'")],
                &msg,
            ));
        }
        let r = match (a, b) {
            (Value::Str(x), Value::Str(y)) => match op {
                b'<' => x < y,
                _ => x <= y,
            },
            _ => {
                let x = xf(&number_of(a).unwrap());
                let y = xf(&number_of(b).unwrap());
                match op {
                    b'<' => x < y,
                    _ => x <= y,
                }
            }
        };
        Ok(Value::Boolean(r))
    }

    fn unop_error(&self, v: &Value, op: &str) -> String {
        let meta = match op {
            "-" => "unm",
            "#" => "len",
            _ => "bnot",
        };
        let mut desc = "";
        let tn = type_name(v);
        let msg = match op {
            "-" => format!("attempt to perform arithmetic on a {tn} value"),
            "#" => format!("attempt to get length of a {tn} value"),
            _ => format!("attempt to perform bitwise operation on a {tn} value"),
        };
        let _ = &mut desc;
        self.error_with(&[format!("[C]: in metamethod '{meta}'")], &msg)
    }

    fn concat_error(&self, v: &Value, desc: &str) -> String {
        let tn = type_name(v);
        self.error_with(
            &["[C]: in metamethod 'concat'".to_string()],
            &format!("attempt to concatenate a {tn} value{desc_suffix(v, desc)}"),
        )
    }

    fn call_error(&self, v: &Value, desc: &str) -> String {
        let tn = type_name(v);
        let msg = if tn == "nil" {
            format!("attempt to call a nil value{desc_suffix(v, desc)}")
        } else {
            format!("attempt to call a {tn} value")
        };
        if tn == "nil" {
            self.error_with(&[format!("[C]: in {desc}")], &msg)
        } else {
            self.error_with(&["[C]: in ?".to_string()], &msg)
        }
    }

    fn frames_error(&self, extra: &[String], message: &str) -> String {
        let mut frames: Vec<String> = extra.to_vec();
        for f in self.frames.iter().rev() {
            let s = match f {
                Frame::Main => format!("{}: in main chunk", self.chunk),
                Frame::Desc(d) => format!("{}: in {d}", self.chunk),
                Frame::C(c) => format!("[C]: {c}"),
            };
            frames.push(s);
        }
        let mut out = format!("{}: {message}", self.chunk);
        out.push_str("\nstack traceback:");
        for f in frames {
            out.push_str("\n\t");
            out.push_str(&f);
        }
        out
    }

    fn error(&self, message: &str) -> String {
        self.frames_error(&[], message)
    }

    fn error_with(&self, extra: &[String], message: &str) -> String {
        self.frames_error(extra, message)
    }

    fn tostring(&mut self, v: &Value) -> Result<String, String> {
        Ok(lua_tostring(v))
    }

    fn call_value(
        &mut self,
        f: Value,
        args: Vec<Value>,
        desc: &str,
    ) -> Result<Vec<Value>, String> {
        if self.depth > 190 {
            return Err(self.error_with(
                &["[C]: in ?".to_string()],
                "stack overflow",
            ));
        }
        match &f {
            Value::Function(func) => {
                let saved_varargs = std::mem::replace(&mut self.varargs, Vec::new());
                let env = self.new_scope(Some(func.env.clone()));
                for (i, p) in func.params.iter().enumerate() {
                    let v = args.get(i).cloned().unwrap_or(Value::Nil);
                    env.define(p, v);
                }
                if func.is_vararg {
                    self.varargs = args
                        .iter()
                        .skip(func.params.len())
                        .cloned()
                        .collect();
                }
                self.push_frame(Frame::Desc(desc.to_string()));
                self.depth += 1;
                let res = self.exec_block(&func.body, &env);
                self.depth -= 1;
                self.pop_frame();
                self.varargs = saved_varargs;
                match res {
                    Ok(Flow::Return(v)) => Ok(v),
                    Ok(_) => Ok(vec![]),
                    Err(e) => Err(e),
                }
            }
            Value::Native(n) => {
                let name = n.1.clone();
                self.push_frame(Frame::C(format!("in function '{name}'")));
                self.push_frame(Frame::C("in ?".to_string()));
                self.depth += 1;
                let res = (n.0)(self, args);
                self.depth -= 1;
                self.pop_frame();
                self.pop_frame();
                res
            }
            Value::Nil => Err(self.call_error(&f, desc)),
            _ => Err(self.call_error(&f, desc)),
        }
    }
}

pub struct NamedNative(pub NativeFn, pub &'static str);

fn desc_suffix(v: &Value, desc: &str) -> String {
    if desc.is_empty() {
        return String::new();
    }
    match v {
        Value::Nil => format!(" ({desc})"),
        Value::Boolean(_) | Value::Table(_) => String::new(),
        Value::Function(_) | Value::Native(_) => format!(" ({desc})"),
        Value::Str(_) | Value::Integer(_) | Value::Float(_) => String::new(),
    }
}

fn is_arith_candidate(v: &Value) -> bool {
    matches!(v, Value::Integer(_) | Value::Float(_) | Value::Str(_))
}

enum NumKind {
    Int(i64),
    Float(f64),
}

fn number_of(v: &Value) -> Option<NumKind> {
    match v {
        Value::Integer(i) => Some(NumKind::Int(*i)),
        Value::Float(f) => Some(NumKind::Float(*f)),
        Value::Str(s) => {
            if let Ok(i) = s.parse::<i64>() {
                Some(NumKind::Int(i))
            } else if let Ok(f) = s.parse::<f64>() {
                Some(NumKind::Float(f))
            } else if s.starts_with("0x") || s.starts_with("0X") {
                i64::from_str_radix(&s[2..], 16).ok().map(NumKind::Int)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn xf(n: &NumKind) -> f64 {
    match n {
        NumKind::Int(i) => *i as f64,
        NumKind::Float(f) => *f,
    }
}

fn can_concat(v: &Value) -> bool {
    matches!(v, Value::Str(_) | Value::Integer(_) | Value::Float(_))
}

fn num_or_str(v: &Value) -> String {
    match v {
        Value::Str(s) => s.to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Float(f) => format_lua_float(*f),
        _ => String::new(),
    }
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Nil, Value::Nil) => true,
        (Value::Boolean(x), Value::Boolean(y)) => x == y,
        (Value::Integer(x), Value::Integer(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Integer(x), Value::Float(y)) => *x as f64 == *y,
        (Value::Float(x), Value::Integer(y)) => *x == *y as f64,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Table(x), Value::Table(y)) => Rc::ptr_eq(x, y),
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        (Value::Native(x), Value::Native(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

pub fn lua_tostring(v: &Value) -> String {
    match v {
        Value::Nil => "nil".to_string(),
        Value::Boolean(b) => b.to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Float(f) => format_lua_float(*f),
        Value::Str(s) => s.to_string(),
        Value::Table(t) => format!("table: {:p}", Rc::as_ptr(t)),
        Value::Function(f) => format!("function: built-in, {:p}", Rc::as_ptr(f)),
        Value::Native(n) => format!("function: built-in, {:p}", Rc::as_ptr(n)),
    }
}

pub fn format_lua_float(f: f64) -> String {
    if f.is_nan() {
        if f.is_sign_negative() {
            return "-nan".to_string();
        }
        return "nan".to_string();
    }
    if f.is_infinite() {
        return if f > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    let s = format!("{f:.14e}");
    // Rust's {:e} gives e.g. 2e0 -> convert to %g style
    let s = match format_g14(f) {
        Some(s) => s,
        None => s,
    };
    if !s.contains('.') && !s.contains('e') && !s.contains('E') && !s.contains("inf") && !s.contains("nan") {
        format!("{s}.0")
    } else {
        s
    }
}

fn format_g14(f: f64) -> Option<String> {
    let s = format!("{:e}", f);
    // printf %g uses e+XX notation; normalize exponent
    let (mant, exp) = s.split_once('e')?;
    let exp_val: i32 = exp.parse().ok()?;
    let mant: f64 = mant.parse().ok()?;
    let out = if exp_val < -4 || exp_val >= 14 {
        // use scientific notation with 14 significant digits
        let digits = format!("{:.13e}", f);
        let (m, e) = digits.split_once('e')?;
        let e: i32 = e.parse().ok()?;
        let sign = if e < 0 { "-" } else { "+" };
        let e_abs = e.abs();
        format!("{m}e{}{:02}", sign, e_abs)
    } else {
        let precision = (14 - 1 - exp_val).max(0) as usize;
        format!("{:.*}", precision, f)
    };
    // strip trailing zeros in the mantissa for the fixed notation
    if out.contains('.') && !out.contains('e') {
        let trimmed = out.trim_end_matches('0').trim_end_matches('.');
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
    }
    Some(out)
}
