/// Parses a hexadecimal float literal (used for lua number literals).
pub fn hex_to_float(hex: &str) -> Option<f64> {
    let (mantissa, exponent) = match hex.find(['p', 'P']) {
        Some(i) => (&hex[..i], hex[i + 1..].parse::<i32>().unwrap_or(0)),
        None => (hex, 0),
    };
    let (int_part, frac_part) = match mantissa.find('.') {
        Some(i) => (&mantissa[..i], &mantissa[i + 1..]),
        None => (mantissa, ""),
    };
    if int_part.is_empty() && frac_part.is_empty() {
        return None;
    }
    let mut value = 0f64;
    for c in int_part.chars() {
        let d = c.to_digit(16)? as f64;
        value = value * 16.0 + d;
    }
    let mut scale = 1.0 / 16.0;
    for c in frac_part.chars() {
        let d = c.to_digit(16)? as f64;
        value += d * scale;
        scale /= 16.0;
    }
    Some(value * 2f64.powi(exponent))
}
