// ---------------------------------------------------------------- json -> lua

/// Converts a json key to a lua identifier.
pub fn sanitize_key(key: &str) -> String {
    let mut out = String::new();
    for c in key.chars() {
        if c.is_ascii_alphanumeric() || c == '_' {
            out.push(c);
        } else {
            out.push('_');
        }
    }
    if let Some(first) = out.chars().next() {
        if first.is_ascii_digit() {
            out.insert(0, '_');
        }
    }
    out
}

/// Renders a json value as a lua literal (used by --print-lua).
pub fn lua_literal(v: &Value) -> String {
    match v {
        Value::Null => "\"unsupported\"".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => crate::lua_escape(s),
        Value::Array(items) => {
            let parts: Vec<String> = items
                .iter()
                .map(|i| match i {
                    Value::Object(_) | Value::Array(_) => "\"unsupported\"".to_string(),
                    other => lua_literal(other),
                })
                .collect();
            format!("{{{}}}", parts.join(","))
        }
        Value::Object(map) => {
            let parts: Vec<String> = map
                .iter()
                .map(|(k, v)| format!("{} = {}", sanitize_key(k), lua_literal(v)))
                .collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

pub fn lua_escape(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            '\0' => out.push_str("\\0"),
            other => out.push(other),
        }
    }
    out.push('"');
    out
}

pub fn json_to_lua(v: &Value, in_array: bool) -> Value {
    match v {
        Value::Null => Value::Str(Rc::new("unsupported".to_string())),
        Value::Bool(b) => Value::Boolean(*b),
        Value::Number(n) => match n.as_i64() {
            Some(i) => Value::Integer(i),
            None => Value::Float(n.as_f64().unwrap_or(0.0)),
        },
        Value::String(s) => Value::Str(Rc::new(s.clone())),
        Value::Object(_) | Value::Array(_) => {
            if in_array {
                Value::Str(Rc::new("unsupported".to_string()))
            } else {
                let table = Rc::new(RefCell::new(Table::new()));
                match v {
                    Value::Object(map) => {
                        for (k, val) in map.iter() {
                            table.borrow_mut().set(
                                Value::Str(Rc::new(k.clone())),
                                json_to_lua(val, false),
                            );
                        }
                    }
                    Value::Array(items) => {
                        for (i, val) in items.iter().enumerate() {
                            table.borrow_mut().set(
                                Value::Integer(i as i64 + 1),
                                json_to_lua(val, true),
                            );
                        }
                    }
                    _ => {}
                }
                Value::Table(table)
            }
        }
    }
}

/// Runs a lua chunk with the given globals.
pub fn run(code: &str, chunk: &str, entry: &Value) -> Result<Value, String> {
    let mut interp = Interp::new(chunk);
    {
        let globals = interp.globals.clone();
        if let Value::Object(map) = entry {
            for (k, v) in map.iter() {
                globals
                    .borrow_mut()
                    .set(Value::Str(Rc::new(k.clone())), json_to_lua(v, false));
            }
        }
    }
    let mut parser = P::new(code);
    let body = match parser.parse_chunk() {
        Ok(b) => b,
        Err(e) => {
            return Err(format!(
                "SyntaxError {{ message: \"{chunk}: {e}\", incomplete_input: false }}"
            ))
        }
    };
    match interp.run(&body) {
        Ok(values) => Ok(values.first().cloned().unwrap_or(Value::Nil)),
        Err(e) => Err(format!("RuntimeError({e:?})")),
    }
}
