impl Interp {
    fn set_global_path(&mut self, names: &[String], value: Value) {
        if names.len() == 1 {
            self.globals
                .borrow_mut()
                .set(Value::Str(Rc::new(names[0].clone())), value);
            return;
        }
        let root_key = Value::Str(Rc::new(names[0].clone()));
        let mut cur = match self.globals.borrow().get(&root_key) {
            Value::Table(t) => Value::Table(t.clone()),
            _ => Value::Table(Rc::new(RefCell::new(Table::new()))),
        };
        self.globals.borrow_mut().set(root_key, cur.clone());
        for name in &names[1..names.len() - 1] {
            let key = Value::Str(Rc::new(name.clone()));
            let next = match &cur {
                Value::Table(t) => t.borrow().get(&key),
                _ => Value::Nil,
            };
            let next = match next {
                Value::Table(t) => Value::Table(t),
                _ => Value::Table(Rc::new(RefCell::new(Table::new()))),
            };
            if let Value::Table(t) = &cur {
                t.borrow_mut().set(key, next.clone());
            }
            cur = next;
        }
        if let Value::Table(t) = &cur {
            t.borrow_mut().set(
                Value::Str(Rc::new(names[names.len() - 1].clone())),
                value,
            );
        }
    }
}
