fn lua_print(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let parts: Vec<String> = args.iter().map(lua_tostring).collect();
    println!("{}", parts.join("\t"));
    let _ = interp;
    Ok(vec![])
}

fn lua_tostring_fn(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        Some(v) => Ok(vec![Value::Str(Rc::new(lua_tostring(v)))]),
        None => Err(interp.error_with(
            &["[C]: in ?".to_string()],
            "bad argument #1 to 'tostring' (value expected)",
        )),
    }
}

fn lua_tonumber(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        None => Err(interp.error_with(
            &["[C]: in ?".to_string()],
            "bad argument #1 to 'tonumber' (value expected)",
        )),
        Some(v) => {
            if let Some(base) = args.get(1) {
                let base = as_int(base).unwrap_or(10);
                let s = match v {
                    Value::Str(s) => s.trim().to_string(),
                    other => lua_tostring(other),
                };
                if (2..=36).contains(&base) {
                    match i64::from_str_radix(&s, base as u32) {
                        Ok(i) => Ok(vec![Value::Integer(i)]),
                        Err(_) => Ok(vec![Value::Nil]),
                    }
                } else {
                    Ok(vec![Value::Nil])
                }
            } else {
                match number_of(v) {
                    Some(NumKind::Int(i)) => Ok(vec![Value::Integer(i)]),
                    Some(NumKind::Float(f)) => Ok(vec![Value::Float(f)]),
                    None => Ok(vec![Value::Nil]),
                }
            }
        }
    }
}

fn lua_type(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        None => Err(interp.error_with(
            &["[C]: in ?".to_string()],
            "bad argument #1 to 'type' (value expected)",
        )),
        Some(v) => Ok(vec![Value::Str(Rc::new(type_name(v).to_string()))]),
    }
}

fn lua_pairs(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "pairs")?;
    let entries: Vec<(Value, Value)> = t.borrow().iter_pairs().collect();
    let iter = native(
        move |interp: &mut Interp, a: Vec<Value>| -> Result<Vec<Value>, String> {
            let state = match a.first() {
                Some(Value::Table(t)) => t.clone(),
                _ => {
                    return Err(interp.error_with(
                        &["[C]: in ?".to_string()],
                        "bad argument #1 to 'pairs' (table expected)",
                    ))
                }
            };
            let key = a.get(1).cloned().unwrap_or(Value::Nil);
            let entries: Vec<(Value, Value)> = state.borrow().iter_pairs().collect();
            // find the entry after the key
            let start = if matches!(key, Value::Nil) {
                0
            } else {
                entries
                    .iter()
                    .position(|(k, _)| values_equal(k, &key))
                    .map(|i| i + 1)
                    .unwrap_or(entries.len())
            };
            Ok(match entries.get(start) {
                Some((k, v)) => vec![k.clone(), v.clone()],
                None => vec![Value::Nil],
            })
        },
        "pairs iterator",
    );
    Ok(vec![iter, Value::Table(t), Value::Nil])
}

fn lua_ipairs(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "ipairs")?;
    let iter = native(
        move |interp: &mut Interp, a: Vec<Value>| -> Result<Vec<Value>, String> {
            let state = match a.first() {
                Some(Value::Table(t)) => t.clone(),
                _ => {
                    return Err(interp.error_with(
                        &["[C]: in ?".to_string()],
                        "bad argument #1 to 'ipairs' (table expected)",
                    ))
                }
            };
            let i = match a.get(1) {
                Some(v) => as_int(v).unwrap_or(0),
                None => 0,
            };
            let next = i + 1;
            let v = state.borrow().get(&Value::Integer(next));
            if matches!(v, Value::Nil) {
                Ok(vec![Value::Nil])
            } else {
                Ok(vec![Value::Integer(next), v])
            }
        },
        "ipairs iterator",
    );
    Ok(vec![iter, Value::Table(t), Value::Integer(0)])
}

fn lua_next(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "next")?;
    let key = args.get(1).cloned().unwrap_or(Value::Nil);
    let entries: Vec<(Value, Value)> = t.borrow().iter_pairs().collect();
    let start = if matches!(key, Value::Nil) {
        0
    } else {
        entries
            .iter()
            .position(|(k, _)| values_equal(k, &key))
            .map(|i| i + 1)
            .unwrap_or(entries.len())
    };
    Ok(match entries.get(start) {
        Some((k, v)) => vec![k.clone(), v.clone()],
        None => vec![Value::Nil],
    })
}

fn lua_error(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let msg = match args.first() {
        Some(v) => lua_tostring(v),
        None => "(error object is not a string)".to_string(),
    };
    Err(interp.error_with(
        &["[C]: in ?".to_string()],
        &msg,
    ))
}

fn lua_assert(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        Some(v) if truthy(v) => Ok(args),
        _ => {
            let msg = match args.get(1) {
                Some(m) => lua_tostring(m),
                None => "assertion failed!".to_string(),
            };
            Err(interp.error_with(&["[C]: in ?".to_string()], &msg))
        }
    }
}

fn lua_pcall(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let f = args.first().cloned().unwrap_or(Value::Nil);
    let rest: Vec<Value> = args.iter().skip(1).cloned().collect();
    let saved = interp.frames.len();
    let res = interp.call_value(f, rest, "main chunk");
    interp.frames.truncate(saved);
    match res {
        Ok(vals) => {
            let mut out = vec![Value::Boolean(true)];
            out.extend(vals);
            Ok(out)
        }
        Err(e) => {
            let msg = e.split("\nstack traceback:").next().unwrap_or(&e).to_string();
            let msg = msg
                .strip_prefix(&format!("{}: ", interp.chunk))
                .unwrap_or(&msg)
                .to_string();
            Ok(vec![Value::Boolean(false), Value::Str(Rc::new(msg))])
        }
    }
}

fn lua_select(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        Some(Value::Str(s)) if *s == "#" => Ok(vec![Value::Integer(args.len() as i64 - 1)]),
        other => {
            let i = match other {
                Some(v) => as_int(v).unwrap_or(1),
                None => {
                    return Err(interp.error_with(
                        &["[C]: in ?".to_string()],
                        "bad argument #1 to 'select' (number expected, got no value)",
                    ))
                }
            };
            if i < 0 {
                let n = args.len() as i64 - 1;
                let start = (n + i + 1).max(1) as usize;
                Ok(args.iter().skip(start).cloned().collect())
            } else {
                Ok(args.iter().skip(i as usize).cloned().collect())
            }
        }
    }
}

fn lua_rawget(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "rawget")?;
    let k = args.get(1).cloned().unwrap_or(Value::Nil);
    Ok(vec![t.borrow().get(&k)])
}

fn lua_rawset(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "rawset")?;
    let k = args.get(1).cloned().unwrap_or(Value::Nil);
    let v = args.get(2).cloned().unwrap_or(Value::Nil);
    t.borrow_mut().set(k, v);
    Ok(vec![args.first().cloned().unwrap_or(Value::Nil)])
}

fn lua_rawequal(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let a = args.first().cloned().unwrap_or(Value::Nil);
    let b = args.get(1).cloned().unwrap_or(Value::Nil);
    Ok(vec![Value::Boolean(values_equal(&a, &b))])
}

fn lua_rawlen(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        Some(Value::Table(t)) => Ok(vec![Value::Integer(t.borrow().length())]),
        Some(Value::Str(s)) => Ok(vec![Value::Integer(s.chars().count() as i64)]),
        other => Err(interp.error_with(
            &["[C]: in ?".to_string()],
            &format!(
                "bad argument #1 to 'rawlen' (table or string expected)",
            )
            .replace(
                &format!("to 'rawlen' (table or string expected)"),
                &format!(
                    "to 'rawlen' (table or string expected, got {})",
                    type_name(other.unwrap_or(&Value::Nil))
                ),
            ),
        )),
    }
}

fn lua_setmetatable(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    Ok(vec![args.first().cloned().unwrap_or(Value::Nil)])
}

fn lua_getmetatable(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    Ok(vec![Value::Nil])
}
