                }
            }
            's' => {
                argi += 1;
                let s = match &arg {
                    Value::Str(s) => s.to_string(),
                    other => lua_tostring(other),
                };
                if !precision.is_empty() {
                    s.chars().take(prec_n).collect::<String>()
                } else {
                    s
                }
            }
            'q' => {
                argi += 1;
                let s = match &arg {
                    Value::Str(s) => crate::lua::lua_escape(&s),
                    other => lua_tostring(other),
                };
                s
            }
            'f' => {
                argi += 1;
                let v = match to_float(&arg) {
                    Some(v) => v,
                    None => {
                        return Err(interp.error_with(
                            &["[C]: in ?".to_string()],
                            &format!(
                                "bad argument #{} to 'format' (number expected, got {})",
                                argi,
                                type_name(&arg)
                            ),
                        ))
                    }
                };
                format!("{:.*}", prec_n, v)
            }
            'e' | 'E' => {
                argi += 1;
                let v = match to_float(&arg) {
                    Some(v) => v,
                    None => {
                        return Err(interp.error_with(
                            &["[C]: in ?".to_string()],
