                                "bad argument #{} to 'format' (number expected, got {})",
                                argi,
                                type_name(&arg)
                            ),
                        ))
                    }
                };
                let mut s = format!("{:.*e}", prec_n, v);
                // normalize exponent to printf style
                if let Some(pos) = s.find('e') {
                    let (m, e) = s.split_at(pos);
                    let ev: i32 = e[1..].parse().unwrap_or(0);
                    let sign = if ev < 0 { "-" } else { "+" };
                    s = format!("{m}e{}{:02}", sign, ev.abs());
