                                type_name(&arg)
                            ),
                        ))
                    }
                };
                let s = crate::lua::format_lua_float(v);
                if spec == 'G' {
                    s.to_uppercase()
                } else {
                    s
                }
            }
            'x' | 'X' | 'o' | 'u' | 'c' => {
                argi += 1;
                let v = match as_int(&arg) {
                    Some(v) => v,
                    None => {
                        return Err(interp.error_with(
                            &["[C]: in ?".to_string()],
                            &format!(
                                "bad argument #{} to 'format' (number has no integer representation)",
                                argi
                            ),
                        ))
                    }
                };
                match spec {
                    'x' => format!("{v:x}"),
                    'X' => format!("{v:X}"),
                    'o' => format!("{v:o}"),
                    'u' => format!("{}", v as u64),
                    _ => (v as u32 as u8 as char).to_string(),
                }
            }
            other => {
                return Err(interp.error_with(
                    &["[C]: in ?".to_string()],
                    &format!("invalid conversion '%{other}' to 'format'"),
                ))
            }
        };
        if width_n > rendered.chars().count() {
            let pad_char = if zero && spec != 's' { '0' } else { ' ' };
            let pad = pad_char
                .to_string()
                .repeat(width_n - rendered.chars().count());
            if left {
                out.push_str(&rendered);
                out.push_str(&pad);
            } else {
                out.push_str(&pad);
                out.push_str(&rendered);
            }
        } else {
            out.push_str(&rendered);
        }
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

fn lua_init_pos(pattern: &str) -> (usize, bool) {
    let mut anchored = false;
    let mut p = pattern.chars();
    let mut pos = 0usize;
    let mut chars = pattern.chars();
    if let Some('^') = chars.next() {
        anchored = true;
        pos += 1;
    }
    let _ = p;
    (pos, anchored)
}
