fn pattern_find(
    s: &[char],
    p: &[char],
    init: usize,
) -> Option<(usize, usize, Vec<(usize, usize)>)> {
    let (pstart, anchored) = lua_init_pos(&p.iter().collect::<String>());
    let mut start = init;
    loop {
        if start > s.len() {
            return None;
        }
        let mut caps: Vec<(usize, usize)> = Vec::new();
        if let Some(end) = match_here(s, p, pstart, start, &mut caps) {
            return Some((start, end, caps));
        }
        if anchored {
            return None;
        }
        start += 1;
    }
}

fn match_here(
    s: &[char],
    p: &[char],
    pi: usize,
    si: usize,
    caps: &mut Vec<(usize, usize)>,
) -> Option<usize> {
    if pi >= p.len() {
        return Some(si);
    }
    match p[pi] {
        ')' => Some(si),
        '(' => {
            // capture
            let mut depth = 1;
            let mut j = pi + 1;
            while j < p.len() && depth > 0 {
                match p[j] {
                    '(' => depth += 1,
                    ')' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if depth != 0 {
                return None;
            }
            let cap_start = caps.len();
            caps.push((si, usize::MAX));
            let end = match_here(s, p, j + 1, si, caps);
            match end {
                Some(e) => {
                    caps[cap_start] = (si, e);
                    Some(e)
                }
                None => {
                    caps.truncate(cap_start);
                    None
                }
            }
        }
        '$' if pi + 1 == p.len() => {
            if si == s.len() {
                Some(si)
            } else {
                None
            }
        }
        '%' if p.get(pi + 1) == Some(&'b') => {
            let open = *p.get(pi + 2)?;
            let close = *p.get(pi + 3)?;
            let mut depth = 0;
            let mut i = si;
            loop {
                if i >= s.len() {
                    return None;
                }
                let c = s[i];
                if c == close {
                    if depth == 0 {
                        return None;
                    }
                    depth -= 1;
                    if depth == 0 {
                        return match_here(s, p, pi + 4, i + 1, caps);
                    }
                } else if c == open {
                    depth += 1;
                }
                i += 1;
            }
        }
        '%' if p.get(pi + 1) == Some(&'f') => {
            // frontier
            let item = parse_item(p, pi + 2)?;
            let prev_ok = if si == 0 {
                false
            } else {
                item.matches(s[si - 1])
            };
            let cur_ok = si < s.len() && item.matches(s[si]);
            if !prev_ok && cur_ok {
                match_here(s, p, pi + 2 + item.len, si, caps)
            } else {
                None
            }
        }
        '%' if p.get(pi + 1).map(|c| c.is_ascii_digit()).unwrap_or(false) => {
            let idx = p[pi + 1] as usize - '1' as usize;
            if let Some(&(a, b)) = caps.get(idx) {
                if b != usize::MAX {
                    let text: String = s[a..b].iter().collect();
                    let text_chars: Vec<char> = text.chars().collect();
                    if si + text_chars.len() <= s.len()
                        && s[si..si + text_chars.len()] == text_chars[..]
                    {
                        return match_here(s, p, pi + 2, si + text_chars.len(), caps);
                    }
                }
            }
            None
        }
        _ => {
            let item = parse_item(p, pi)?;
            let quant = p.get(pi + item.len).copied();
            match quant {
                Some('*') => {
                    let mut i = si;
                    let mut best = None;
                    loop {
                        match match_here(s, p, pi + item.len + 1, i, caps) {
                            Some(e) => {
                                best = Some(e);
                                break;
                            }
                            None => {
                                if i < s.len() && item.matches(s[i]) {
                                    i += 1;
                                } else {
                                    break;
                                }
                            }
                        }
                    }
                    best
                }
                Some('+') => {
                    let mut i = si;
                    while i < s.len() && item.matches(s[i]) {
                        i += 1;
                    }
                    if i == si {
                        return None;
                    }
                    // greedy with backtracking
                    loop {
                        match match_here(s, p, pi + item.len + 1, i, caps) {
                            Some(e) => return Some(e),
                            None => {
                                if i == si {
                                    return None;
                                }
                                i -= 1;
                            }
                        }
                    }
                }
                Some('-') => {
                    let mut i = si;
                    loop {
                        match match_here(s, p, pi + item.len + 1, i, caps) {
                            Some(e) => return Some(e),
                            None => {
                                if i < s.len() && item.matches(s[i]) {
                                    i += 1;
                                } else {
                                    return None;
                                }
                            }
                        }
                    }
                }
                Some('?') => {
                    if si < s.len() && item.matches(s[si]) {
                        if let Some(e) = match_here(s, p, pi + item.len + 1, si + 1, caps) {
                            return Some(e);
                        }
                    }
                    match_here(s, p, pi + item.len + 1, si, caps)
                }
                _ => {
                    if si < s.len() && item.matches(s[si]) {
                        match_here(s, p, pi + item.len, si + 1, caps)
                    } else {
                        None
                    }
                }
            }
        }
    }
}

fn captures_to_strings(
    s: &[char],
    caps: &[(usize, usize)],
    whole: (usize, usize),
) -> Vec<Value> {
    let mut out = Vec::new();
    if caps.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
        return out;
    }
    for (a, b) in caps {
        if *b == usize::MAX {
            continue;
        }
        let text: String = s[*a..*b].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    if out.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    out
}

fn str_find(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "string.find", "string")?;
    let pat = str_arg(interp, &args, 1, "string.find", "string")?;
    let init = args.get(2).and_then(as_int).unwrap_or(1);
    let plain = matches!(args.get(3), Some(Value::Boolean(true)));
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let init = if init < 0 { (n + init + 1).max(1) } else { init };
    let init = (init - 1).max(0) as usize;
    if plain {
        let pchars: Vec<char> = pat.chars().collect();
        let mut i = init;
        while i + pchars.len() <= chars.len() {
            if chars[i..i + pchars.len()] == pchars[..] {
                return Ok(vec![
                    Value::Integer(i as i64 + 1),
                    Value::Integer((i + pchars.len()) as i64),
                ]);
            }
            i += 1;
        }
        return Ok(vec![Value::Nil]);
    }
    let pchars: Vec<char> = pat.chars().collect();
    match pattern_find(&chars, &pchars, init) {
        Some((a, b, caps)) => {
            let mut out = vec![Value::Integer(a as i64 + 1), Value::Integer(b as i64)];
            out.extend(captures_to_strings(&chars, &caps, (a, b)));
            Ok(out)
        }
        None => Ok(vec![Value::Nil]),
    }
}

fn str_match(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "string.match", "string")?;
    let pat = str_arg(interp, &args, 1, "string.match", "string")?;
    let init = args.get(2).and_then(as_int).unwrap_or(1);
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let init = if init < 0 { (n + init + 1).max(1) } else { init };
    let init = (init - 1).max(0) as usize;
    let pchars: Vec<char> = pat.chars().collect();
    match pattern_find(&chars, &pchars, init) {
        Some((a, b, caps)) => Ok(captures_to_strings(&chars, &caps, (a, b))),
        None => Ok(vec![Value::Nil]),
    }
}

fn str_gmatch(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "string.gmatch", "string")?;
    let pat = str_arg(interp, &args, 1, "string.gmatch", "string")?;
    let chars: Vec<char> = s.chars().collect();
    let pchars: Vec<char> = pat.chars().collect();
    let anchored = pchars.first() == Some(&'^');
    let iter = native(
        move |interp: &mut Interp, _a: Vec<Value>| -> Result<Vec<Value>, String> {
            let _ = interp;
            let mut state = GMATCH_STATE.lock().unwrap();
            let st = state.entry(GMATCH_KEY).or_insert((0usize, false));
            let (mut pos, done) = (st.0, st.1);
            if done {
                return Ok(vec![Value::Nil]);
            }
            let mut found = None;
            let mut search = pos;
            loop {
                if search > chars.len() {
                    break;
                }
                match pattern_find(&chars, &pchars, search) {
                    Some((a, b, caps)) => {
                        let next = if b > a { b } else { a + 1 };
                        if anchored && a != pos {
                            break;
                        }
                        found = Some((a, b, caps, next));
                        break;
                    }
                    None => break,
                }
            }
            match found {
                Some((a, b, caps, next)) => {
                    st.0 = next;
                    if next > chars.len() {
                        st.1 = true;
                    }
                    Ok(captures_to_strings(&chars, &caps, (a, b)))
                }
                None => {
                    st.1 = true;
                    Ok(vec![Value::Nil])
                }
            }
        },
        "gmatch iterator",
    );
    Ok(vec![iter])
}

use std::sync::Mutex;
static GMATCH_STATE: Mutex<std::collections::HashMap<usize, (usize, bool)>> =
    Mutex::new(std::collections::HashMap::new());
static GMATCH_KEY: usize = 0;

fn str_gsub(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "string.gsub", "string")?;
    let pat = str_arg(interp, &args, 1, "string.gsub", "string")?;
    let repl = args.get(2).cloned().unwrap_or(Value::Nil);
    let maxn = args.get(3).and_then(as_int).unwrap_or(i64::MAX);
    let chars: Vec<char> = s.chars().collect();
    let pchars: Vec<char> = pat.chars().collect();
    let mut out = String::new();
    let mut pos = 0usize;
    let mut count = 0i64;
    while pos <= chars.len() && count < maxn {
        match pattern_find(&chars, &pchars, pos) {
            Some((a, b, caps)) if a >= pos => {
                out.push_str(&chars[pos..a].iter().collect::<String>());
                let caps_strs = captures_to_strings(&chars, &caps, (a, b));
                let replacement = match &repl {
                    Value::Str(r) => {
                        let rchars: Vec<char> = r.chars().collect();
                        let mut res = String::new();
                        let mut i = 0usize;
                        while i < rchars.len() {
                            if rchars[i] == '%' && i + 1 < rchars.len() {
                                let k = rchars[i + 1];
                                i += 2;
                                if k.is_ascii_digit() {
                                    let idx = (k as usize - '1' as usize) + 1;
                                    res.push_str(
                                        caps_strs
                                            .get(idx)
                                            .map(|v| match v {
                                                Value::Str(x) => x.to_string(),
                                                other => lua_tostring(other),
                                            })
                                            .unwrap_or_default(),
                                    );
                                } else if k == '%' {
                                    res.push('%');
                                } else if k == '0' {
                                    res.push_str(&chars[a..b].iter().collect::<String>());
                                } else {
                                    res.push(k);
                                }
                            } else {
                                res.push(rchars[i]);
                                i += 1;
                            }
                        }
                        res
                    }
                    Value::Table(t) => {
                        let key = caps_strs.first().cloned().unwrap_or(Value::Nil);
                        let v = t.borrow().get(&key);
                        if matches!(v, Value::Nil | Value::Boolean(false)) {
                            chars[a..b].iter().collect::<String>()
                        } else {
                            lua_tostring(&v)
                        }
                    }
                    Value::Function(_) | Value::Native(_) => {
                        let vals = interp.call_value(repl.clone(), caps_strs.clone(), "main chunk")?;
                        let v = vals.first().cloned().unwrap_or(Value::Nil);
                        if matches!(v, Value::Nil | Value::Boolean(false)) {
                            chars[a..b].iter().collect::<String>()
                        } else {
                            lua_tostring(&v)
                        }
                    }
                    _ => chars[a..b].iter().collect::<String>(),
                };
                out.push_str(&replacement);
                count += 1;
                pos = if b > a { b } else { a + 1 };
            }
            _ => {
                break;
            }
        }
    }
    out.push_str(&chars[pos.min(chars.len())..].iter().collect::<String>());
    Ok(vec![
        Value::Str(Rc::new(out)),
        Value::Integer(count),
    ])
}
