fn class_match(c: char, class: char) -> bool {
    match class {
        'a' => c.is_alphabetic(),
        'c' => c.is_control(),
        'd' => c.is_ascii_digit(),
        'l' => c.is_ascii_lowercase(),
        'p' => c.is_ascii_punctuation(),
        's' => c.is_whitespace(),
        'u' => c.is_ascii_uppercase(),
        'w' => c.is_ascii_alphanumeric() || c == '_',
        'x' => c.is_ascii_hexdigit(),
        'A' => !c.is_alphabetic(),
        'C' => !c.is_control(),
        'D' => !c.is_ascii_digit(),
        'L' => !c.is_ascii_lowercase(),
        'P' => !c.is_ascii_punctuation(),
        'S' => !c.is_whitespace(),
        'U' => !c.is_ascii_uppercase(),
        'W' => !(c.is_ascii_alphanumeric() || c == '_'),
        'X' => !c.is_ascii_hexdigit(),
        other => c == other,
    }
}

/// A single pattern item: returns the characters consumed from the pattern.
struct Item {
    len: usize,
    class: Class,
}

enum Class {
    Any,
    Single(char),
    Neg(char),
    Set(Vec<(char, char)>, bool),
}

impl Item {
    fn matches(&self, c: char) -> bool {
        match &self.class {
            Class::Any => true,
            Class::Single(x) => *x == c,
            Class::Neg(x) => *x != c,
            Class::Set(ranges, negated) => {
                let mut m = false;
                for (a, b) in ranges {
                    if c >= *a && c <= *b {
                        m = true;
                        break;
                    }
                }
                if *negated {
                    !m
                } else {
                    m
                }
            }
        }
    }
}

fn parse_item(p: &[char], pi: usize) -> Option<Item> {
    let c = p[pi];
    match c {
        '.' => Some(Item {
            len: 1,
            class: Class::Any,
        }),
        '%' => {
            let k = *p.get(pi + 1)?;
            match k {
                'a' | 'c' | 'd' | 'l' | 'p' | 's' | 'u' | 'w' | 'x' => Some(Item {
                    len: 2,
                    class: Class::Single(k),
                }),
                'A' | 'C' | 'D' | 'L' | 'P' | 'S' | 'U' | 'W' | 'X' => Some(Item {
                    len: 2,
                    class: Class::Neg(k),
                }),
                _ => Some(Item {
                    len: 2,
                    class: Class::Single(k),
                }),
            }
        }
        '[' => {
            let mut i = pi + 1;
            let negated = if p.get(i) == Some(&'^') {
                i += 1;
                true
            } else {
                false
            };
            let mut ranges: Vec<(char, char)> = Vec::new();
            let mut first = true;
            while i < p.len() {
                if p[i] == ']' && !first {
                    break;
                }
                first = false;
                if p[i] == '%' && i + 1 < p.len() {
                    let k = p[i + 1];
                    if "acdlpsuwxACDLPSUWX".contains(k) {
                        ranges.push((k, k));
                        // expand the class into ranges lazily: store as a single
                        // char and use class_match for singles
                    } else {
                        ranges.push((k, k));
                    }
                    i += 2;
                    continue;
                }
                if i + 2 < p.len() && p[i + 1] == '-' && p[i + 2] != ']' {
                    ranges.push((p[i], p[i + 2]));
                    i += 3;
                    continue;
                }
                ranges.push((p[i], p[i]));
                i += 1;
            }
            Some(Item {
                len: i + 1 - pi,
                class: Class::Set(ranges, negated),
            })
        }
        other => Some(Item {
            len: 1,
            class: Class::Single(other),
        }),
    }
}

