fn table_insert(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "table.insert")?;
    if args.len() >= 3 {
        let pos = match args.get(1) {
            Some(v) => as_int(v).unwrap_or(1),
            None => {
                return Err(interp.error_with(
                    &["[C]: in ?".to_string()],
                    "bad argument #2 to 'table.insert' (number expected, got no value)",
                ))
            }
        };
        let value = args[2].clone();
        let mut entries: Vec<(Value, Value)> = t.borrow().entries.clone();
        let n = entries.len() as i64;
        let p = if pos < 0 { n + pos + 2 } else { pos };
        entries.insert((p - 1).max(0) as usize, (Value::Integer(p), value));
        for (i, e) in entries.iter_mut().enumerate() {
            e.0 = Value::Integer(i as i64 + 1);
        }
        t.borrow_mut().entries = entries;
        t.borrow_mut().index.clear();
        for (i, (k, _)) in t.borrow().entries.clone().iter().enumerate() {
            t.borrow_mut().index.insert(key_key(k), i);
        }
    } else {
        let value = args.get(1).cloned().unwrap_or(Value::Nil);
        let len = t.borrow().length();
        t.borrow_mut().set(Value::Integer(len + 1), value);
    }
    Ok(vec![])
}

fn table_remove(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "table.remove")?;
    let len = t.borrow().length();
    let pos = args.get(1).and_then(as_int).unwrap_or(len);
    if len == 0 {
        return Ok(vec![Value::Nil]);
    }
    let p = if pos < 0 { len + pos + 1 } else { pos };
    let v = t.borrow().get(&Value::Integer(p));
    // shift down
    let mut i = p;
    while i < len {
        let nv = t.borrow().get(&Value::Integer(i + 1));
        t.borrow_mut().set(Value::Integer(i), nv);
        i += 1;
    }
    t.borrow_mut().set(Value::Integer(len), Value::Nil);
    Ok(vec![v])
}

fn table_concat(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "table.concat")?;
    let sep = args.get(1).and_then(|v| match v {
        Value::Str(s) => Some(s.to_string()),
        other => Some(lua_tostring(other)),
    });
    let start = args.get(2).and_then(as_int).unwrap_or(1);
    let end = args.get(3).and_then(as_int).unwrap_or_else(|| t.borrow().length());
    let mut out = String::new();
    let mut i = start;
    while i <= end {
        if i > start {
            if let Some(s) = &sep {
                out.push_str(s);
            }
        }
        let v = t.borrow().get(&Value::Integer(i));
        match &v {
            Value::Str(s) => out.push_str(s),
            Value::Integer(x) => out.push_str(&x.to_string()),
            Value::Float(x) => out.push_str(&format_lua_float(*x)),
            other => {
                return Err(interp.error_with(
                    &["[C]: in ?".to_string()],
                    &format!(
                        "invalid value (at index {}) in table for 'concat'",
                        i
                    )
                    .replace(
                        "(at index ",
                        &format!("(at index {})", i).replace(&format!("{}", i), &format!("{}", i)),
                    ),
                ))
            }
        }
        i += 1;
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

fn table_sort(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "table.sort")?;
    let len = t.borrow().length();
    let mut items: Vec<Value> = Vec::new();
    for i in 1..=len {
        items.push(t.borrow().get(&Value::Integer(i)));
    }
    if let Some(cmp) = args.get(1).cloned() {
        // sort with a comparator
        let mut sorted = items;
        // simple insertion sort calling the comparator
        for i in 1..sorted.len() {
            let mut j = i;
            while j > 0 {
                let res = interp.call_value(
                    cmp.clone(),
                    vec![sorted[j - 1].clone(), sorted[j].clone()],
                    "main chunk",
                )?;
                if truthy(res.first().unwrap_or(&Value::Nil)) {
                    sorted.swap(j - 1, j);
                    j -= 1;
                } else {
                    break;
                }
            }
        }
        items = sorted;
    } else {
        items.sort_by(|a, b| match (number_of(a), number_of(b)) {
            (Some(x), Some(y)) => xf(&x).partial_cmp(&xf(&y)).unwrap_or(std::cmp::Ordering::Equal),
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, None) => match (a, b) {
                (Value::Str(x), Value::Str(y)) => x.cmp(y),
                _ => std::cmp::Ordering::Equal,
            },
        });
    }
    for (i, v) in items.iter().enumerate() {
        t.borrow_mut().set(Value::Integer(i as i64 + 1), v.clone());
    }
    Ok(vec![])
}

fn table_unpack(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "table.unpack")?;
    let len = t.borrow().length();
    let start = args.get(1).and_then(as_int).unwrap_or(1);
    let end = args.get(2).and_then(as_int).unwrap_or(len);
    let mut out = Vec::new();
    let mut i = start;
    while i <= end {
        out.push(t.borrow().get(&Value::Integer(i)));
        i += 1;
    }
    Ok(out)
}

fn table_pack(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = Rc::new(RefCell::new(Table::new()));
    for (i, v) in args.iter().enumerate() {
        t.borrow_mut().set(Value::Integer(i as i64 + 1), v.clone());
    }
    t.borrow_mut()
        .set(Value::Str(Rc::new("n".to_string())), Value::Integer(args.len() as i64));
    Ok(vec![Value::Table(t)])
}

fn table_move(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let src = table_arg(interp, &args, 0, "table.move")?;
    let f = args.get(1).and_then(as_int).unwrap_or(1);
    let t_end = args.get(2).and_then(as_int).unwrap_or(0);
    let dst_idx = args.get(3).and_then(as_int).unwrap_or(1);
    let dst = match args.get(4) {
        Some(Value::Table(t)) => t.clone(),
        _ => src.clone(),
    };
    let mut i = f;
    let mut k = dst_idx;
    while i <= t_end {
        let v = src.borrow().get(&Value::Integer(i));
        dst.borrow_mut().set(Value::Integer(k), v);
        i += 1;
        k += 1;
    }
    Ok(vec![Value::Table(dst)])
}

