fn os_time(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    let now = crate::now_seconds() as i64;
    if let Some(Value::Table(t)) = args.first() {
        let get = |k: &str| -> Option<i64> {
            t.borrow()
                .get(&Value::Str(Rc::new(k.to_string())))
                .as_int_option()
        };
        let year = get("year").unwrap_or(1970);
        let month = get("month").unwrap_or(1);
        let day = get("day").unwrap_or(1);
        let hour = get("hour").unwrap_or(12);
        let min = get("min").unwrap_or(0);
        let sec = get("sec").unwrap_or(0);
        let days = crate::days_from_civil_pub(year, month as u32, day as u32);
        return Ok(vec![Value::Integer(
            days * 86400 + hour * 3600 + min * 60 + sec,
        )]);
    }
    Ok(vec![Value::Integer(now)])
}

