    let wdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    let months = [
        "January", "February", "March", "April", "May", "June", "July", "August", "September",
        "October", "November", "December",
    ];
    let mut out = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] != '%' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        i += 1;
        let spec = chars.get(i).cloned().unwrap_or('%');
        i += 1;
        match spec {
            'Y' => out.push_str(&format!("{y:04}")),
            'y' => out.push_str(&format!("{:02}", y.rem_euclid(100))),
            'm' => out.push_str(&format!("{m:02}")),
            'd' => out.push_str(&format!("{d:02}")),
            'H' => out.push_str(&format!("{h:02}")),
            'M' => out.push_str(&format!("{mi:02}")),
            'S' => out.push_str(&format!("{s:02}")),
            'A' => out.push_str(wdays[weekday as usize]),
            'a' => out.push_str(&wdays[weekday as usize][..3]),
            'B' => out.push_str(months[(m - 1) as usize]),
            'b' => out.push_str(&months[(m - 1) as usize][..3]),
            'p' => out.push_str(if h < 12 { "AM" } else { "PM" }),
            'c' => out.push_str(&format!(
                "{} {} {:02} {:02}:{:02}:{:02} {}",
                wdays[weekday as usize][..3].to_string(),
                months[(m - 1) as usize][..3].to_string(),
                d,
                h,
                mi,
                s,
                y
            )),
            'x' => out.push_str(&format!("{m:02}/{d:02}/{:02}", y.rem_euclid(100))),
            'X' => out.push_str(&format!("{h:02}:{mi:02}:{s:02}")),
            'j' => out.push_str(&format!("{:03}", days - crate::days_from_civil_pub(y, 1, 1) + 1)),
            'U' => out.push_str(&format!("{:02}", (rem + (weekday * 86400)) / (7 * 86400))),
            'w' => out.push_str(&format!("{weekday}")),
            '%' => out.push('%'),
            other => {
                out.push('%');
                out.push(other);
            }
        }
    }
    out
}
