pub fn dump_entry(
    _path: &str,
    value: &Value,
    _parent_is_array: bool,
    exclusions: &[String],
    out: &mut Vec<(Vec<Step>, String)>,
) {
    dump_steps(&[], value, false, exclusions, out);
}

fn dump_steps(
    steps: &[Step],
    value: &Value,
    parent_is_array: bool,
    exclusions: &[String],
    out: &mut Vec<(Vec<Step>, String)>,
) {
    match value {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let v = map.get(k).unwrap();
                if v.is_null() {
                    continue;
                }
                let mut new_steps: Vec<Step> = steps.to_vec();
                new_steps.push(Step::Key(k.clone()));
                dump_steps(&new_steps, v, false, exclusions, out);
            }
        }
        Value::Array(items) => {
            let base = if parent_is_array { 1usize } else { 0usize };
            for (i, item) in items.iter().enumerate() {
                let mut new_steps: Vec<Step> = steps.to_vec();
                new_steps.push(Step::Index(i + base));
                dump_steps(&new_steps, item, true, exclusions, out);
            }
        }
        other => {
            let path_str = render_steps(steps);
            if exclusions.iter().any(|e| e == &path_str) {
                return;
            }
            let rendered = if parent_is_array {
                other.to_string()
            } else {
                match other {
                    Value::String(s) => s.clone(),
                    Value::Number(n) => n.to_string(),
                    Value::Bool(b) => b.to_string(),
                    _ => String::new(),
                }
            };
            out.push((steps.to_vec(), rendered));
        }
    }
}

