#[derive(Clone)]
enum IterKind {
    Pairs,
    IPairs,
    GMatch,
}

impl IterState {
    fn clone_state(&self) -> IterKind {
        match self {
            IterState::Pairs { .. } => IterKind::Pairs,
            IterState::IPairs { .. } => IterKind::IPairs,
            IterState::GMatch { .. } => IterKind::GMatch,
        }
    }
    fn table_rc(&self) -> Rc<RefCell<Table>> {
        match self {
            IterState::Pairs { table, .. } | IterState::IPairs { table, .. } => table.clone(),
            IterState::GMatch { .. } => Rc::new(RefCell::new(Table::new())),
        }
    }
    fn iter_pos(&self) -> usize {
        match self {
            IterState::Pairs { pos, .. } | IterState::GMatch { pos, .. } => *pos,
            IterState::IPairs { next, .. } => *next as usize,
        }
    }
    fn set_pos(&mut self, p: usize) {
        match self {
            IterState::Pairs { pos, .. } | IterState::GMatch { pos, .. } => *pos = p,
            IterState::IPairs { .. } => {}
        }
    }
    fn iter_next(&self) -> i64 {
        match self {
            IterState::IPairs { next, .. } => *next,
            _ => 0,
        }
    }
    fn set_next(&mut self, n: i64) {
        if let IterState::IPairs { next, .. } = self {
            *next = n;
        }
    }
    fn is_done(&self) -> bool {
        match self {
            IterState::GMatch { done, .. } => *done,
            _ => false,
        }
    }
    fn set_done(&mut self, d: bool) {
        if let IterState::GMatch { done, .. } = self {
            *done = d;
        }
    }
    fn gmatch_data(&self) -> (Vec<char>, Vec<char>, bool) {
        match self {
            IterState::GMatch {
                chars,
                pat,
                anchored,
                ..
            } => (chars.clone(), pat.clone(), *anchored),
            _ => (Vec::new(), Vec::new(), false),
        }
    }
}
