/// Compiles a chunk: a single expression is turned into a `return` statement
/// (mirroring mlua's expression chunk loading).
pub fn compile_chunk(code: &str) -> Result<Vec<Stmt>, String> {
    // Try to interpret the whole source as a single expression first.
    let trimmed = code.trim_start();
    let stripped = trimmed.trim_end();
    let stripped = stripped.strip_suffix(';').unwrap_or(stripped).trim_end();
    if !stripped.is_empty() && !starts_with_statement_keyword(stripped) {
        let mut p = P::new(stripped);
        if let Ok(expr) = p.parse_expr() {
            if matches!(p.cur, Tok::Eof) {
                return Ok(vec![Stmt::Return(vec![expr])]);
            }
        }
    }
    let mut p = P::new(code);
    p.parse_chunk()
}

fn starts_with_statement_keyword(src: &str) -> bool {
    let mut lex = Lexer::new(src);
