// ---------------------------------------------------------------- stdlib

use std::io::Write;

fn arg_error(fname: &str, idx: usize, what: &str, got: Option<&str>) -> String {
    match (what.is_empty(), got) {
        (true, None) => format!("bad argument #{} to '{}' (value expected)", idx + 1, fname),
        (true, Some(g)) => format!("bad argument #{} to '{}' (value expected, got {})", idx + 1, fname, g),
        (false, None) => format!(
            "bad argument #{} to '{}' ({} expected, got no value)",
            idx + 1,
            fname,
            what
        ),
        (false, Some(g)) => format!(
            "bad argument #{} to '{}' ({} expected, got {})",
            idx + 1,
            fname,
            what,
            g
        ),
    }
}

fn num_arg(interp: &Interp, args: &[Value], idx: usize, fname: &str, what: &str) -> Result<f64, String> {
    match args.get(idx) {
        Some(v) => match number_of(v) {
            Some(n) => Ok(xf(&n)),
            None => Err(interp.error(&arg_error(fname, idx, what, Some(type_name(v))))),
        },
        None => Err(interp.error(&arg_error(fname, idx, what, None))),
    }
}

fn int_arg(interp: &Interp, args: &[Value], idx: usize, fname: &str, what: &str) -> Result<i64, String> {
    match args.get(idx) {
        Some(v) => match as_int(v) {
            Some(i) => Ok(i),
            None => Err(interp.error(&arg_error(
                fname,
                idx,
                what,
                Some(type_name(v)),
            ))),
        },
        None => Err(interp.error(&arg_error(fname, idx, what, None))),
    }
}

fn str_arg(interp: &Interp, args: &[Value], idx: usize, fname: &str) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok(s.to_string()),
