fn lua_tonumber(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    match args.first() {
        None => Err(interp.error(&arg_error("tonumber", 0, "", None))),
        Some(v) => {
            if let Some(base) = args.get(1) {
                let base = match as_int(base) {
                    Some(b) => b,
                    None => {
                        return Err(interp.error(&arg_error(
                            "tonumber",
                            1,
                            "number",
                            Some(type_name(base)),
                        )))
                    }
                };
                let s = match v {
                    Value::Str(s) => s.trim().to_string(),
                    other => lua_tostring(other),
                };
