fn str_format(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let fmt = str_arg(interp, &args, 0, "format")?;
    let chars: Vec<char> = fmt.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    let mut argi = 1usize;
    while i < chars.len() {
        let c = chars[i];
        if c != '%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= chars.len() {
            return Err(interp.error("invalid conversion to 'format'"));
        }
        if chars[i] == '%' {
            out.push('%');
            i += 1;
            continue;
        }
        let mut flags = String::new();
        while i < chars.len() && "-+ #0".contains(chars[i]) {
            flags.push(chars[i]);
            i += 1;
        }
        let mut width = String::new();
        while i < chars.len() && chars[i].is_ascii_digit() {
            width.push(chars[i]);
            i += 1;
        }
        let mut precision = String::new();
        if i < chars.len() && chars[i] == '.' {
            i += 1;
            while i < chars.len() && chars[i].is_ascii_digit() {
                precision.push(chars[i]);
                i += 1;
            }
        }
        let spec = chars.get(i).cloned().unwrap_or('%');
        i += 1;
        let width_n = width.parse::<usize>().unwrap_or(0);
        let prec_n = precision.parse::<usize>().unwrap_or(6);
        let left = flags.contains('-');
        let zero = flags.contains('0');
        let plus = flags.contains('+');
        let space = flags.contains(' ');
        let bad = |msg: String| -> Result<Vec<Value>, String> {
            Err(interp.error(&msg))
        };
        let arg = args.get(argi).cloned().unwrap_or(Value::Nil);
        let rendered = match spec {
            'd' | 'i' => {
                argi += 1;
                match as_int(&arg) {
                    Some(v) => {
                        let sign = if v < 0 {
                            "-"
                        } else if plus {
                            "+"
                        } else if space {
                            " "
                        } else {
                            ""
                        };
                        let digits = v.unsigned_abs().to_string();
                        if zero && width_n > digits.len() + sign.len() {
                            let pad = "0".repeat(width_n - digits.len() - sign.len());
                            format!("{sign}{pad}{digits}")
                        } else {
                            format!("{sign}{digits}")
                        }
                    }
                    None => {
                        return bad(arg_error(
                            "format",
                            argi,
                            "number has no integer representation",
                            Some(type_name(&arg)),
                        ))
                    }
                }
            }
            's' => {
                argi += 1;
                let s = match &arg {
                    Value::Str(s) => s.to_string(),
                    other => lua_tostring(other),
