                .to_string()
                .repeat(width_n - rendered.chars().count());
            if left {
                out.push_str(&rendered);
                out.push_str(&pad);
            } else {
                out.push_str(&pad);
                out.push_str(&rendered);
            }
        } else {
            out.push_str(&rendered);
        }
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

/// Finds the leftmost match of `p` in `s` starting at or after `init`.
fn pattern_find(
    s: &[char],
    p: &[char],
    init: usize,
) -> Option<(usize, usize, Vec<(usize, usize)>)> {
    let anchored = p.first() == Some(&'^');
    let pstart = if anchored { 1 } else { 0 };
    let mut start = init;
    loop {
        if start > s.len() {
            return None;
        }
        let mut caps: Vec<(usize, usize)> = Vec::new();
        if let Some(end) = match_here(s, p, pstart, start, &mut caps) {
            return Some((start, end, caps));
        }
        if anchored {
            return None;
        }
        start += 1;
    }
}

fn captures_to_strings(
    s: &[char],
    caps: &[(usize, usize)],
    whole: (usize, usize),
) -> Vec<Value> {
    let mut out = Vec::new();
    if caps.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
        return out;
    }
    for (a, b) in caps {
        if *b == usize::MAX {
            continue;
        }
        let text: String = s[*a..*b].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    if out.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    out
}

fn str_find(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "find")?;
    let pat = str_arg(interp, &args, 1, "find")?;
    let init = match args.get(2) {
        Some(v) => match as_int(v) {
            Some(i) => i,
            None => {
                return Err(interp.error(&arg_error(
                    "find",
                    2,
                    "number",
                    Some(type_name(v)),
                )))
            }
        },
        None => 1,
    };
    let plain = matches!(args.get(3), Some(Value::Boolean(true)));
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let init = if init < 0 { (n + init + 1).max(1) } else { init };
    let init = (init - 1).max(0) as usize;
    if plain {
        let pchars: Vec<char> = pat.chars().collect();
        let mut i = init;
        while i + pchars.len() <= chars.len() {
            if chars[i..i + pchars.len()] == pchars[..] {
                return Ok(vec![
                    Value::Integer(i as i64 + 1),
                    Value::Integer((i + pchars.len()) as i64),
                ]);
            }
            i += 1;
        }
        return Ok(vec![Value::Nil]);
    }
    let pchars: Vec<char> = pat.chars().collect();
    match pattern_find(&chars, &pchars, init) {
        Some((a, b, caps)) => {
            let mut out = vec![Value::Integer(a as i64 + 1), Value::Integer(b as i64)];
            out.extend(captures_to_strings(&chars, &caps, (a, b)));
            Ok(out)
        }
        None => Ok(vec![Value::Nil]),
    }
}

fn str_match(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "match")?;
    let pat = str_arg(interp, &args, 1, "match")?;
    let init = args.get(2).and_then(as_int).unwrap_or(1);
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let init = if init < 0 { (n + init + 1).max(1) } else { init };
    let init = (init - 1).max(0) as usize;
    let pchars: Vec<char> = pat.chars().collect();
    match pattern_find(&chars, &pchars, init) {
        Some((a, b, caps)) => Ok(captures_to_strings(&chars, &caps, (a, b))),
        None => Ok(vec![Value::Nil]),
    }
}

fn str_gmatch(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "gmatch")?;
    let pat = str_arg(interp, &args, 1, "gmatch")?;
    let chars: Vec<char> = s.chars().collect();
    let pchars: Vec<char> = pat.chars().collect();
    let anchored = pchars.first() == Some(&'^');
    let iter = Value::Iter(Rc::new(RefCell::new(IterState::GMatch {
        chars,
        pat: pchars,
        anchored,
        pos: 0,
        done: false,
    })));
    Ok(vec![iter])
}

fn str_gsub(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "gsub")?;
    let pat = str_arg(interp, &args, 1, "gsub")?;
    let repl = args.get(2).cloned().unwrap_or(Value::Nil);
    let maxn = args.get(3).and_then(as_int).unwrap_or(i64::MAX);
    let chars: Vec<char> = s.chars().collect();
    let pchars: Vec<char> = pat.chars().collect();
    let mut out = String::new();
    let mut pos = 0usize;
    let mut count = 0i64;
    while pos <= chars.len() && count < maxn {
        match pattern_find(&chars, &pchars, pos) {
            Some((a, b, caps)) if a >= pos => {
                out.push_str(&chars[pos..a].iter().collect::<String>());
                let caps_strs = captures_to_strings(&chars, &caps, (a, b));
                let replacement = match &repl {
                    Value::Str(r) => {
                        let rchars: Vec<char> = r.chars().collect();
                        let mut res = String::new();
                        let mut i = 0usize;
                        while i < rchars.len() {
                            if rchars[i] == '%' && i + 1 < rchars.len() {
                                let k = rchars[i + 1];
                                i += 2;
                                if k.is_ascii_digit() {
                                    let idx = k as usize - '0' as usize;
                                    let rep = caps_strs
                                        .get(idx)
                                        .map(|v| match v {
                                            Value::Str(x) => x.to_string(),
                                            other => lua_tostring(other),
                                        })
                                        .unwrap_or_default();
                                    res.push_str(&rep);
                                } else if k == '%' {
                                    res.push('%');
                                } else {
                                    res.push(k);
                                }
                            } else {
                                res.push(rchars[i]);
                                i += 1;
                            }
                        }
                        res
                    }
                    Value::Table(t) => {
                        let key = caps_strs.first().cloned().unwrap_or(Value::Nil);
                        let v = t.borrow().get(&key);
                        if matches!(v, Value::Nil | Value::Boolean(false)) {
                            chars[a..b].iter().collect::<String>()
                        } else {
                            lua_tostring(&v)
                        }
                    }
                    Value::Function(_) | Value::Native(_) => {
                        let vals =
                            interp.call_value(repl.clone(), caps_strs.clone(), "main chunk")?;
                        let v = vals.first().cloned().unwrap_or(Value::Nil);
                        if matches!(v, Value::Nil | Value::Boolean(false)) {
                            chars[a..b].iter().collect::<String>()
                        } else {
                            lua_tostring(&v)
                        }
                    }
                    _ => chars[a..b].iter().collect::<String>(),
                };
                out.push_str(&replacement);
                count += 1;
                pos = if b > a { b } else { a + 1 };
            }
            _ => break,
        }
    }
    out.push_str(&chars[pos.min(chars.len())..].iter().collect::<String>());
    Ok(vec![Value::Str(Rc::new(out)), Value::Integer(count)])
}
