// ---- string library

fn str_len(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "len")?;
    let start = args.get(1).and_then(as_int).unwrap_or(1);
    let end = args.get(2).and_then(as_int).unwrap_or(-1);
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let s_i = if start < 0 { n + start + 1 } else { start };
    let e_i = if end < 0 { n + end + 1 } else { end };
    let s_i = s_i.max(1);
    let e_i = e_i.min(n);
    if s_i > e_i {
        return Ok(vec![Value::Integer(0)]);
    }
    Ok(vec![Value::Integer(e_i - s_i + 1)])
}

fn utf8_sub(s: &str, start: i64, end: i64) -> String {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let mut s_i = if start < 0 { n + start + 1 } else { start };
    let mut e_i = if end < 0 { n + end + 1 } else { end };
    if s_i < 1 {
        s_i = 1;
    }
    if e_i > n {
        e_i = n;
    }
    if s_i > e_i {
        return String::new();
    }
    chars[(s_i - 1) as usize..e_i as usize].iter().collect()
}

fn str_sub(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "sub")?;
    let start = args.get(1).and_then(as_int).unwrap_or(1);
    let end = args.get(2).and_then(as_int).unwrap_or(-1);
    Ok(vec![Value::Str(Rc::new(utf8_sub(&s, start, end)))])
}

fn str_upper(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
