    Ok(vec![Value::Str(Rc::new(
        s.chars().map(|c| c.to_ascii_lowercase()).collect(),
    ))])
}

fn str_rep(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "rep")?;
    let n = match args.get(1) {
        Some(v) => match as_int(v) {
            Some(i) => i,
            None => {
                return Err(interp.error(&arg_error(
                    "rep",
                    1,
                    "number",
                    Some(type_name(v)),
                )))
            }
        },
        None => return Err(interp.error(&arg_error("rep", 1, "number", None))),
    };
    let sep = args.get(2).and_then(|v| match v {
        Value::Str(s) => Some(s.to_string()),
        _ => None,
    });
    if n <= 0 {
        return Ok(vec![Value::Str(Rc::new(String::new()))]);
    }
    let mut out = String::new();
    for i in 0..n {
        if i > 0 {
            if let Some(sep) = &sep {
                out.push_str(sep);
            }
        }
        out.push_str(&s);
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

