        if c != '%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= chars.len() {
            return Err(interp.error("invalid conversion to 'format'"));
        }
        if chars[i] == '%' {
            out.push('%');
            i += 1;
            continue;
        }
        let mut flags = String::new();
        while i < chars.len() && "-+ #0".contains(chars[i]) {
            flags.push(chars[i]);
            i += 1;
        }
        let mut width = String::new();
        while i < chars.len() && chars[i].is_ascii_digit() {
            width.push(chars[i]);
            i += 1;
        }
        let mut precision = String::new();
        if i < chars.len() && chars[i] == '.' {
            i += 1;
            while i < chars.len() && chars[i].is_ascii_digit() {
                precision.push(chars[i]);
                i += 1;
            }
        }
        let spec = chars.get(i).cloned().unwrap_or('%');
        i += 1;
        let width_n = width.parse::<usize>().unwrap_or(0);
        let prec_n = precision.parse::<usize>().unwrap_or(6);
        let left = flags.contains('-');
        let zero = flags.contains('0');
        let plus = flags.contains('+');
        let space = flags.contains(' ');
        let bad = |msg: String| -> Result<Vec<Value>, String> {
            Err(interp.error(&msg))
        };
        let arg = args.get(argi).cloned().unwrap_or(Value::Nil);
        let rendered = match spec {
            'd' | 'i' => {
                argi += 1;
                match as_int(&arg) {
                    Some(v) => {
                        let sign = if v < 0 {
                            "-"
                        } else if plus {
                            "+"
                        } else if space {
                            " "
                        } else {
                            ""
                        };
                        let digits = v.unsigned_abs().to_string();
                        if zero && width_n > digits.len() + sign.len() {
                            let pad = "0".repeat(width_n - digits.len() - sign.len());
                            format!("{sign}{pad}{digits}")
                        } else {
                            format!("{sign}{digits}")
                        }
                    }
                    None => {
                        return bad(arg_error(
                            "format",
                            argi,
                            "number has no integer representation",
                            Some(type_name(&arg)),
                        ))
                    }
                }
            }
            's' => {
                argi += 1;
                let s = match &arg {
                    Value::Str(s) => s.to_string(),
                    other => lua_tostring(other),
                };
                if !precision.is_empty() {
                    s.chars().take(prec_n).collect::<String>()
                } else {
                    s
                }
            }
            'q' => {
                argi += 1;
                match &arg {
                    Value::Str(s) => crate::lua::lua_escape(s),
                    other => lua_tostring(other),
                }
            }
            'f' | 'e' | 'E' | 'g' | 'G' => {
                argi += 1;
                let v = match to_float(&arg) {
                    Some(v) => v,
                    None => {
                        return bad(arg_error(
                            "format",
                            argi,
                            "number",
                            Some(type_name(&arg)),
                        ))
                    }
                };
                match spec {
                    'f' => format!("{:.*}", prec_n, v),
                    'e' | 'E' => {
                        let mut s = format!("{:.*e}", prec_n, v);
                        if let Some(pos) = s.find('e') {
                            let (m, e) = s.split_at(pos);
                            let ev: i32 = e[1..].parse().unwrap_or(0);
                            let sign = if ev < 0 { "-" } else { "+" };
                            s = format!("{m}e{}{:02}", sign, ev.abs());
                            if spec == 'E' {
                                s = s.replace('e', "E");
                            }
                        }
                        s
                    }
                    _ => {
                        let s = crate::lua::format_lua_float(v);
                        if spec == 'G' {
                            s.to_uppercase()
                        } else {
                            s
                        }
                    }
                }
            }
            'x' | 'X' | 'o' | 'u' | 'c' => {
                argi += 1;
                let v = match as_int(&arg) {
                    Some(v) => v,
                    None => {
                        return bad(arg_error(
                            "format",
                            argi,
                            "number has no integer representation",
                            Some(type_name(&arg)),
                        ))
                    }
                };
                match spec {
                    'x' => format!("{v:x}"),
                    'X' => format!("{v:X}"),
                    'o' => format!("{v:o}"),
                    'u' => format!("{}", v as u64),
                    _ => (v as u32 as u8 as char).to_string(),
                }
            }
            other => {
                return bad(format!("invalid conversion '%{other}' to 'format'"));
            }
        };
        if width_n > rendered.chars().count() {
            let pad_char = if zero && spec != 's' { '0' } else { ' ' };
            let pad = pad_char
                .to_string()
                .repeat(width_n - rendered.chars().count());
            if left {
                out.push_str(&rendered);
                out.push_str(&pad);
            } else {
                out.push_str(&pad);
                out.push_str(&rendered);
            }
        } else {
            out.push_str(&rendered);
        }
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

/// Finds the leftmost match of `p` in `s` starting at or after `init`.
fn pattern_find(
    s: &[char],
    p: &[char],
    init: usize,
) -> Option<(usize, usize, Vec<(usize, usize)>)> {
    let anchored = p.first() == Some(&'^');
    let pstart = if anchored { 1 } else { 0 };
    let mut start = init;
    loop {
        if start > s.len() {
            return None;
        }
        let mut caps: Vec<(usize, usize)> = Vec::new();
        if let Some(end) = match_here(s, p, pstart, start, &mut caps) {
            return Some((start, end, caps));
        }
        if anchored {
            return None;
        }
        start += 1;
    }
}

fn captures_to_strings(
    s: &[char],
    caps: &[(usize, usize)],
    whole: (usize, usize),
) -> Vec<Value> {
    let mut out = Vec::new();
    if caps.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
        return out;
    }
    for (a, b) in caps {
        if *b == usize::MAX {
            continue;
        }
        let text: String = s[*a..*b].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    if out.is_empty() {
        let text: String = s[whole.0..whole.1].iter().collect();
        out.push(Value::Str(Rc::new(text)));
    }
    out
}

fn str_find(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "find")?;
    let pat = str_arg(interp, &args, 1, "find")?;
    let init = match args.get(2) {
        Some(v) => match as_int(v) {
            Some(i) => i,
            None => {
                return Err(interp.error(&arg_error(
                    "find",
                    2,
                    "number",
                    Some(type_name(v)),
                )))
            }
        },
        None => 1,
    };
    let plain = matches!(args.get(3), Some(Value::Boolean(true)));
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len() as i64;
    let init = if init < 0 { (n + init + 1).max(1) } else { init };
    let init = (init - 1).max(0) as usize;
    if plain {
        let pchars: Vec<char> = pat.chars().collect();
        let mut i = init;
        while i + pchars.len() <= chars.len() {
            if chars[i..i + pchars.len()] == pchars[..] {
                return Ok(vec![
                    Value::Integer(i as i64 + 1),
                    Value::Integer((i + pchars.len()) as i64),
                ]);
            }
            i += 1;
        }
        return Ok(vec![Value::Nil]);
    }
    let pchars: Vec<char> = pat.chars().collect();
    match pattern_find(&chars, &pchars, init) {
        Some((a, b, caps)) => {
            let mut out = vec![Value::Integer(a as i64 + 1), Value::Integer(b as i64)];
            out.extend(captures_to_strings(&chars, &caps, (a, b)));
            Ok(out)
        }
        None => Ok(vec![Value::Nil]),
    }
}

fn str_match(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let s = str_arg(interp, &args, 0, "match")?;
    let pat = str_arg(interp, &args, 1, "match")?;
    let init = args.get(2).and_then(as_int).unwrap_or(1);
    let chars: Vec<char> = s.chars().collect();
