    };
    for (i, a) in args.iter().enumerate().skip(1) {
        if matches!(cmp_lua(interp, a, &best)?, std::cmp::Ordering::Greater) {
            best = a.clone();
        }
        let _ = i;
    }
    Ok(vec![best])
}

