fn rebuild_index(t: &Rc<RefCell<Table>>) {
    let entries = t.borrow().entries.clone();
    let mut index = std::collections::HashMap::new();
    for (i, (k, _)) in entries.iter().enumerate() {
        index.insert(key_key(k), i);
    }
    t.borrow_mut().index = index;
}

fn table_insert(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "insert")?;
    if args.len() == 3 {
        let pos = match args.get(1) {
            Some(v) => match as_int(v) {
                Some(i) => i,
                None => {
                    return Err(interp.error(&arg_error(
                        "insert",
                        1,
                        "number",
                        Some(type_name(v)),
                    )))
                }
            },
            None => {
                return Err(interp.error(&arg_error("insert", 1, "number", None)));
            }
        };
        let value = args[2].clone();
        let len = t.borrow().length();
        let p = if pos < 0 { len + pos + 2 } else { pos };
        if p < 1 || p > len + 1 {
            return Err(interp.error("bad argument #2 to 'insert' (position out of bounds)"));
        }
        let mut i = len;
        while i >= p {
            let v = t.borrow().get(&Value::Integer(i));
            t.borrow_mut().set(Value::Integer(i + 1), v);
            i -= 1;
        }
        t.borrow_mut().set(Value::Integer(p), value);
    } else if args.len() == 2 {
        let value = args[1].clone();
        let len = t.borrow().length();
        t.borrow_mut().set(Value::Integer(len + 1), value);
    } else {
        return Err(interp.error("wrong number of arguments to 'insert'"));
    }
    rebuild_index(&t);
    Ok(vec![])
}

fn table_remove(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "remove")?;
    let len = t.borrow().length();
    let pos = match args.get(1) {
        Some(v) => match as_int(v) {
            Some(i) => i,
            None => {
                return Err(interp.error(&arg_error(
                    "remove",
                    1,
                    "number",
                    Some(type_name(v)),
                )))
            }
        },
        None => len,
    };
    if len == 0 || pos < 1 || pos > len {
        return Ok(vec![Value::Nil]);
    }
    let v = t.borrow().get(&Value::Integer(pos));
    let mut i = pos;
    while i < len {
        let nv = t.borrow().get(&Value::Integer(i + 1));
        t.borrow_mut().set(Value::Integer(i), nv);
        i += 1;
    }
    t.borrow_mut().set(Value::Integer(len), Value::Nil);
    rebuild_index(&t);
    Ok(vec![v])
}

fn table_concat(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "concat")?;
    let sep = match args.get(1) {
        Some(v) => match v {
            Value::Str(s) => Some(s.to_string()),
            Value::Integer(i) => Some(i.to_string()),
            Value::Float(f) => Some(format_lua_float(*f)),
            Value::Nil => None,
            other => {
                return Err(interp.error(&arg_error(
                    "concat",
                    1,
                    "string",
                    Some(type_name(other)),
                )))
            }
        },
        None => None,
    };
    let start = args.get(2).and_then(as_int).unwrap_or(1);
    let end = args
        .get(3)
        .and_then(as_int)
        .unwrap_or_else(|| t.borrow().length());
    let mut out = String::new();
    let mut i = start;
    while i <= end {
        if i > start {
            if let Some(s) = &sep {
                out.push_str(s);
            }
        }
        let v = t.borrow().get(&Value::Integer(i));
        match &v {
            Value::Str(s) => out.push_str(s),
            Value::Integer(x) => out.push_str(&x.to_string()),
            Value::Float(x) => out.push_str(&format_lua_float(*x)),
            other => {
                return Err(interp.error(&format!(
                    "invalid value ({}) at index {} in table for 'concat'",
                    lua_tostring(other),
                    i
                )))
            }
        }
        i += 1;
    }
    Ok(vec![Value::Str(Rc::new(out))])
}

fn table_sort(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "sort")?;
    let len = t.borrow().length();
    let mut items: Vec<Value> = Vec::new();
    for i in 1..=len {
        items.push(t.borrow().get(&Value::Integer(i)));
    }
    if let Some(cmp) = args.get(1).cloned() {
        let mut sorted = items;
        for i in 1..sorted.len() {
            let mut j = i;
            while j > 0 {
                let res = interp.call_value(
                    cmp.clone(),
                    vec![sorted[j - 1].clone(), sorted[j].clone()],
                    "main chunk",
                )?;
                if truthy(res.first().unwrap_or(&Value::Nil)) {
                    sorted.swap(j - 1, j);
                    j -= 1;
                } else {
                    break;
                }
            }
        }
        items = sorted;
    } else {
        let mut err: Option<String> = None;
        items.sort_by(|a, b| match cmp_lua(interp, a, b) {
            Ok(o) => o,
            Err(e) => {
                if err.is_none() {
                    err = Some(e);
                }
                std::cmp::Ordering::Equal
            }
        });
        if let Some(e) = err {
            return Err(e);
        }
    }
    for (i, v) in items.iter().enumerate() {
        t.borrow_mut().set(Value::Integer(i as i64 + 1), v.clone());
    }
    rebuild_index(&t);
    Ok(vec![])
}

fn table_unpack(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "unpack")?;
    let len = t.borrow().length();
    let start = args.get(1).and_then(as_int).unwrap_or(1);
    let end = args.get(2).and_then(as_int).unwrap_or(len);
    let mut out = Vec::new();
    let mut i = start;
    while i <= end {
        out.push(t.borrow().get(&Value::Integer(i)));
        i += 1;
    }
    Ok(out)
}

fn table_pack(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    let t = Rc::new(RefCell::new(Table::new()));
    for (i, v) in args.iter().enumerate() {
        t.borrow_mut().set(Value::Integer(i as i64 + 1), v.clone());
    }
    t.borrow_mut().set(
        Value::Str(Rc::new("n".to_string())),
        Value::Integer(args.len() as i64),
    );
    Ok(vec![Value::Table(t)])
}

fn table_move(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let src = table_arg(interp, &args, 0, "move")?;
    let f = args.get(1).and_then(as_int).unwrap_or(1);
    let t_end = args.get(2).and_then(as_int).unwrap_or(0);
    let dst_idx = args.get(3).and_then(as_int).unwrap_or(1);
    let dst = match args.get(4) {
        Some(Value::Table(t)) => t.clone(),
        _ => src.clone(),
    };
    let mut i = f;
    let mut k = dst_idx;
    while i <= t_end {
        let v = src.borrow().get(&Value::Integer(i));
        dst.borrow_mut().set(Value::Integer(k), v);
        i += 1;
        k += 1;
    }
    Ok(vec![Value::Table(dst)])
}

