fn cmp_lua(interp: &Interp, a: &Value, b: &Value) -> Result<std::cmp::Ordering, String> {
    let ok_pair = |x: &Value, y: &Value| match (x, y) {
        (Value::Integer(_) | Value::Float(_), Value::Integer(_) | Value::Float(_)) => true,
        (Value::Str(_), Value::Str(_)) => true,
        _ => false,
    };
    if !ok_pair(a, b) {
        let msg = match (type_name(a), type_name(b)) {
            ("nil", "nil") => "attempt to compare two nil values".to_string(),
            (x, y) if x == y => format!("attempt to compare two {x} values"),
            (x, y) => format!("attempt to compare {x} with {y}"),
        };
        return Err(interp.error_with(&["[C]: in metamethod 'lt'".to_string()], &msg));
    }
    Ok(match (a, b) {
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        _ => {
            let x = xf(&number_of(a).unwrap());
            let y = xf(&number_of(b).unwrap());
            x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal)
        }
    })
}

fn math_max(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let mut best = match args.first() {
        Some(v) => v.clone(),
        None => return Err(interp.error(&arg_error("max", 0, "", None))),
    };
    for (i, a) in args.iter().enumerate().skip(1) {
        if matches!(cmp_lua(interp, a, &best)?, std::cmp::Ordering::Greater) {
            best = a.clone();
        }
        let _ = i;
    }
    Ok(vec![best])
}

