        items = sorted;
    } else {
        let mut err: Option<String> = None;
        items.sort_by(|a, b| match cmp_lua(interp, a, b) {
            Ok(o) => o,
            Err(e) => {
                if err.is_none() {
                    err = Some(e);
                }
                std::cmp::Ordering::Equal
            }
        });
        if let Some(e) = err {
            return Err(e);
        }
    }
    for (i, v) in items.iter().enumerate() {
        t.borrow_mut().set(Value::Integer(i as i64 + 1), v.clone());
    }
    rebuild_index(&t);
    Ok(vec![])
}

fn table_unpack(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "unpack")?;
