// ---- table library

fn rebuild_index(t: &Rc<RefCell<Table>>) {
    let entries = t.borrow().entries.clone();
    let mut index = std::collections::HashMap::new();
    for (i, (k, _)) in entries.iter().enumerate() {
        index.insert(key_key(k), i);
    }
    t.borrow_mut().index = index;
}

fn table_insert(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "insert")?;
    if args.len() == 3 {
        let pos = match args.get(1) {
            Some(v) => match as_int(v) {
                Some(i) => i,
                None => {
                    return Err(interp.error(&arg_error(
                        "insert",
                        1,
                        "number",
                        Some(type_name(v)),
                    )))
                }
            },
            None => {
                return Err(interp.error(&arg_error("insert", 1, "number", None)));
            }
        };
        let value = args[2].clone();
        let len = t.borrow().length();
        let p = if pos < 0 { len + pos + 2 } else { pos };
        if p < 1 || p > len + 1 {
            return Err(interp.error("bad argument #2 to 'insert' (position out of bounds)"));
        }
        let mut i = len;
        while i >= p {
            let v = t.borrow().get(&Value::Integer(i));
            t.borrow_mut().set(Value::Integer(i + 1), v);
            i -= 1;
        }
        t.borrow_mut().set(Value::Integer(p), value);
    } else if args.len() == 2 {
        let value = args[1].clone();
        let len = t.borrow().length();
        t.borrow_mut().set(Value::Integer(len + 1), value);
    } else {
        return Err(interp.error("wrong number of arguments to 'insert'"));
    }
    rebuild_index(&t);
    Ok(vec![])
}

fn table_remove(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let t = table_arg(interp, &args, 0, "remove")?;
    let len = t.borrow().length();
    let pos = match args.get(1) {
        Some(v) => match as_int(v) {
            Some(i) => i,
            None => {
                return Err(interp.error(&arg_error(
                    "remove",
                    1,
                    "number",
                    Some(type_name(v)),
                )))
            }
        },
        None => len,
    };
    if len == 0 || pos < 1 || pos > len {
        return Ok(vec![Value::Nil]);
    }
    let v = t.borrow().get(&Value::Integer(pos));
    let mut i = pos;
    while i < len {
        let nv = t.borrow().get(&Value::Integer(i + 1));
        t.borrow_mut().set(Value::Integer(i), nv);
        i += 1;
    }
    t.borrow_mut().set(Value::Integer(len), Value::Nil);
    rebuild_index(&t);
    Ok(vec![v])
}

fn table_concat(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
