                    sorted.swap(j - 1, j);
                    j -= 1;
                } else {
                    break;
                }
            }
        }
        items = sorted;
    } else {
        let mut err: Option<String> = None;
        items.sort_by(|a, b| match cmp_lua(interp, a, b) {
            Ok(o) => o,
            Err(e) => {
                if err.is_none() {
                    err = Some(e);
                }
                std::cmp::Ordering::Equal
            }
