fn os_clock(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = (interp, args);
    Ok(vec![Value::Float(0.0)])
}

fn os_date(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let fmt = match args.first() {
        Some(v) => match v {
            Value::Str(s) => s.to_string(),
            other => lua_tostring(other),
        },
        None => "%c".to_string(),
    };
    let secs = args
        .get(1)
        .and_then(as_int)
        .unwrap_or_else(|| crate::now_seconds() as i64);
    let text = crate::format_date(&fmt, secs);
    Ok(vec![Value::Str(Rc::new(text))])
}

fn os_getenv(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let name = str_arg(interp, &args, 0, "getenv")?;
    Ok(match std::env::var(&name) {
        Ok(v) => vec![Value::Str(Rc::new(v))],
        Err(_) => vec![Value::Nil],
    })
}

fn io_write(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    let mut out = String::new();
    for a in &args {
        out.push_str(&lua_tostring(a));
    }
    print!("{out}");
    let _ = std::io::stdout().flush();
    Ok(vec![])
}

fn io_read(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    let what = args.first().map(|v| match v {
        Value::Str(s) => s.to_string(),
        other => lua_tostring(other),
    });
    match what.as_deref() {
        Some("a") | Some("*a") => {
            let mut buf = String::new();
            let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut buf);
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        _ => {
            let mut line = String::new();
            let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut line);
            Ok(vec![Value::Str(Rc::new(line))])
        }
    }
}

fn io_lines(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = (interp, args);
    Ok(vec![Value::Nil])
}
