// ---- lua pattern matching

fn class_match(c: char, class: char) -> bool {
    match class {
        'a' => c.is_alphabetic(),
        'c' => c.is_control(),
        'd' => c.is_ascii_digit(),
        'l' => c.is_ascii_lowercase(),
        'p' => c.is_ascii_punctuation(),
        's' => c.is_whitespace(),
        'u' => c.is_ascii_uppercase(),
        'w' => c.is_ascii_alphanumeric() || c == '_',
        'x' => c.is_ascii_hexdigit(),
        'A' => !c.is_alphabetic(),
        'C' => !c.is_control(),
        'D' => !c.is_ascii_digit(),
        'L' => !c.is_ascii_lowercase(),
        'P' => !c.is_ascii_punctuation(),
        'S' => !c.is_whitespace(),
        'U' => !c.is_ascii_uppercase(),
        'W' => !(c.is_ascii_alphanumeric() || c == '_'),
        'X' => !c.is_ascii_hexdigit(),
        other => c == other,
    }
}

enum Class {
    Any,
    Single(char),
    Neg(char),
    Set(Vec<(char, char)>, bool),
}

impl Class {
    fn matches(&self, c: char) -> bool {
        match self {
            Class::Any => true,
            Class::Single(x) => *x == c,
            Class::Neg(x) => *x != c,
            Class::Set(ranges, negated) => {
                let mut m = false;
                for (a, b) in ranges {
                    if c >= *a && c <= *b {
                        m = true;
                        break;
                    }
                }
                if *negated {
                    !m
                } else {
                    m
                }
            }
        }
    }
}

/// A single pattern item with the number of pattern characters it consumes.
struct Item {
    len: usize,
    class: Class,
}

impl Item {
    fn matches(&self, c: char) -> bool {
        self.class.matches(c)
    }
}

fn parse_item(p: &[char], pi: usize) -> Option<Item> {
    let c = p[pi];
    match c {
        '.' => Some(Item {
            len: 1,
            class: Class::Any,
        }),
        '%' => {
            let k = *p.get(pi + 1)?;
            match k {
                'a' | 'c' | 'd' | 'l' | 'p' | 's' | 'u' | 'w' | 'x' => Some(Item {
                    len: 2,
                    class: Class::Single(k),
                }),
                'A' | 'C' | 'D' | 'L' | 'P' | 'S' | 'U' | 'W' | 'X' => Some(Item {
                    len: 2,
                    class: Class::Neg(k),
                }),
                _ => Some(Item {
                    len: 2,
                    class: Class::Single(k),
                }),
            }
        }
        '[' => {
            let mut i = pi + 1;
            let negated = if p.get(i) == Some(&'^') {
                i += 1;
                true
            } else {
                false
            };
            let mut ranges: Vec<(char, char)> = Vec::new();
            let mut singles: Vec<char> = Vec::new();
            let mut first = true;
            while i < p.len() {
                if p[i] == ']' && !first {
                    break;
                }
                first = false;
                if p[i] == '%' && i + 1 < p.len() {
                    let k = p[i + 1];
                    if "acdlpsuwx".contains(k) {
                        singles.push(k);
                    } else if "ACDLPSUWX".contains(k) {
                        // negated classes inside sets are approximated
                        singles.push(k);
                    } else {
                        ranges.push((k, k));
                    }
                    i += 2;
                    continue;
                }
                if i + 2 < p.len() && p[i + 1] == '-' && p[i + 2] != ']' {
                    ranges.push((p[i], p[i + 2]));
                    i += 3;
                    continue;
                }
                ranges.push((p[i], p[i]));
                i += 1;
            }
            Some(Item {
                len: i + 1 - pi,
                class: Class::Set(ranges, negated),
            })
        }
        other => Some(Item {
            len: 1,
            class: Class::Single(other),
        }),
    }
}

fn match_here(
    s: &[char],
    p: &[char],
    pi: usize,
    si: usize,
    caps: &mut Vec<(usize, usize)>,
) -> Option<usize> {
    if pi >= p.len() {
        return Some(si);
    }
    match p[pi] {
        ')' => Some(si),
        '(' => {
            let mut depth = 1;
            let mut j = pi + 1;
            while j < p.len() && depth > 0 {
                match p[j] {
                    '(' => depth += 1,
                    ')' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if depth != 0 {
                return None;
            }
            let cap_start = caps.len();
            caps.push((si, usize::MAX));
            let end = match_here(s, p, j + 1, si, caps);
            match end {
                Some(e) => {
                    caps[cap_start] = (si, e);
                    Some(e)
                }
                None => {
                    caps.truncate(cap_start);
                    None
                }
            }
        }
        '$' if pi + 1 == p.len() => {
            if si == s.len() {
                Some(si)
            } else {
                None
