        if matched {
            let (a, b, caps) = m.unwrap();
            count += 1;
            out.push_str(&chars[src..a].iter().collect::<String>());
            let caps_strs = captures_to_strings(&chars, &caps, (a, b));
            let replacement = match &repl {
                Value::Str(r) => {
                    let rchars: Vec<char> = r.chars().collect();
                    let mut res = String::new();
                    let mut i = 0usize;
