                        if rchars[i] == '%' && i + 1 < rchars.len() {
                            let k = rchars[i + 1];
                            i += 2;
                            if k == '0' {
                                res.push_str(&chars[a..b].iter().collect::<String>());
                            } else if k.is_ascii_digit() {
                                let idx = k as usize - '1' as usize;
                                let rep = caps_strs
                                    .get(idx)
                                    .map(|v| match v {
                                        Value::Str(x) => x.to_string(),
                                        other => lua_tostring(other),
                                    })
                                    .unwrap_or_default();
                                res.push_str(&rep);
                            } else if k == '%' {
                                res.push('%');
                            } else {
                                res.push(k);
                            }
                        } else {
                            res.push(rchars[i]);
                            i += 1;
                        }
                    }
                    res
                }
                Value::Table(t) => {
                    let key = caps_strs.first().cloned().unwrap_or(Value::Nil);
                    let v = t.borrow().get(&key);
                    if matches!(v, Value::Nil | Value::Boolean(false)) {
                        chars[a..b].iter().collect::<String>()
                    } else {
                        lua_tostring(&v)
                    }
                }
                Value::Function(_) | Value::Native(_) => {
                    let vals = interp.call_value(repl.clone(), caps_strs.clone(), "main chunk")?;
                    let v = vals.first().cloned().unwrap_or(Value::Nil);
