                break;
            }
            out.push(chars[src]);
            src += 1;
        }
    }
    if src < chars.len() {
        out.push_str(&chars[src..].iter().collect::<String>());
    }
    Ok(vec![Value::Str(Rc::new(out)), Value::Integer(count)])
}
'''
