// ---- extra math library functions

fn math_1f(interp: &mut Interp, args: Vec<Value>, fname: &str, f: fn(f64) -> f64) -> Result<Vec<Value>, String> {
    let v = num_arg(interp, &args, 0, fname, "number")?;
    Ok(vec![Value::Float(f(v))])
}

fn math_atan2(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let a = num_arg(interp, &args, 0, "atan2", "number")?;
    let b = num_arg(interp, &args, 1, "atan2", "number")?;
    Ok(vec![Value::Float(a.atan2(b))])
}
fn math_cosh(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "cosh", f64::cosh)
}
fn math_sinh(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "sinh", f64::sinh)
}
fn math_tanh(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "tanh", f64::tanh)
}
fn math_deg(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "deg", |v| v * 180.0 / std::f64::consts::PI)
}
fn math_rad(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "rad", |v| v * std::f64::consts::PI / 180.0)
}
fn math_frexp(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let v = num_arg(interp, &args, 0, "frexp", "number")?;
    if v == 0.0 || !v.is_finite() {
        return Ok(vec![Value::Float(v), Value::Integer(0)]);
    }
    let e = v.abs().log2().floor() as i32 + 1;
    let m = v / (2f64).powi(e);
    Ok(vec![Value::Float(m), Value::Integer(e as i64)])
}
fn math_ldexp(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let a = num_arg(interp, &args, 0, "ldexp", "number")?;
    let b = num_arg(interp, &args, 1, "ldexp", "number")?;
    Ok(vec![Value::Float(a * (2f64).powi(b as i32))])
}
fn math_log10(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    math_1f(interp, args, "log10", f64::log10)
}
fn math_modf(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let v = num_arg(interp, &args, 0, "modf", "number")?;
    let i = v.trunc();
    let f = v - i;
    Ok(vec![
        if i.fract() == 0.0 && i >= i64::MIN as f64 && i <= i64::MAX as f64 {
            Value::Integer(i as i64)
        } else {
            Value::Float(i)
        },
        Value::Float(f),
    ])
}
fn math_pow(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let a = num_arg(interp, &args, 0, "pow", "number")?;
    let b = num_arg(interp, &args, 1, "pow", "number")?;
    Ok(vec![Value::Float(a.powf(b))])
}
