// ---- extra os / io library functions

fn os_difftime(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    let a = args.first().and_then(as_int).unwrap_or(0);
    let b = args.get(1).and_then(as_int).unwrap_or(0);
    Ok(vec![Value::Float((a - b) as f64)])
}

fn os_execute(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    match args.first() {
        None => Ok(vec![Value::Integer(1)]),
        Some(cmd) => {
            let c = lua_tostring(cmd);
            match std::process::Command::new("sh").arg("-c").arg(&c).status() {
                Ok(status) => {
                    if status.success() {
                        Ok(vec![Value::Boolean(true)])
                    } else {
                        Ok(vec![Value::Nil])
                    }
                }
                Err(_) => Ok(vec![Value::Nil]),
            }
        }
    }
}

fn os_remove(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let name = str_arg(interp, &args, 0, "remove")?;
    match std::fs::remove_file(&name) {
        Ok(_) => Ok(vec![Value::Boolean(true)]),
        Err(e) => Ok(vec![Value::Nil, Value::Str(Rc::new(name)), Value::Str(Rc::new(e.to_string()))]),
    }
}

fn os_rename(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let a = str_arg(interp, &args, 0, "rename")?;
    let b = str_arg(interp, &args, 1, "rename")?;
    match std::fs::rename(&a, &b) {
        Ok(_) => Ok(vec![Value::Boolean(true)]),
        Err(e) => Ok(vec![Value::Nil, Value::Str(Rc::new(e.to_string()))]),
    }
}

fn os_setlocale(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = (interp, args);
    Ok(vec![Value::Str(Rc::new("C".to_string()))])
}

fn os_tmpname(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = (interp, args);
    Ok(vec![Value::Str(Rc::new("/tmp/fblog_tmp".to_string()))])
}

fn os_exit(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let code = args.first().and_then(as_int).unwrap_or(0);
    std::process::exit(code as i32);
}

fn io_type_fn(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = interp;
    match args.first() {
        Some(Value::Table(_)) => Ok(vec![Value::Str(Rc::new("file".to_string()))]),
        Some(Value::Nil) => Ok(vec![Value::Nil]),
        _ => Ok(vec![Value::Nil]),
    }
}

fn io_stub(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    let _ = (interp, args);
    Ok(vec![Value::Nil])
}

fn io_write_fn(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    io_write(interp, args)
}

fn io_read_fn(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    io_read(interp, args)
}

fn io_lines_fn(interp: &mut Interp, args: Vec<Value>) -> Result<Vec<Value>, String> {
    io_lines(interp, args)
}
